class Solution:
    def canTransform(self, start: str, result: str) -> bool:
        # Extract the non-X characters and their positions for both strings
        s_chars = []
        s_indices = []
        for idx, c in enumerate(start):
            if c in {'L', 'R'}:
                s_chars.append(c)
                s_indices.append(idx)

        r_chars = []
        r_indices = []
        for idx, c in enumerate(result):
            if c in {'L', 'R'}:
                r_chars.append(c)
                r_indices.append(idx)

        # Check if the sequences of non-X characters are the same
        if s_chars != r_chars:
            return False

        # Check positions for each corresponding pair
        n = len(s_chars)
        for i in range(n):
            char = s_chars[i]
            start_pos = s_indices[i]
            end_pos = r_indices[i]
            if char == 'L':
                if end_pos > start_pos:
                    return False
            elif char == 'R':
                if end_pos < start_pos:
                    return False
        return True

class Solution:
    def swimInWater(self, grid: List[List[int]]) -> int:
        def find(x):
            if p[x] != x:
                p[x] = find(p[x])
            return p[x]

        n = len(grid)
        p = list(range(n * n))
        hi = [0] * (n * n)
        for i, row in enumerate(grid):
            for j, h in enumerate(row):
                hi[h] = i * n + j
        for t in range(n * n):
            i, j = hi[t] // n, hi[t] % n
            for a, b in [(0, -1), (0, 1), (1, 0), (-1, 0)]:
                x, y = i + a, j + b
                if 0 <= x < n and 0 <= y < n and grid[x][y] <= t:
                    p[find(x * n + y)] = find(hi[t])
                if find(0) == find(n * n - 1):
                    return t
        return -1

class Solution:
    def kthGrammar(self, n: int, k: int) -> int:
        if n == 1:
            return 0
        if k <= (1 << (n - 2)):
            return self.kthGrammar(n - 1, k)
        return self.kthGrammar(n - 1, k - (1 << (n - 2))) ^ 1

class Solution:
    def reachingPoints(self, sx: int, sy: int, tx: int, ty: int) -> bool:
        while tx > sx and ty > sy and tx != ty:
            if tx > ty:
                tx %= ty
            else:
                ty %= tx
        if tx == sx and ty == sy:
            return True
        if tx == sx:
            return ty > sy and (ty - sy) % tx == 0
        if ty == sy:
            return tx > sx and (tx - sx) % ty == 0
        return False

