class Solution:
    def minSwap(self, nums1: List[int], nums2: List[int]) -> int:
        a, b = 0, 1
        for i in range(1, len(nums1)):
            x, y = a, b
            if nums1[i - 1] >= nums1[i] or nums2[i - 1] >= nums2[i]:
                a, b = y, x + 1
            else:
                b = y + 1
                if nums1[i - 1] < nums2[i] and nums2[i - 1] < nums1[i]:
                    a, b = min(a, y), min(b, x + 1)
        return min(a, b)

class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        rg = defaultdict(list)
        indeg = [0] * len(graph)
        for i, vs in enumerate(graph):
            for j in vs:
                rg[j].append(i)
            indeg[i] = len(vs)
        q = deque([i for i, v in enumerate(indeg) if v == 0])
        while q:
            i = q.popleft()
            for j in rg[i]:
                indeg[j] -= 1
                if indeg[j] == 0:
                    q.append(j)
        return [i for i, v in enumerate(indeg) if v == 0]

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m = len(grid)
        if m == 0:
            return []
        n = len(grid[0])
        n_cols = n
        virtual = m * n
        grid_copy = [row[:] for row in grid]
        is_brick = [False] * len(hits)

        for i in range(len(hits)):
            x, y = hits[i]
            if grid[x][y] == 1:
                is_brick[i] = True
                grid_copy[x][y] = 0  # Mark the hit as removed initially

        # DSU class definition
        class DSU:
            def __init__(self, size):
                self.parent = list(range(size + 1))
                self.size = [1] * (size + 1)

            def find(self, x):
                if self.parent[x] != x:
                    self.parent[x] = self.find(self.parent[x])
                return self.parent[x]

            def union(self, x, y):
                x_root = self.find(x)
                y_root = self.find(y)
                if x_root == y_root:
                    return
                if self.size[x_root] < self.size[y_root]:
                    x_root, y_root = y_root, x_root
                self.parent[y_root] = x_root
                self.size[x_root] += self.size[y_root]

        dsu = DSU(m * n)

        # Initialize the DSU based on the modified grid (grid_copy)
        for i in range(m):
            for j in range(n):
                if grid_copy[i][j] == 1:
                    current = i * n_cols + j
                    if i == 0:
                        dsu.union(current, virtual)
                    # Check left
                    if j > 0 and grid_copy[i][j - 1] == 1:
                        left = current - 1
                        dsu.union(current, left)
                    # Check above
                    if i > 0 and grid_copy[i - 1][j] == 1:
                        above = (i - 1) * n_cols + j
                        dsu.union(current, above)

        res = []
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for idx in reversed(range(len(hits))):
            hit = hits[idx]
            x, y = hit
            if not is_brick[idx]:
                res.append(0)
                continue
            cell_id = x * n_cols + y
            grid_copy[x][y] = 1  # Re-add the brick

            initial_size = dsu.size[dsu.find(virtual)]

            current = cell_id
            # Union with the virtual node if in the first row
            if x == 0:
                dsu.union(current, virtual)

            # Check all four directions
            for dx, dy in directions:
                nx = x + dx
                ny = y + dy
                if 0 <= nx < m and 0 <= ny < n:
                    if grid_copy[nx][ny] == 1:
                        neighbor_id = nx * n_cols + ny
                        dsu.union(current, neighbor_id)

            final_size = dsu.size[dsu.find(virtual)]
            delta = final_size - initial_size
            cnt = delta - 1 if delta > 0 else 0
            res.append(cnt)

        # Reverse the result to match the original hits order
        return res[::-1]

class Solution:
    def splitArraySameAverage(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return False
        s = sum(nums)
        for i, v in enumerate(nums):
            nums[i] = v * n - s
        m = n >> 1
        vis = set()
        for i in range(1, 1 << m):
            t = sum(v for j, v in enumerate(nums[:m]) if i >> j & 1)
            if t == 0:
                return True
            vis.add(t)
        for i in range(1, 1 << (n - m)):
            t = sum(v for j, v in enumerate(nums[m:]) if i >> j & 1)
            if t == 0 or (i != (1 << (n - m)) - 1 and -t in vis):
                return True
        return False

