class Solution:
    def getBiggestThree(self, grid: List[List[int]]) -> List[int]:
        m = len(grid)
        n = len(grid[0]) if m > 0 else 0
        all_sums = set()

        for i in range(m):
            for j in range(n):
                # Calculate the maximum possible k for current center (i,j)
                max_k = min(i, (m - 1 - i), j, (n - 1 - j))
                for k in range(0, max_k + 1):
                    if k == 0:
                        all_sums.add(grid[i][j])
                    else:
                        points = set()
                        # Edge1: from (i -k, j) to (i, j +k)
                        for t in range(0, k + 1):
                            x = i - k + t
                            y = j + t
                            points.add((x, y))
                        # Edge2: from (i, j +k) to (i +k, j)
                        for t in range(0, k + 1):
                            x = i + t
                            y = j + k - t
                            points.add((x, y))
                        # Edge3: from (i +k, j) to (i, j -k)
                        for t in range(0, k + 1):
                            x = i + k - t
                            y = j - t
                            points.add((x, y))
                        # Edge4: from (i, j -k) to (i -k, j)
                        for t in range(0, k + 1):
                            x = i - t
                            y = j - k + t
                            points.add((x, y))
                        # Calculate the sum for this rhombus
                        current_sum = 0
                        for (x, y) in points:
                            current_sum += grid[x][y]
                        all_sums.add(current_sum)

        # Convert to a sorted list in descending order
        sorted_sums = sorted(all_sums, reverse=True)
        result = []
        for num in sorted_sums:
            if len(result) < 3:
                result.append(num)
            else:
                break
        return result

class Solution:
    def minimumXORSum(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums2)
        f = [[inf] * (1 << n) for _ in range(n + 1)]
        f[0][0] = 0
        for i, x in enumerate(nums1, 1):
            for j in range(1 << n):
                for k in range(n):
                    if j >> k & 1:
                        f[i][j] = min(f[i][j], f[i - 1][j ^ (1 << k)] + (x ^ nums2[k]))
        return f[-1][-1]

