class Solution:
    def minimumBuckets(self, hamsters: str) -> int:
        n = len(hamsters)
        buckets_needed = 0
        last_bucket = -2  # Initialize to an invalid position

        for i in range(n):
            if hamsters[i] == 'H':
                # Check if the previous bucket is already to the left of this H
                if last_bucket == i - 1:
                    continue  # Already covered by the previous bucket

                # Try to place a bucket to the right first
                if i + 1 < n and hamsters[i+1] == '.':
                    buckets_needed += 1
                    last_bucket = i + 1
                else:
                    # Try to place to the left
                    if i - 1 >= 0 and hamsters[i-1] == '.':
                        buckets_needed += 1
                        last_bucket = i - 1
                    else:
                        # Cannot place a bucket, impossible
                        return -1
            # Else, do nothing for '.' positions

        return buckets_needed

