class Solution:
    def getWordsInLongestSubsequence(self, words: List[str], groups: List[int]) -> List[str]:
        n = len(words)
        if n == 0:
            return []
        lengths = [len(word) for word in words]
        dp = [(1, -1) for _ in range(n)]
        max_len = 1
        best_idx = 0

        for i in range(n):
            for j in range(i):
                if groups[i] != groups[j] and lengths[i] == lengths[j]:
                    s = words[j]
                    t = words[i]
                    diff = 0
                    for a, b in zip(s, t):
                        if a != b:
                            diff += 1
                            if diff > 1:
                                break
                    if diff == 1:
                        if dp[j][0] + 1 > dp[i][0]:
                            dp[i] = (dp[j][0] + 1, j)
            if dp[i][0] > max_len:
                max_len = dp[i][0]
                best_idx = i

        path = []
        current = best_idx
        while current != -1:
            path.append(current)
            current = dp[current][1]
        path = path[::-1]
        return [words[i] for i in path]

class Solution:
    def countSubMultisets(self, nums: List[int], l: int, r: int) -> int:
        kMod = 1_000_000_007
        # dp[i] := # of submultisets of nums with sum i
        dp = [1] + [0] * r
        count = collections.Counter(nums)
        zeros = count.pop(0, 0)

        for num, freq in count.items():
            # stride[i] := dp[i] + dp[i - num] + dp[i - 2 * num] + ...
            stride = dp.copy()
            for i in range(num, r + 1):
                stride[i] += stride[i - num]
            for i in range(r, 0, -1):
                if i >= num * (freq + 1):
                    # dp[i] + dp[i - num] + dp[i - freq * num]
                    dp[i] = stride[i] - stride[i - num * (freq + 1)]
                else:
                    dp[i] = stride[i]

        return (zeros + 1) * sum(dp[l : r + 1]) % kMod

