        ret = []

        for i in range(numCourses):
            if i not in deg:
                deg[i] = 0

        for i in prerequisites:
            a, b = i[0], i[1]
            if a not in deg:
                deg[a] = 1
            else:
                deg[a] += 1

            if b not in deg:
