    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        if numCourses is 0 or prerequisites is None:
            return []

        graph = {}
        for i in range(numCourses):
            graph[i] = []

        for src, dst in prerequisites:
            graph[src].append(dst)


        results = []
        visited = set()

        def dfs(node):
            if node in visited:
                return False
            if node in results:
                return True

            visited.add(node)

            for nei in sorted(graph[node]):
                if not dfs(nei):
                    return False
                graph[node].remove(nei)

            visited.remove(node)

            if node not in results:
                results.append(node)

            return True

        for i in range(numCourses):
            if not dfs(i):
                return []

        return results

class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        reqs = {}
        nexts = {}
        courses = set()
        for v in prerequisites:
            if v[0] in reqs:
                reqs[v[0]].add(v[1])
            else:
                reqs[v[0]] = {v[1]}
            if v[1] in nexts:
                nexts[v[1]].add(v[0])
            else:
                nexts[v[1]] = {v[0]}
            courses.add(v[0])
            courses.add(v[1])
        res = [i for i in range(numCourses) if i not in courses]

        while reqs:
            takes = list(courses - set(reqs.keys()))
            if not takes:
                # cycle
                return []
            for p in takes:
                if p in nexts:
                    for c in nexts[p] & set(reqs.keys()):
                        reqs[c].remove(p)
                        if not reqs[c]:
                            reqs.pop(c)
            courses -= set(takes)
            res += takes
        return res + list(courses)

