        """

        par = [i for i in range(len(edges)+ 1)]
        rank = [1 for _ in range(len(edges) + 1)]

        def find_parent(node):
            p = par[node]
            while not p == par[p]:
                # par[p] = par[par[p]]
                p = par[p]

            return p

        def union(u, v):
            par_u = find_parent(u)
            par_v = find_parent(v)

            # If they are already the same
            if par_u == par_v:
