class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        min_value = min(nums)
        max_value = max(nums)
        count = [ 0 ] * (max_value - min_value + 1)

        for num in nums:
            count[num - min_value] += 1

        remain = k
        for num in range(len(count) -1, -1, -1):
            remain -= count[num]
            if remain <= 0:
                return num + min_value

        return -1

class Solution(object):
    def networkDelayTime(self, times, n, k):
        """
        :type times: List[List[int]]
        :type n: int
        :type k: int
        :rtype: int
        """

        adjacencyList = {}

        for time in times:
            if time[0] not in adjacencyList:
                adjacencyList[time[0]] = [[time[2], time[1]]]
            else:
                adjacencyList[time[0]].append([time[2], time[1]])

        import heapq
        queue = []
        heapq.heappush(queue, [0,k])
        visited = [False]*(n+1)
        distances = [float('inf')]*(n+1)
        distances[0] = 0
        distances[k] = 0

        while queue:
            curr = heapq.heappop(queue)
            dist = curr[0]
            node = curr[1]
            visited[node] = True

            if distances[node] > dist:
                distances[node] = dist

            if node in adjacencyList:
                for n in adjacencyList[node]:
                    if not visited[n[1]]:
                        heapq.heappush(queue, [n[0] + dist, n[1]])

        minTime = max(distances)

        if minTime == float('inf'):
            return -1
        else:
            return minTime

