import sys , heapq
class Solution(object):
    def networkDelayTime(self, times, n, k):
        """
        :type times: List[List[int]]
        :type n: int
        :type k: int
        :rtype: int
        """
        dist = [sys.maxint]*(n+1)
        graph = defaultdict(list)
        for t in times :
            graph[t[0]].append([t[1] , t[2]])
        dist[k] = 0
        h = []
        spSet = set()
        heapq.heappush(h,(0,k))
        while len(h) > 0 :
            val , node = heapq.heappop(h)
            if node in spSet :
                continue
            spSet.add(node)
            for ele in graph[node] :
                if dist[ele[0]] > val+ele[1] :
                    dist[ele[0]] = val+ele[1]
                    heapq.heappush(h , (val+ele[1] , ele[0]))
        if len(spSet) < n :
            return -1
        else :
            return max(dist[1:])

