class Solution(object):
    def networkDelayTime(self, times, n, k):
        """
        :type times: List[List[int]]
        :type n: int
        :type k: int
        :rtype: int
        """
        adj = {}
        for i in range(1, n+1):
            adj[i] = []
        for u, v, w in times:
            adj[u].append([v, w])

        res = {}
        minHeap = [[0, k]]

        while minHeap:
            w1, u = heapq.heappop(minHeap)
            if u in res:
                continue
            res[u] = w1
            for v, w2 in adj[u]:
                heapq.heappush(minHeap, [w1+w2, v])

        if len(res) != n:
            return -1
        return max(res.values())

class Solution(object):
    def networkDelayTime(self, times, n, k):
        """
        :type times: List[List[int]]
        :type n: int
        :type k: int
        :rtype: int
        """
        # times: time it takes for a signal to travel from source to target.
        # n: nodes num
        # k: a given node
        # dist[u]: 为从k-->u的最短距离
        dist = [-1 for _ in xrange(n)]
        dist[k-1] = 0
        # 从k到u最多走n-1步，因为(u,v,w) u and v互不相同
        for _ in range(n-1):
            for edge in times:
                u, v, w = edge
                u, v = u-1, v-1
                if dist[u] == -1:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + w
                else:
                    dist[v] = min(dist[v], dist[u] + w)

        res = -1
        for d in dist:
            if d == -1:
                return -1
            else:
                res = max(res, d)
        return res

