class Solution(object):
    def shortestPathBinaryMatrix(self, grid):
        """
        :type grid: List[List[int]]
        :rtype: int
        """
        if grid[0][0] == 1:
            return -1
        queue = [(0, [0,0], 1)]
        n = len(grid)
        heapq.heapify(queue)
        seen = set()
        while queue:
            priority, coor, steps = heapq.heappop(queue)

            if coor[0] == n-1 and coor[1] == n-1:
                return steps

            if (coor[0], coor[1]) in seen:
                continue
            else:
                seen.add((coor[0], coor[1]))

            for row in range(max(0, coor[0]-1), min(n-1, coor[0]+1)+1):
                for col in range(max(0, coor[1]-1), min(n-1, coor[1]+1)+1):
                    if row == coor[0] and col == coor[1]:
                        continue
                    if grid[row][col] == 0:
                        heuristic = max(n-1 - row, n-1 - col)
                        heapq.heappush(queue, (steps+heuristic+1, [row,col], steps+1))



        return -1

class Solution(object):
    def validPath(self, n, edges, source, destination):
        """
        :type n: int
        :type edges: List[List[int]]
        :type source: int
        :type destination: int
        :rtype: bool
        """
        # construct a parent array
        p = [i for i in xrange(n)]
        def find(n):
            if p[n] != n:
                # compress path
                p[n] = find(p[n])
            return p[n]
        for u, v in edges:
            p[find(u)] = find(v)
        return find(source) == find(destination)

