class Solution(object):
    def validPath(self, n, edges, source, destination):
        """
        :type n: int
        :type edges: List[List[int]]
        :type source: int
        :type destination: int
        :rtype: bool
        """
        #find all edges that have contain source vertex. Write out the verticies that can be obtained. For each vertex that can be obtained, do this again. Check criteria: set size hasnt grown.
        if source==destination:
            return True
        reachables = {source}
        current_size = 0
        while current_size != len(reachables):
            current_size = len(reachables)
            for edge in edges:
                if edge[0] in reachables or edge[1] in reachables:
                    reachables.add(edge[0])
                    reachables.add(edge[1])
                if destination in reachables:
                    return True
        return False

