class LRUCache:

    def __init__(self, capacity):
        self.capacity = capacity
        self.time = 0
        self.time_set = {}
        self.lru = {}

    def get(self, key):
        if key not in self.lru:
            return -1
        else:
            self.time_set[key] = self.time
            self.time += 1
            return self.lru[key]

    def put(self, key, value):
        if key in self.lru or len(self.lru) < self.capacity:
            self.lru[key] = value
            self.time_set[key] = self.time
        else:
            # Find the least recently used item
            lru_key = min(self.time_set, key=self.time_set.get)
            self.lru.pop(lru_key)
            self.time_set.pop(lru_key)
            self.lru[key] = value
            self.time_set[key] = self.time
        self.time += 1

