class Node:
    def __init__(self, p, n, k):
        self.prev = p
        self.next = n
        self.key = k

class LRUCache(object):



    def __init__(self, capacity):
        self.cap = capacity
        self.count = 0
        self.head = Node(None, None, None)
        self.tail = Node(self.head, None, None)
        self.head.next = (self.tail)

        self.nodes = {}
        self.keyMap = {}



    def addNode(self, k):
        n = Node(self.head, self.head.next, k)
        self.head.next = n
        n.next.prev = n
        return n



    def delete(self, n):
        n.next.prev = n.prev
        n.prev.next = n.next


    def get(self, key):
        if key not in self.keyMap.keys():
            return -1
        node = self.nodes.get(key)
        self.delete(node)
        newNode = self.addNode(node.key)
        self.nodes[key] = newNode
        return self.keyMap.get(key)


    def put(self, key, value):
        if key in self.keyMap.keys():
            node = self.nodes.get(key)
            self.delete(node)
            newNode = self.addNode(node.key)
            self.nodes[key] = newNode
            self.keyMap[key] = value
        else:
            if self.count == self.cap:
                rNode = self.tail.prev
                self.delete(rNode)
                del self.keyMap[rNode.key]
                del self.nodes[rNode.key]

                newNode = self.addNode(key)
                self.keyMap[key] = value
                self.nodes[key] = newNode

            if self.count != self.cap:
                newNode = self.addNode(key)
                self.keyMap[key] = value
                self.nodes[key] = newNode

                self.count += 1

