class MedianFinder(object):

    def __init__(self):
        self.h1 = []
        self.h2 = []
        self.c = 0
        self.mean = None

    def heapify(self, arr, N, i, maxh):
        h = i
        l = 2*i+1
        r = 2*i+2
        if maxh:
            if l < N and arr[l] > arr[h]:
                h = l
            if r < N and arr[r] > arr[h]:
                h = r
        else:
            if l < N and arr[l] < arr[h]:
                h = l
            if r < N and arr[r] < arr[h]:
                h = r
        if h != i:
            arr[i], arr[h] = arr[h], arr[i]
            self.heapify(arr, N, h, maxh)


    def insert(self, arr, val, maxh):
        arr.append(val)
        def tr(arr, i, maxh):
            p = (i-1) // 2
            if p < 0:
                return
            if maxh:
                if arr[p] < arr[i]:
                    arr[p], arr[i] = arr[i], arr[p]
                    tr(arr, p, maxh)
            else:
                if arr[p] > arr[i]:
                    arr[p], arr[i] = arr[i], arr[p]
                    tr(arr, p, maxh)
        tr(arr, len(arr)-1, maxh)


    def addNum(self, num):
        """
        :type num: int
        :rtype: None
        """
        if len(self.h1) == 0:
            self.h1.append(num)
            return

        if len(self.h2) == 0:
            if num > self.h1[0]:
                self.h2.append(num)
            else:
                self.h2.append(self.h1[0])
                self.h1[0] = num
            return
        if num < self.h2[0]:
            self.insert(self.h1, num, maxh=True)

            # Balance
            if len(self.h1) > len(self.h2)+1:
                # Add to h1
                self.insert(self.h2, self.h1[0], maxh=False)
                # Remove from h2
                self.h1[0] = self.h1[-1]
                self.h1.pop()
                self.heapify(self.h1, len(self.h1), 0, maxh=True)

        else:
            self.insert(self.h2, num, maxh=False)

            # Balance
            if len(self.h2) > len(self.h1):
                # Add to h1
                self.insert(self.h1, self.h2[0], maxh=True)
                # Remove from h2
                self.h2[0] = self.h2[-1]
                self.h2.pop()
                self.heapify(self.h2, len(self.h2), 0, maxh=False)



    def findMedian(self):
        """
        :rtype: float
        """
        if (len(self.h1) + len(self.h2)) % 2 == 0:
            return (self.h1[0] + self.h2[0]) / 2.
        else:
            return self.h1[0] 



