class Solution(object):
    def outerTrees(self, trees):
        trees.sort() # sort trees according to x axis

        def cmpSlopes(p1, p2, p3):
            x1, y1 = p1
            x2, y2 = p2
            x3, y3 = p3
            # if slope13 - slope12 > 0 => point 2 is under the line 13

            return (y3 - y1) * (x2 - x1) - (y2 - y1) * (x3 - x1) 

        higher, lower  = [], []

        for point in trees:
            while len(higher) >= 2 and cmpSlopes(higher[-2], higher[-1], point) > 0:
                # pop point2 if slope12 < slope13
                higher.pop() 

            while len(lower) >= 2 and cmpSlopes(lower[-2], lower[-1], point) < 0:
                # pop point2 if slope13 < slope12
                lower.pop() 

            # append point 3 since the last point in the x-axis 
            #will always be part of the boundary
            lower.append(tuple(point)) 

            higher.append(tuple(point))

        return list(set(lower + higher))

