class Solution(object):
    def outerTrees(self, trees):
        """
        :type trees: List[List[int]]
        :rtype: List[List[int]]
        """
        def orientation(p, q, r):
            return (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])

        def andrews_monotone_chain(points):
            points.sort()

            upper_hull = []
            for point in points:
                while len(upper_hull) >= 2 and orientation(upper_hull[-2], upper_hull[-1], point) < 0:
                    upper_hull.pop()
                upper_hull.append(point)

            lower_hull = []
            for point in reversed(points):
                while len(lower_hull) >= 2 and orientation(lower_hull[-2], lower_hull[-1], point) < 0:
                    lower_hull.pop()
                lower_hull.append(point)

            return upper_hull + lower_hull

        if len(trees) <= 3:
            return trees

        convex_hull = andrews_monotone_chain(trees)

        # To eliminate duplicates, convert the list of lists to a set of tuples, and back to a list of lists
        unique_convex_hull = [list(point) for point in set(map(tuple, convex_hull))]
        return unique_convex_hull

