def decode_string(s: str) -> str:
    """
    Decode the string according to the rule: k[encoded_string].
    """
    stack = []
    current_num = 0
    current_str = ""
    for char in s:
        if char.isdigit():
            current_num = current_num * 10 + int(char)
        elif char == '[':
            stack.append((current_str, current_num))
            current_str, current_num = "", 0
        elif char == ']':
            prev_str, num = stack.pop()
            current_str = prev_str + num * current_str
        else:
            current_str += char
    return current_str

def add_bitwise_operator(x: int, y: int) -> int:
    while y != 0:
        carry = x & y
        x = x ^ y
        y = carry << 1
    return x

def find_first_occurrence(nums, target):
    """
    Returns the index of the first occurrence of target in nums.
    If target is not present, returns -1.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            if mid == 0 or nums[mid - 1] != target:
                return mid
            right = mid - 1

    return -1

