def detect_prime(n: int) -> bool:
    """
    Returns True if n is a prime number, else returns False.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
