    return True

def isBalanced(s: str) -> bool:
    """
    Determines if the brackets in the input string are balanced.

    Args:
    s (str): The input string containing the brackets.

    Returns:
    bool: True if the brackets are balanced, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            continue  # ignore non-bracket characters

    return stack == []

def longest_common_subsequence(text1, text2):
    """
    Finds the longest common subsequence (LCS) of two strings and returns the LCS as a string.
    """
    m, n = len(text1), len(text2)
    dp = [["" for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + text1[i - 1]
            else:
                if len(dp[i - 1][j]) > len(dp[i][j - 1]):
                    dp[i][j] = dp[i - 1][j]
                else:
                    dp[i][j] = dp[i][j - 1]

    return dp[m][n]

def min_sessions(tasks, sessionTime):
    """
    Returns the minimum number of sessions needed to complete all tasks given that the sum
    of task durations in each session should not exceed sessionTime.
    """
    n = len(tasks)
    dp = [float('inf')] * (1 << n)
    dp[0] = 1

    # Calculate the sum of the tasks for each subset
    subset_sum = [0] * (1 << n)
    for mask in range(1 << n):
        total = 0
        for i in range(n):
            if mask & (1 << i):
                total += tasks[i]
        subset_sum[mask] = total

    # Dynamic programming to find the minimum number of sessions
    for mask in range(1 << n):
        if subset_sum[mask] <= sessionTime:
            dp[mask] = 1
        else:
            submask = mask
            while submask:
                if subset_sum[submask] <= sessionTime:
                    dp[mask] = min(dp[mask], dp[mask ^ submask] + 1)
                submask = (submask - 1) & mask

    return dp[(1 << n) - 1]

