def prime_factors(number: int) -> List[int]:
    """
    Returns a list of prime factors for a given positive integer.
    """
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if number < 1:
        raise ValueError("number must be greater than or equal to 1")

    factors = []
    # Handle the number 1 case directly
    if number == 1:
        return [1]

    divisor = 2
    while number >= divisor:
        while number % divisor == 0:
            factors.append(divisor)
            number //= divisor
        divisor += 1
    return factors

def find_top_manager(n, reportPairs):
    if n == 0:
        return -1

    # a set of all employee IDs
    all_employees = set(range(1, n+1))

    # a set of employees who report to someone
    has_manager = set(e for _, e in reportPairs)

    # find the set of employees who do not report to anyone
    top_managers = all_employees - has_manager

    if not top_managers:
        return -1

    # return the smallest ID among the top managers
    return min(top_managers)

def find_min_max(arr):
    """
    Returns a tuple containing the minimum and maximum values in the array.
    """
    if not arr:
        raise ValueError("Array must contain at least one element")

    min_val, max_val = arr[0], arr[0]

    for num in arr:
        if num < min_val:
            min_val = num
        if num > max_val:
            max_val = num

    return (min_val, max_val)

def pigeonhole_sort(arr: list) -> list:
    if not arr:
        return []

    min_value = min(arr)
    max_value = max(arr)
    size = max_value - min_value + 1

    holes = [[] for _ in range(size)]

    for number in arr:
        holes[number - min_value].append(number)

    sorted_arr = []
    for hole in holes:
        sorted_arr.extend(hole)

    return sorted_arr

def first_non_repeating_char(s):
    """
    Returns the first non-repeating character in the given string.
    If all characters are repeating, returns '_blank_'.
    """
    char_count = {}

    # Count the occurrence of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character with a count of 1
