def longest_palindromic_subsequence(s: str) -> int:
    """
    Computes the length of the longest palindromic subsequence in the input string s.
    """
    n = len(s)
    # Create a 2D array dp to store the lengths of palindromic subsequences.
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Each character on its own is a palindrome of length 1.
    for i in range(n):
        dp[i][i] = 1

    # Fill the dp array.
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and length == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

import heapq
from typing import Dict, List, Tuple

def shortest_path(graph: Dict[str, List[Tuple[str, int]]], start: str, end: str) -> List[str]:
    # Check if the start and end warehouses exist in the graph
    if start not in graph or end not in graph:
        raise ValueError("Invalid start or end warehouse")

    # Priority queue for Dijkstra's algorithm
    priority_queue = [(0, start, [])]  # (distance, current_node, path)
    visited = set()

    while priority_queue:
        current_distance, current_node, path = heapq.heappop(priority_queue)

        if current_node in visited:
            continue

        visited.add(current_node)
        new_path = path + [current_node]

        if current_node == end:
            return new_path

        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in visited:
                heapq.heappush(priority_queue, (current_distance + weight, neighbor, new_path))

    # If there's no path to the end warehouse
    return []

from collections import deque

def min_steps_maze(grid):
    rows = len(grid)
    cols = len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find starting point 'S' and end point 'E'
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            if grid[r][c] == 'E':
                end = (r, c)

    # Set up the queue for BFS
    queue = deque([(start[0], start[1], 0)])  # (row, col, distance)
    visited = set()
    visited.add(start)

    while queue:
        r, c, dist = queue.popleft()

        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return -1

from typing import List

def pigeonhole_sort_v2(arr: List[int]) -> List[int]:
    if not arr:
        return []

    mn = min(arr)
    mx = max(arr)
    size = mx - mn + 1

    holes = [0] * size

    for x in arr:
        holes[x - mn] += 1

    sorted_arr = []
    for count in range(size):
        while holes[count] > 0:
            sorted_arr.append(count + mn)
            holes[count] -= 1

    return sorted_arr

def searchMatrix(matrix, target):
    """
    Searches for a target value in a matrix where each row is sorted in ascending order
    from left to right, and each column is sorted in ascending order from top to bottom.

    :param matrix: List[List[int]], the matrix of integers
    :param target: int, the target value to search for
    :return: bool, True if the target exists in the matrix, otherwise False
    """
    if not matrix or not matrix[0]:
        return False

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1

    return False

