def is_match(s: str, p: str) -> bool:
    """
    Returns whether the input string `s` matches the pattern `p`.
    Pattern can include '.' which matches any single character
    and '*' which matches zero or more of the preceding character.
    """
    # Create a DP table with dimensions (len(s) + 1) x (len(p) + 1)
    # dp[i][j] will be True if s[0:i] matches p[0:j]
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # An empty string matches an empty pattern
    dp[0][0] = True

    # Handle patterns with '*' at the beginning
    for j in range(2, len(p) + 1):
        if p[j-1] == '*':
            dp[0][j] = dp[0][j-2]

    # Fill the table iteratively
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j-1] == '*' and j > 1:
                # '*' can either match zero or more of the preceding element
                dp[i][j] = dp[i][j-2] or (dp[i-1][j] and (s[i-1] == p[j-2] or p[j-2] == '.'))
            else:
                # Match single character
                if p[j-1] == '.' or p[j-1] == s[i-1]:
                    dp[i][j] = dp[i-1][j-1]

    return dp[len(s)][len(p)]

