    corresponding to the push_arr, otherwise returns false.
    """
    stack = []
    j = 0

    for num in push_arr:
        stack.append(num)
        while stack and stack[-1] == pop_arr[j]:
            stack.pop()
            j += 1

    return j == len(pop_arr)

