    """
    Returns the account number that has the highest balance after all transactions have been processed.

    Arguments:
    transactions -- list of transactions, where each transaction is represented as 
                    [accountNumber, transactionType, amount]

    Returns:
    string -- the account number with the highest balance
    """
    account_balances = {}

    for accountNumber, transactionType, amount in transactions:
        if accountNumber not in account_balances:
            account_balances[accountNumber] = 0

        if transactionType == 'deposit':
