def get_skyline(buildings):
    events = []
    for L, R, H in buildings:
        events.append((L, -H, R))
        events.append((R, 0, 0))
    events.sort()

    res = [[0, 0]]
    pq = [(0, float('inf'))]

    for x, negH, R in events:
        while pq[0][1] <= x:
            heappop(pq)
        if negH != 0:
            heappush(pq, (negH, R))
        maxH = -pq[0][0]
        if res[-1][1] != maxH:
            res.append([x, maxH])

    return res[1:]

def custom_find(string: str, substring: str) -> int:
