    prev = lo - 1

    for num in arr + [hi + 1]:
        if num == prev + 2:
            ranges.append((prev + 1, prev + 1))
        elif num > prev + 2:
            ranges.append((prev + 1, num - 1))
        prev = num

    return ranges

def characterReplacement(s, k):
    max_len = 0
    left = 0
    counts = {}
    max_count = 0

    for right in range(len(s)):
        counts[s[right]] = counts.get(s[right], 0) + 1
        max_count = max(max_count, counts[s[right]])

        while (right - left + 1) - max_count > k:
            counts[s[left]] -= 1
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

def extended_gcd(a, b):
    """
    Returns the Bézout coefficients (s, t) and gcd of a and b
    such that a * s + b * t = gcd(a, b).
    """
    if a == 0:
        return (0, 1, b)
    else:
        s1, t1, gcd = extended_gcd(b % a, a)
        s = t1 - (b // a) * s1
        t = s1
        return (s, t, gcd)

def calculate_factorial(n):
    """
    Calculate the factorial of a non-negative integer n using recursion.
    Raises a ValueError for negative integers and TypeError for non-integers.

    Args:
    n (int): the input integer for which factorial needs to be calculated.

    Returns:
    int: factorial of the input integer n.

    Raises:
    ValueError: if n is a negative integer.
    TypeError: if n is not an integer.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")

    if n == 0:
        return 1
    else:
        return n * calculate_factorial(n - 1)

def longest_distinct_substring(s):
    """
    Returns the longest substring of `s` that consists of distinct characters.
    """
    last_seen = {}
    start = 0
    max_length = 0
    start_index_of_max = 0

    for end in range(len(s)):
        if s[end] in last_seen:
            start = max(start, last_seen[s[end]] + 1)

        last_seen[s[end]] = end

        if end - start + 1 > max_length:
            max_length = end - start + 1
            start_index_of_max = start

    return s[start_index_of_max:start_index_of_max + max_length]

def find_two_sum_indices(arr, x):
    """
    Finds two distinct indices such that the elements at these indices add up to x.

    Parameters:
    arr (list): List of unique positive integers.
    x (int): Target integer.

    Returns:
    list: List containing the two indices. Returns an empty list if no such pair exists.
    """
    index_map = {}
    for i, num in enumerate(arr):
        complement = x - num
        if complement in index_map:
            return sorted([index_map[complement], i])
        index_map[num] = i
    return []

def atbash_cipher(message: str) -> str:
    translated = ""
    for char in message:
        if char.isalpha():
            if char.isupper():
                translated += chr(ord('Z') - (ord(char) - ord('A')))
            elif char.islower():
                translated += chr(ord('z') - (ord(char) - ord('a')))
        else:
            translated += char
    return translated

