def interpolation_search_custom(array: List[int], search_key: int) -> int:
    low = 0
    high = len(array) - 1

    while low <= high and search_key >= array[low] and search_key <= array[high]:
        if low == high:
            if array[low] == search_key:
                return low
            return -1

        pos = low + ((high - low) // (array[high] - array[low]) * (search_key - array[low]))

        if array[pos] == search_key:
            return pos
        if array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

def search_matrix(matrix, target):
    """
    Searches for the target in the matrix. The matrix has properties: 
    each row is sorted in ascending order, each column is sorted in ascending order.

    :param matrix: 2D list of integers
    :param target: integer
    :return: boolean indicating if target is found in matrix
    """
    if not matrix or not matrix[0]:
        return False

    m, n = len(matrix), len(matrix[0])
    row, col = 0, n - 1

    while row < m and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1

    return False

