def calculate_median_age(ages: List[int]) -> float:
    if not ages:
        raise ValueError("Input list cannot be empty")

    ages.sort()
    n = len(ages)
    mid = n // 2

    if n % 2 == 1:
        return float(ages[mid])
    else:
        return (ages[mid - 1] + ages[mid]) / 2.0

def edit_distance(str1: str, str2: str) -> int:
    n, m = len(str1), len(str2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize base cases
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    # Fill the matrix
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                insert = dp[i][j - 1]
                delete = dp[i - 1][j]
                substitute = dp[i - 1][j - 1]
                dp[i][j] = 1 + min(insert, delete, substitute)

    return dp[n][m]

