def increasing_triplet(nums):
    """
    Returns true if there exists a subsequence of length 3 that forms an increasing triplet subsequence.
    Otherwise, returns false.
    """
    if not nums or len(nums) < 3:
        return False

    first = float('inf')
    second = float('inf')

    for n in nums:
        if n <= first:
            first = n
        elif n <= second:
            second = n
        else:
            return True

    return False

def check_subarray_sum(arr, k):
    """
    Returns True if there is a continuous subarray of size at least k that sums up to a multiple of k, otherwise False.
    """
    if len(arr) < k:
        return False

    cum_sum = 0
    mod_dict = {0: -1}

    for i, num in enumerate(arr):
        cum_sum += num
        mod = cum_sum % k

        if mod in mod_dict:
            if i - mod_dict[mod] >= k:
                return True
        else:
            mod_dict[mod] = i

    return False

import math

def min_num_perfect_squares(n):
    """
    Returns the smallest number of perfect squares that sum to the specified number.

    :param n: int, the number to be summed to using smallest number of perfect squares
    :return: int between 1 - 4, the minimum number of perfect squares that sum to the specified number
    """
    if int(math.sqrt(n))**2 == n:
        return 1

    while n > 0 and n % 4 == 0:
        n = n // 4

    if n % 8 == 7:
        return 4

    for i in range(1, int(math.sqrt(n)) + 1):
        if int(math.sqrt(n - i**2))**2 == n - i**2:
            return 2

    return 3

def longest_subarray_with_sum_at_most_x(arr, x):
    max_length = 0
    current_sum = 0
    start_index = 0

    for end_index in range(len(arr)):
        current_sum += arr[end_index]

        while current_sum > x and start_index <= end_index:
            current_sum -= arr[start_index]
            start_index += 1

        if current_sum <= x:
            max_length = max(max_length, end_index - start_index + 1)

    return max_length

