def common_elements(matrix):
    """
    Finds all elements present in every row of the matrix in increasing order.

    :param matrix: List of lists where each list represents a row in the matrix.
    :return: List of common elements sorted in ascending order.
    """
    if not matrix:
        return []

    common_set = set(matrix[0])

    for row in matrix[1:]:
        common_set &= set(row)

    return sorted(common_set)

def longest_winning_streak(nums):
    """
    Returns the length of the longest winning streak in the series.
    A winning streak is when each score is greater than the preceding score.
    """
    if not nums:
        return 0

    max_streak = 0
    current_streak = 0

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            current_streak += 1
            max_streak = max(max_streak, current_streak)
        else:
            current_streak = 0

    return 0 if max_streak == 0 else max_streak + 1

def compute_avg_response_time(logs):
    """
    Computes the average response time per endpoint for successful requests.
    """
    endpoint_stats = {}

    for log in logs:
        try:
            endpoint, status, response_time = log.split(',')
            response_time = float(response_time)
            if status == "success":
                if endpoint not in endpoint_stats:
                    endpoint_stats[endpoint] = {"total_time": 0, "count": 0}
                endpoint_stats[endpoint]["total_time"] += response_time
                endpoint_stats[endpoint]["count"] += 1
        except ValueError:
            # Skip any malformed logs
            continue

    avg_response_times = {}
    for endpoint, stats in endpoint_stats.items():
        if stats["count"] > 0:
            avg_response_times[endpoint] = stats["total_time"] / stats["count"]

    return avg_response_times

def final_string_length(s):
    """
    Determine the length of the final string after performing any number of moves
    where we can remove any two adjacent characters if they are different.

    Parameters:
    s (str): The input string containing characters 'a', 'b', and 'c'.

    Returns:
    int: The length of the final string.
    """
    stack = []

    for char in s:
        if stack and stack[-1] != char:
            stack.pop()  # remove the adjacent different character
        else:
            stack.append(char)

    return len(stack)

from typing import List

def enhanced_interpolation_search(array: List[int], search_key: int) -> int:
    """
    Perform an enhanced interpolation search on the given sorted array.

    Args:
    - array (List[int]): A sorted list of integers.
    - search_key (int): The value to search for.

    Returns:
    - int: The index of the search_key if found, otherwise -1.
    """

    if not array:
        return -1

    low, high = 0, len(array) - 1

    while low <= high and search_key >= array[low] and search_key <= array[high]:
        if low == high:
            if array[low] == search_key:
                return low
            return -1

        # Avoid division by zero and handle repetitive elements
        if array[high] == array[low]:
            if array[low] == search_key:
                return low
            return -1

        pos = low + ((high - low) // (array[high] - array[low]) * (search_key - array[low]))

        # Ensure the calculated position stays within bounds
        pos = max(min(pos, high), low)

        if array[pos] == search_key:
            return pos
        if array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

def longest_zero_sum_subarray(arr):
    """
    Find the length of the longest subarray with sum zero.

    Parameters:
    arr (list): List of integers where each element is either 1 or -1.

    Returns:
    int: Length of the longest subarray with sum zero.
    """
    sum_index_map = {}
    max_length = 0
    current_sum = 0

    for i in range(len(arr)):
        current_sum += arr[i]

        if current_sum == 0:
            max_length = i + 1
        elif current_sum in sum_index_map:
            max_length = max(max_length, i - sum_index_map[current_sum])
        else:
            sum_index_map[current_sum] = i

    return max_length

def can_form_palindrome(s):
    """
    Determines if the characters of the string s can be rearranged to form a palindrome.
    """
    # Count the frequency of each character in the string
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check the number of characters with odd frequency counts
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # A string can form a palindrome if there is at most one character with an odd count
    return odd_count <= 1

def can_transform_by_reversing_substring(s, t):
    """
    Determines if string s can be transformed into string t by reversing any one of its substrings exactly once.
    """
    if s == t:
        return True

    len_s = len(s)

    # If lengths are not the same, no transformation is possible
    if len_s != len(t):
        return False

    # Try reversing every possible substring in s and see if any of them match t
    for i in range(len_s):
        for j in range(i+1, len_s+1):
            reversed_substring = s[:i] + s[i:j][::-1] + s[j:]
            if reversed_substring == t:
                return True

    return False

import csv
