def optimized_euler_totient(n: int) -> int:
    if n == 1:
        return 1

    result = n
    p = 2

    # Check for each number from 2 to sqrt(n)
    while p * p <= n:
        # Check if p is a divisor of n
        if n % p == 0:
            # If so, then p is a prime factor, so we calculate
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1

    # This condition is to check if n is a prime number
    # greater than sqrt(n)
    if n > 1:
        result -= result // n

    return result

def four_sum(arr, target):
    """
    Find all unique quadruplets that sum up to the target value.
    """
    arr.sort()
    n = len(arr)
    quadruplets = set()

    for i in range(n-3):
        for j in range(i+1, n-2):
            left, right = j + 1, n - 1
            while left < right:
                total = arr[i] + arr[j] + arr[left] + arr[right]
                if total == target:
                    quadruplets.add((arr[i], arr[j], arr[left], arr[right]))
                    left += 1
                    right -= 1
                elif total < target:
                    left += 1
                else:
                    right -= 1

    # Convert set into sorted list of lists
    result = sorted([list(quad) for quad in quadruplets])
    return result

def length_of_longest_substring(s):
