    s = s.replace(" ", "")
    stack = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()

    return len(stack) == 0

def optimized_bubble_sort(arr):
    """
    Optimized bubble sort that stops if the array is already sorted.
    """
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

def search_rotated_sorted_array(array, target):
    """
    This function returns the index of the target in the rotated sorted array if found, otherwise -1.
    """
    start, end = 0, len(array) - 1

    while start <= end:
        mid = (start + end) // 2

        if array[mid] == target:
            return mid

        if array[start] <= array[mid]:  # left half is sorted
            if array[start] <= target < array[mid]:
                end = mid - 1
            else:
                start = mid + 1
        else:  # right half is sorted
            if array[mid] < target <= array[end]:
                start = mid + 1
            else:
                end = mid - 1

    return -1

