def max_points(points):
    n = len(points)
    if n == 0:
        return 0
    if n == 1:
        return points[0]

    # dp[i] will store the maximum points we can get till index i
    dp = [0] * n
    dp[0] = points[0]

    if n > 1:
        dp[1] = max(points[0], points[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], points[i] + dp[i-2])

    return dp[-1]

def longest_unique_substr(s: str) -> (int, str):
    """
    Find the longest substring without repeating characters and return its length and the substring itself.
    """
    n = len(s)
    if n == 0:
        return (0, "")

    char_index_map = {}
    start = 0
    max_length = 0
    longest_substr = ""

    for end in range(n):
        if s[end] in char_index_map:
            start = max(start, char_index_map[s[end]] + 1)

        char_index_map[s[end]] = end

        if end - start + 1 > max_length:
            max_length = end - start + 1
            longest_substr = s[start:end+1]

    return (max_length, longest_substr)

def are_anagrams(s1: str, s2: str) -> bool:
    """
    Determine if two strings are anagrams of each other.

    Parameters:
    s1 (str): First input string.
    s2 (str): Second input string.

    Returns:
    bool: True if both strings are anagrams, False otherwise.
    """
    if len(s1) != len(s2):
        return False

    # Frequency dictionary to count occurrences of each character
    char_count = {}

    for char in s1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in s2:
        if char in char_count:
            char_count[char] -= 1
            if char_count[char] == 0:
                del char_count[char]
        else:
            return False

    return len(char_count) == 0

from typing import List

def find_longest_common_prefix(strings: List[str]) -> str:
    if not strings:
        return ""

    # Initialize to the first string since we need to compare others to it
    prefix = strings[0]

    for i in range(1, len(strings)):
        temp_prefix = ""
        for j in range(min(len(prefix), len(strings[i]))):
            if prefix[j] == strings[i][j]:
                temp_prefix += prefix[j]
            else:
                break
        prefix = temp_prefix

        # If at any point, the common prefix becomes empty, return immediately
        if prefix == "":
            return ""

    return prefix

def optimized_selection_sort(arr):
    """
    Sorts an array of integers using an optimized selection sort algorithm.

    Introduces early stopping if the array is found to be already sorted during the process.

    :param arr: List of integers to be sorted.
    :return: List of integers sorted in ascending order.
    """
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j

        # Swap the found minimum element with the first element
        if min_idx != i:
            arr[i], arr[min_idx] = arr[min_idx], arr[i]

        # Check if the array is already sorted
        sorted = True
        for k in range(i+1, n-1):
            if arr[k] > arr[k+1]:
                sorted = False
                break
        if sorted:
            break

    return arr

def has_all_unique_chars(s: str) -> bool:
