    """
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n):
            if s[i] == s[j]:
                return False
    return True

def remove_excessive_characters(s):
    """
    Remove the minimum number of characters from the string so that every letter appears at most twice.
    """
    from collections import Counter

    count = Counter(s)
    result = []

    # Create a temporary dictionary to keep track of occurrences of each letter in the result
    temp_count = {char: 0 for char in count}

    for char in s:
        if temp_count[char] < 2:
            result.append(char)
            temp_count[char] += 1

    return ''.join(result)

def sum_of_digits(s: str) -> int:
    """
    Returns the sum of all numerical digits present in the input string s.
    """
    return sum(int(char) for char in s if char.isdigit())

def min_cost_path(grid):
    """
    Returns the minimum cost to reach the bottom-right corner of the grid from the top-left.
    Movement is restricted to right or down.
    """
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])
    dp = [[0] * m for _ in range(n)]

    dp[0][0] = grid[0][0]

    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[n-1][m-1]

def largest_square_submatrix(matrix, k):
    if k == 0:
        return 0

    dp = [[0] * k for _ in range(k)]
    max_side = 0

    for i in range(k):
        for j in range(k):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1  # If it's on the first row or first column
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

def box_volume(length: float, width: float, height: float) -> float:
    if length <= 0:
        raise ValueError("The length of the box cannot be zero or negative")
    if width <= 0:
        raise ValueError("The width of the box cannot be zero or negative")
    if height <= 0:
        raise ValueError("The height of the box cannot be zero or negative")

    return length * width * height

def shift_string(s, n):
    """
    Shifts each character in the string `s` forward by `n` positions in the alphabet.
    The alphabet is considered circular. Non-alphabet characters remain unchanged.
    """
    result = []
    for char in s:
        if char.islower():
            result.append(chr((ord(char) - ord('a') + n) % 26 + ord('a')))
        elif char.isupper():
            result.append(chr((ord(char) - ord('A') + n) % 26 + ord('A')))
        else:
            result.append(char)
    return ''.join(result)

def transpose(matrix):
    """
    Returns the transpose of the given matrix.
    Transposing a matrix means to flip the matrix over its main diagonal, switching the row and column indices.
    """
    if not matrix:
        return []
    m, n = len(matrix), len(matrix[0])
    transposed = [[0] * m for _ in range(n)]

    for i in range(m):
        for j in range(n):
            transposed[j][i] = matrix[i][j]

    return transposed

def longest_bitonic_subsequence(arr):
    """
    Returns the length of the longest bitonic subsequence in the array.
    """
    n = len(arr)

    if n == 0:
        return 0

    # Initialize the increasing and decreasing subsequences
    inc = [1] * n
    dec = [1] * n

    # Fill increasing subsequence array
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Fill decreasing subsequence array
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # The length of longest bitonic subsequence is the max value of (inc[i] + dec[i] - 1)
    max_length = 0
    for i in range(n):
        max_length = max(max_length, inc[i] + dec[i] - 1)

    return max_length

def compress_string(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    if not s:
        raise TypeError("input must be a non-empty string")

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1] + str(count))
            count = 1

    # Add the last repeated character
    compressed.append(s[-1] + str(count))

    compressed_str = ''.join(compressed)
    return compressed_str if len(compressed_str) < len(s) else s

from typing import List, Tuple

def missing_ranges(arr: List[int], lo: int, hi: int) -> List[Tuple[int, int]]:
    result = []

    # Check if we need to add range from lo to first element of arr
    if not arr or lo < arr[0]:
        if not arr:
            result.append((lo, hi))
        else:
            if lo < arr[0]:
                result.append((lo, arr[0] - 1))

    # Check for missing ranges between elements in arr
    for i in range(1, len(arr)):
        if arr[i] - arr[i-1] > 1:
            result.append((arr[i-1] + 1, arr[i] - 1))

    # Check if we need to add range from last element of arr to hi
    if arr and arr[-1] < hi:
        result.append((arr[-1] + 1, hi))

    return result

def max_nested_rectangles(height, width):
    """
    Given the heights and widths arrays of rectangles, return the maximum number of rectangles 
    that can be nested inside each other.
    """
    # Combine the heights and widths into a list of tuples and sort them based on one dimension first
    # and if they are equal, sort by the other dimension in descending order.
    rectangles = sorted(zip(height, width), key=lambda x: (x[0], -x[1]))

    # Initialize an array to keep track of the longest increasing subsequence based on the second dimension.
    dp = []

    for _, w in rectangles:
        lo, hi = 0, len(dp)

        # Binary search for the correct position of the current width.
        while lo < hi:
            mid = (lo + hi) // 2
            if dp[mid] < w:
                lo = mid + 1
            else:
                hi = mid

        # Replace or add the current width to the dp array.
        if lo < len(dp):
            dp[lo] = w
        else:
            dp.append(w)

    return len(dp)

def longest_common_subsequence(seq1: str, seq2: str) -> str:
    """
    Returns the longest common subsequence between seq1 and seq2.
    """
    m = len(seq1)
    n = len(seq2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if seq1[i - 1] == seq2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if seq1[i - 1] == seq2[j - 1]:
            lcs.append(seq1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(lcs))

def closest_three_sum(arr, target):
    """
    Finds the closest possible sum of any three distinct elements in `arr` to the `target`.
    """
    arr.sort()
    closest_sum = float('inf')

    for i in range(len(arr) - 2):
        left, right = i + 1, len(arr) - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target:
                return current_sum  # If the exact sum is found, return it

            if abs(target - current_sum) < abs(target - closest_sum):
                closest_sum = current_sum
            elif abs(target - current_sum) == abs(target - closest_sum):
                closest_sum = min(closest_sum, current_sum)

            if current_sum < target:
                left += 1
            else:
                right -= 1

    return closest_sum

from collections import defaultdict, deque

def is_valid_k_ary_tree(edges, k):
    """
    Determines if the given edges form a valid k-ary tree.
    """
    if not edges:
        return True  # An empty tree is a valid k-ary tree.

    children_count = defaultdict(int)
    in_degree = defaultdict(int)

    for parent, child in edges:
        children_count[parent] += 1
        in_degree[child] += 1

    # Check that no node has more than k children
    for count in children_count.values():
        if count > k:
            return False

    # To ensure no cycles, we will use Kahn's algorithm for topological sorting
    # Find nodes with zero in-degree
    zero_in_degree_nodes = deque([node for node in children_count if in_degree[node] == 0])

    visited_count = 0
    while zero_in_degree_nodes:
        node = zero_in_degree_nodes.popleft()
        visited_count += 1

        for child in [child for parent, child in edges if parent == node]:
            in_degree[child] -= 1
            if in_degree[child] == 0:
                zero_in_degree_nodes.append(child)

    # If we visited all unique nodes, it means no cycle and valid tree structure
    unique_nodes = set(node for edge in edges for node in edge)
    return visited_count == len(unique_nodes)

def unique_characters(s: str) -> str:
    """
    Removes duplicate characters from the string while maintaining the original order.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

def is_drone_back(moves: str) -> bool:
    """
    Determines if the series of moves brings the drone back to its original position.

    Parameters:
    moves (str): A string containing the movements of the drone.

    Returns:
    bool: True if the drone ends up back at the starting position (0, 0), otherwise False.
    """
    horizontal = 0
    vertical = 0

    for move in moves:
        if move == 'R':
            horizontal += 1
        elif move == 'L':
            horizontal -= 1
        elif move == 'U':
            vertical += 1
        elif move == 'D':
            vertical -= 1

    return horizontal == 0 and vertical == 0

def remove_consecutive_duplicates(text: str) -> str:
    if not text:
        return ""

    words = text.split()
    result = []

    for i, word in enumerate(words):
        if i == 0 or word != words[i - 1]:
            result.append(word)

    return ' '.join(result)

def product_except_self(nums, k):
    """
    Returns an array 'result' where each element at index 'i' is the product of 
    all elements in 'nums' except nums[i], and ensures the sum of all elements 
    in 'result' is less than or equal to 'k'.

    If there is no such possible 'result' array, returns an empty array.
    """
    length = len(nums)
    if length == 0:
        return []

    left_products = [1] * length
    right_products = [1] * length
    result = [0] * length

    for i in range(1, length):
        left_products[i] = left_products[i - 1] * nums[i - 1]

    for i in range(length - 2, -1, -1):
        right_products[i] = right_products[i + 1] * nums[i + 1]

    for i in range(length):
        result[i] = left_products[i] * right_products[i]

    if sum(result) > k:
        return []
    else:
        return result

def max_subarray_len(nums, k):
    """
    Returns the maximum length of a subarray that sums to k.

    :param nums: List[int] - List of integers
    :param k: int - Target sum
    :return: int - Maximum length of subarray that sums to k
    """
    sum_map = {}
    curr_sum = 0
    max_len = 0

    for i in range(len(nums)):
        curr_sum += nums[i]
        if curr_sum == k:
            max_len = i + 1
        if (curr_sum - k) in sum_map:
            max_len = max(max_len, i - sum_map[curr_sum - k])
        if curr_sum not in sum_map:
            sum_map[curr_sum] = i

    return max_len

def extended_anagram(s1: str, s2: str) -> bool:
    """
    Determines if two strings are anagrams of each other, considering all printable ASCII characters
    and making the comparison case-insensitive.
    """
    # Normalize strings to lower case to make the comparison case insensitive
    s1 = s1.lower()
    s2 = s2.lower()

    # If lengths differ, they cannot be anagrams
    if len(s1) != len(s2):
        return False

    # Use dictionaries to count frequencies of characters
    count1 = {}
    count2 = {}

    for char in s1:
        if char in count1:
            count1[char] += 1
        else:
            count1[char] = 1

    for char in s2:
        if char in count2:
            count2[char] += 1
        else:
            count2[char] = 1

    # Compare the two dictionaries
    return count1 == count2

from typing import List, Set, Dict

def assign_category(recipes: List[Set[str]], categories: Dict[str, Set[str]]) -> List[str]:
    result = []

    for recipe in recipes:
        best_category = ""
        max_subs = 0

        for category, sub_ingredients in categories.items():
            if sub_ingredients.issubset(recipe) and len(sub_ingredients) > max_subs:
                best_category = category
                max_subs = len(sub_ingredients)

        result.append(best_category)

    return result

import heapq

def dijkstra_algorithm(graph, start, end):
    """
    Implements Dijkstra's algorithm to find the shortest path in a weighted graph.

    :param graph: A dictionary representing a weighted graph.
    :param start: A string representing the starting node.
    :param end: A string representing the target node.
    :return: A tuple containing a list of nodes representing the shortest path and the total travel time.
    """
    # Min-heap priority queue
    pq = [(0, start, [])]
    visited = set()
    while pq:
        (cost, node, path) = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        path = path + [node]

        if node == end:
            return (path, cost)

        for neighbor, weight in graph.get(node, {}).items():
            if neighbor not in visited:
                heapq.heappush(pq, (cost + weight, neighbor, path))

    return ([], 0)

def first_unique_char_optimized(s):
    """
    Finds the index of the first non-repeating character in the given string.

    Parameters:
    s (str): The input string consisting of lowercase English letters.

    Returns:
    int: Index of the first non-repeating character. If there is no such character, return -1.
    """
    # Create a dictionary to store the frequency of each character
    char_count = {}

    # Populate the dictionary with the frequency of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Loop through the string again to find the index of the first unique character
    for index, char in enumerate(s):
        if char_count[char] == 1:
            return index

    # If no unique character found, return -1
    return -1

def min_path_cost(cost):
    """
    Returns the minimum cost to reach the bottom-right cell from the top-left cell.

    :param cost: A list of lists of integers where cost[i][j] represents the cost of stepping on the cell (i, j)
    :return: Minimum cost to reach the bottom-right cell (m-1, n-1) from the top-left cell (0, 0)
    """
    if not cost or not cost[0]:
        return 0

    m, n = len(cost), len(cost[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = cost[0][0]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + cost[i][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + cost[0][j]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + cost[i][j]

    return dp[m-1][n-1]

def manual_sort_and_deduplicate(arr):
    """
    Sorts an input list of distinct integers in non-decreasing order and removes any duplicates.
    """
    # Remove duplicates by converting the list to a set
    unique_elems = list(set(arr))

    # Implementing a simple sorting algorithm: Bubble Sort
    n = len(unique_elems)
    for i in range(n):
        for j in range(0, n-i-1):
            if unique_elems[j] > unique_elems[j+1]:
                unique_elems[j], unique_elems[j+1] = unique_elems[j+1], unique_elems[j]

    return unique_elems

def remove_duplicates(s: str) -> str:
    """
    This function takes a string as input and returns a new string with only the
    first occurrences of each character, preserving the original order of their first appearances.
    """
    seen = set()
    output = []

    for char in s:
        if char not in seen:
            seen.add(char)
            output.append(char)

    return ''.join(output)

def length_of_longest_special_subarray(arr):
    """
    Returns the length of the longest special subarray from the given array.
    A special subarray has at least 3 distinct elements.
    """
    n = len(arr)
    if n < 3:
        return 0

    max_len = 0
    start = 0
    seen = {}

    for end in range(n):
        if arr[end] in seen and seen[arr[end]] >= start:
            start = seen[arr[end]] + 1
        seen[arr[end]] = end

        current_subarray_length = end - start + 1
        if current_subarray_length >= 3:
            max_len = max(max_len, current_subarray_length)

    return max_len

from typing import List

def find_triplet_with_sum(arr: List[int], target: int) -> bool:
    arr.sort()
    n = len(arr)

    for i in range(n - 2):
        l, r = i + 1, n - 1
        while (l < r):
            current_sum = arr[i] + arr[l] + arr[r]
            if current_sum == target:
                return True
            elif current_sum < target:
                l += 1
            else:
                r -= 1
    return False

def combination_sum(arr, target):
    """
    Determine if there exists a combination of elements in arr
    that sums up to the target. Each element can be used multiple times.
    """
    if target == 0:
        return True
    if target < 0:
        return False

    for num in arr:
        if combination_sum(arr, target - num):
            return True

    return False

def union_of_intervals(intervals):
    """
    Returns the total length covered by the union of the intervals.
    """
    if not intervals:
        return 0

    # Sort intervals based on the starting point
    intervals.sort(key=lambda x: x[0])

    merged_intervals = []

    for interval in intervals:
        if not merged_intervals or merged_intervals[-1][1] < interval[0]:
            merged_intervals.append(interval)
        else:
            merged_intervals[-1][1] = max(merged_intervals[-1][1], interval[1])

    total_length = sum(end - start for start, end in merged_intervals)

    return total_length

def find_complementary_strand(dna_sequence: str) -> str:
    """
    Given a DNA sequence, returns the complementary DNA strand.

    Args:
    dna_sequence (str): A string representing the sequence of nucleotides.

    Returns:
    str: A string representing the complementary DNA strand.

    Raises:
    ValueError: If the dna_sequence contains invalid nucleotide.
    """
    complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}

    try:
        return ''.join(complement[nucleotide] for nucleotide in dna_sequence)
    except KeyError as e:
        raise ValueError(f"Invalid nucleotide '{e.args[0]}' found in the sequence.")

from typing import List, Tuple

def search_2d_matrix(matrix: List[List[int]], target: int) -> Tuple[int, int]:
    if not matrix or not matrix[0]:
        return (-1, -1)

    row = 0
    col = len(matrix[0]) - 1

    while row < len(matrix) and col >= 0:
        if matrix[row][col] == target:
            return (row, col)
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1

    return (-1, -1)

def find_unique_elements(arr):
    """
    Returns a list of integers that appear exactly once in the input array, sorted in ascending order.
    The function will raise a TypeError if the input is not a list of integers.
    """
    if not isinstance(arr, list):
        raise TypeError("Input should be a list")
    if not all(isinstance(x, int) for x in arr):
        raise TypeError("All elements in the input list should be integers")

    from collections import Counter
    element_count = Counter(arr)
    unique_elements = [elem for elem, count in element_count.items() if count == 1]

    return sorted(unique_elements)

def find_min_diff(groupSizes, groupValues):
    """
    Returns the minimum absolute difference between the sums of group sizes
    in the two sub-collections.
    """
    total_sum = sum(groupSizes)
    n = len(groupSizes)

    dp = [[False] * (total_sum // 2 + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(total_sum // 2 + 1):
            if j >= groupSizes[i - 1]:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - groupSizes[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    closest_sum = 0
    for j in range(total_sum // 2 + 1):
        if dp[n][j]:
            closest_sum = j

    return abs(total_sum - 2 * closest_sum)

def is_match(s: str, p: str) -> bool:
    """
    Determines if the string `s` matches the pattern `p`.
    The pattern can include '?' which matches exactly one character and '*' which matches zero or more characters.
    """
    # dp[i][j] will be True if the first `i` characters in `s` can match the first `j` characters in `p`
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Empty pattern matches empty string
    dp[0][0] = True

    # Fill the entries for patterns with leading '*'
    for j in range(1, len(p) + 1):
        if p[j-1] == '*':
            dp[0][j] = dp[0][j-1]

    # Fill the dp table
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j-1] == '*':
                dp[i][j] = dp[i][j-1] or dp[i-1][j]
            elif p[j-1] == '?' or p[j-1] == s[i-1]:
                dp[i][j] = dp[i-1][j-1]

    return dp[len(s)][len(p)]

def find_dominant_character(s):
    """
    Returns the dominant character if one exists, otherwise an empty string.

    A character is dominant if the number of times it appears in the string 
    is strictly greater than the occurrences of all other characters combined.
    """
    if not s:
        return ""

    char_count = {}

    # Count the occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    total_length = len(s)
    for char, count in char_count.items():
        if count > (total_length - count):
            return char

    return ""

from typing import List

def count_unique_triplets(nums: List[int], target: int) -> int:
    """
    Returns the number of unique triplets (a, b, c) in the array such that
    a + b + c = target and a <= b <= c.
    """
    nums.sort()
    triplet_set = set()
    n = len(nums)

    for i in range(n - 2):
        j = i + 1
        k = n - 1
        while j < k:
            total = nums[i] + nums[j] + nums[k]
            if total == target:
                triplet_set.add((nums[i], nums[j], nums[k]))
                j += 1
                k -= 1
            elif total < target:
                j += 1
            else:
                k -= 1

    return len(triplet_set)

from typing import List

def max_height_diff(nums: List[int]) -> int:
    """
    Finds the maximum difference in height between two mountains
    that are separated by at least one other mountain in the list.
    """

    if len(nums) < 3:
        raise ValueError("The list must contain at least three mountains")

    max_diff = 0

    for i in range(1, len(nums) - 1):
        for j in range(i + 1, len(nums)):
            diff = abs(nums[i - 1] - nums[j])
            if diff > max_diff:
                max_diff = diff

    return max_diff

def final_position(commands: str) -> (int, int):
    x, y = 0, 0
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1
    return (x, y)

def first_unique_char(s: str) -> int:
