    If it does not exist, returns -1.
    """
    # Dictionary to keep count of each character
    char_count = {}

    # Populate the dictionary with character counts
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character that has a count of 1
    for index, char in enumerate(s):
        if char_count[char] == 1:
            return index

    # If no unique character found, return -1
    return -1

