def all_pairs_shortest_path(adjacency_matrix: List[List[float]]) -> List[List[float]]:
    """
    Uses the Floyd-Warshall algorithm to compute the shortest paths between all pairs of nodes.
    """
    n = len(adjacency_matrix)
    # Initialize distance matrix with the given adjacency matrix
    dist = [row[:] for row in adjacency_matrix]

    # Applying Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

def longest_substring_same_char(s):
    """
    Given a string s consisting of lowercase English letters, return the length 
    of the longest substring with all characters the same.
    """
    if not s:
        return 0

    max_length = current_length = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    return max(max_length, current_length)

def compute_totient(n: int) -> int:
    if n == 1:
        return 1

    result = n
    p = 2

    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1

    if n > 1:
        result -= result // n

    return result

from collections import deque

def shortest_path(graph, start, end):
    """
    Returns the shortest path from the start intersection to the end intersection
    using Breadth-First Search.
    """
    if start not in graph or end not in graph:
        return []

    queue = deque([[start]])
    visited = set([start])

    while queue:
        path = queue.popleft()
        node = path[-1]

        if node == end:
            return path

        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(path + [neighbor])

    return []

def valid_path(edges, source, destination):
    """
    Determines if there is a valid path from source to destination in a directed graph.
    """
    from collections import defaultdict, deque

    # Create adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # BFS to check for path from source to destination
    to_visit = deque([source])
    visited = set()

    while to_visit:
        current = to_visit.popleft()
        if current == destination:
            return True
        if current not in visited:
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    to_visit.append(neighbor)

    return False

