def bitwise_array_manipulator(arr: List[int], ops: List[Tuple[str, int, int, int]]) -> List[bool]:
    results = []
    for command, index, bit_index, value in ops:
        if command == "get":
            results.append((arr[index] & (1 << bit_index)) != 0)
        elif command == "set":
            arr[index] |= (1 << bit_index)
        elif command == "clear":
            arr[index] &= ~(1 << bit_index)
        elif command == "update":
            if value:
                arr[index] |= (1 << bit_index)
            else:
                arr[index] &= ~(1 << bit_index)
    return results

def most_frequent_kgram(word, k):
    """
    Returns the most frequent k-gram in the given word. If there are multiple with the same frequency, 
    returns the lexicographically smallest one. If `word` is shorter than or equal to `k`, returns `word`.
    """
    if len(word) <= k:
        return word

    kgram_freq = {}

    # Create a frequency dictionary for all k-grams
    for i in range(len(word) - k + 1):
        kgram = word[i:i+k]
        if kgram in kgram_freq:
            kgram_freq[kgram] += 1
        else:
            kgram_freq[kgram] = 1

    # Find the most frequent k-gram, breaking ties lexicographically
    most_frequent_kgram = min(sorted(kgram_freq), key=lambda x: (-kgram_freq[x], x))

    return most_frequent_kgram

def min_difference(tasks):
    """
    Returns the minimum difference possible after distributing all the tasks between the two servers.
    """
    total_sum = sum(tasks)
    n = len(tasks)
    half_sum = total_sum // 2

    dp = [[False] * (half_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(half_sum + 1):
            dp[i][j] = dp[i-1][j]
            if j >= tasks[i-1]:
                dp[i][j] = dp[i][j] or dp[i-1][j-tasks[i-1]]

    for j in range(half_sum, -1, -1):
        if dp[n][j]:
            return total_sum - 2 * j

