def convert_date_format(date_str: str, current_format: str, target_format: str) -> str:
    """
    Converts a date from one string format to another.

    :param date_str: A string representing the date in the current_format.
    :param current_format: A string representing the current format of the date_str.
    :param target_format: A string representing the desired format for the output date string.
    :return: A string representing the date in the target_format.
    """
    date_parts = {}

    if current_format == "YYYY-MM-DD":
        date_parts['year'], date_parts['month'], date_parts['day'] = date_str.split('-')
    elif current_format == "MM/DD/YYYY":
        date_parts['month'], date_parts['day'], date_parts['year'] = date_str.split('/')
    elif current_format == "DD-MM-YYYY":
        date_parts['day'], date_parts['month'], date_parts['year'] = date_str.split('-')

    if target_format == "YYYY-MM-DD":
        return f"{date_parts['year']}-{date_parts['month']}-{date_parts['day']}"
    elif target_format == "MM/DD/YYYY":
        return f"{date_parts['month']}/{date_parts['day']}/{date_parts['year']}"
    elif target_format == "DD-MM-YYYY":
        return f"{date_parts['day']}-{date_parts['month']}-{date_parts['year']}"

def normalize_path(path: str) -> str:
    """
    Normalizes the given file system path to its canonical form.
    """
    parts = path.split("/")
    stack = []

    for part in parts:
        if part == "..":
            if stack:
                stack.pop()
        elif part == "." or not part:
            continue
        else:
            stack.append(part)

    return "/" + "/".join(stack)

def is_valid_sequence(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping:  # Check if the char is a closing bracket
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:  # It is an opening bracket
            stack.append(char)

    return not stack

def rob(nums):
    """
    Returns the maximum amount of money the robber can rob tonight without alerting the police.
    """
    if not nums:
        return 0

    if len(nums) == 1:
        return nums[0]

    rob1, rob2 = 0, 0

    for n in nums:
        new_rob = max(rob1 + n, rob2)
        rob1, rob2 = rob2, new_rob

    return rob2

def construct_directory_tree(paths):
    """
    Constructs a nested dictionary representing directory structure from a list of file paths.
    """
    tree = {}

    for path in paths:
        parts = path.split('/')
        current_level = tree

        # Traverse the path, creating nested dictionaries along the way
        for part in parts:
            if part not in current_level:
                current_level[part] = {}
            current_level = current_level[part]

    return tree

