def prime_factors(n: int) -> List[int]:
    if n < 2:
        raise ValueError("n must be greater than or equal to 2")

    factors = []

    # Check for number of 2s that divide n
    while n % 2 == 0:
        factors.append(2)
        n = n // 2

    # n must be odd at this point, so a skip of 2 (i.e. i = i + 2) can be used
    for i in range(3, int(n**0.5) + 1, 2):
        # While i divides n, add i and divide n
        while n % i == 0:
            factors.append(i)
            n = n // i

    # If n is a prime number greater than 2
    if n > 2:
        factors.append(n)

    return factors

def longest_common_subsequence(str1: str, str2: str) -> int:
    """
    Returns the length of the longest common subsequence between str1 and str2.
    """
    len1, len2 = len(str1), len(str2)

    # Create a DP table with (len1 + 1) x (len2 + 1) dimensions
    dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]

    # Build the DP table
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the longest common subsequence is in the bottom-right cell
    return dp[len1][len2]

