    for i in range(n):
        while 0 < nums[i] <= n and nums[i] != nums[nums[i] - 1]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    # The first index i such that nums[i] is not i + 1 is the answer
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    # If all positions are correct, answer is n + 1
    return n + 1

def final_counter_value(operations):
    """
    Computes the final value of a counter starting at 0 after performing the given operations.

    Parameters:
    operations (list of str): List of operations to perform, where each operation is 
                              one of "+", "-", "++", "--".

    Returns:
    int: The final value of the counter.
    """
    counter = 0
    for operation in operations:
        if operation == "+":
            counter += 1
        elif operation == "-":
            counter -= 1
        elif operation == "++":
            counter += 2
        elif operation == "--":
            counter -= 2
    return counter

import bisect

def process_operations_and_queries(operations, queries1, queries2):
    """
    Perform a list of insertion and deletion operations on a set and respond to subsequent queries.

    :param operations: List of operations, where each operation is a string in the form of "I x" or "D x".
    :param queries1: List of integers for which we need to find the smallest integer in the set that is greater than each integer.
    :param queries2: List of integers for which we need to find the largest integer in the set that is less than each integer.
    :return: List of results for queries1 followed by results for queries2.
    """
    sorted_set = []

    # Process the operations
    for operation in operations:
        command, value = operation.split()
        value = int(value)

        if command == "I":
            if value not in sorted_set:
                bisect.insort(sorted_set, value)
        elif command == "D":
            if value in sorted_set:
                sorted_set.remove(value)

    results = []

    # Handle queries1
    for q1 in queries1:
        index = bisect.bisect_right(sorted_set, q1)
        if index < len(sorted_set):
            results.append(sorted_set[index])
        else:
            results.append(-1)

    # Handle queries2
    for q2 in queries2:
        index = bisect.bisect_left(sorted_set, q2)
        if index > 0:
            results.append(sorted_set[index - 1])
        else:
            results.append(-1)

    return results

