        left, right = i + 1, len(nums) - 1

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]

            if abs(current_sum - target) < abs(closest_sum - target):
                closest_sum = current_sum

            if current_sum < target:
                left += 1
            elif current_sum > target:
                right -= 1
            else:
                return current_sum

    return closest_sum

from typing import Union, List

def total_kinetic_energy(masses: List[float], velocities: List[Union[float, List[float]]]) -> float:
    if len(masses) != len(velocities):
        raise ValueError("Mismatch between number of masses and velocities")

    total_ke = 0.0

    for mass, velocity in zip(masses, velocities):
        if mass <= 0:
            raise ValueError("Invalid mass")

        if isinstance(velocity, (float, int)):
            total_ke += 0.5 * mass * velocity ** 2
        elif isinstance(velocity, list):
            velocity_sum = 0.0
            for v in velocity:
                if not isinstance(v, (float, int)):
                    raise ValueError("Invalid velocity")
                velocity_sum += v ** 2
            total_ke += 0.5 * mass * velocity_sum
        else:
            raise ValueError("Invalid velocity")

    return total_ke

from typing import List

def rotate_90_clockwise(matrix: List[List[int]]) -> None:
    """
    Rotates the given square matrix 90 degrees clockwise in-place.
    """
    n = len(matrix)

    # Step 1: Transpose the matrix (swap rows with columns)
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Step 2: Reverse each row to complete the 90-degree rotation
    for i in range(n):
        matrix[i].reverse()

def min_bonus(ratings):
    n = len(ratings)
    if n == 0: 
        return 0

    bonus = [1] * n

    # First pass from left to right
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            bonus[i] = bonus[i - 1] + 1

    # Second pass from right to left
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            bonus[i] = max(bonus[i], bonus[i + 1] + 1)

    return sum(bonus)

import os
import shutil

def organize_files_by_extension(directory_path: str) -> dict:
    try:
        if not os.path.exists(directory_path):
            return {
                "success": False,
                "data": "Directory does not exist."
            }

        files_moved = False
        for item in os.listdir(directory_path):
            item_path = os.path.join(directory_path, item)

            if os.path.isfile(item_path):
                files_moved = True
                _, extension = os.path.splitext(item)
                if extension:
                    extension = extension[1:].lower()
                else:
                    extension = "no_extension"

                target_dir = os.path.join(directory_path, extension)
                if not os.path.exists(target_dir):
                    os.makedirs(target_dir)

                shutil.move(item_path, os.path.join(target_dir, item))

        if files_moved:
            return {
                "success": True,
                "data": "Files organized successfully."
            }
        else:
            return {
                "success": True,
                "data": "No files to organize."
            }

    except PermissionError:
        return {
            "success": False,
            "data": "Permission denied while accessing the directory."
        }
    except Exception as e:
        return {
            "success": False,
            "data": f"An error occurred: {str(e)}"
        }

import heapq

def priority_queue_operations(operations):
    min_heap = []
    result = []

    for operation in operations:
        if operation.startswith("insert"):
            _, x = operation.split()
            heapq.heappush(min_heap, int(x))
        elif operation == "extract_min":
            if min_heap:
                result.append(heapq.heappop(min_heap))
            else:
                result.append(-1)

    return result

def modified_counting_sort(arr):
    if not arr:
        return []

    min_val = min(arr)
    max_val = max(arr)

    range_of_elements = max_val - min_val + 1
    count_arr = [0] * range_of_elements
    output_arr = [0] * len(arr)

    for num in arr:
        count_arr[num - min_val] += 1

    for i in range(1, len(count_arr)):
        count_arr[i] += count_arr[i-1]

    for num in reversed(arr):
        output_arr[count_arr[num - min_val] - 1] = num
        count_arr[num - min_val] -= 1

    return output_arr

def min_partitions(nums):
    """
    Returns the minimum number of subarrays required to partition 'nums' 
    such that each subarray is sorted in non-decreasing order.
    """
    if not nums:
        return 0

    partitions = 1
    for i in range(1, len(nums)):
        if nums[i] < nums[i - 1]:
            partitions += 1

    return partitions

def convert_temperature(temperature, from_unit, to_unit):
    valid_units = ['Celsius', 'Fahrenheit', 'Kelvin']
    # Check if the units are valid
    if from_unit not in valid_units:
        raise ValueError(f"Invalid temperature unit '{from_unit}'.")
    if to_unit not in valid_units:
        raise ValueError(f"Invalid temperature unit '{to_unit}'.")

    # Check if the temperature is above absolute zero for the given unit
    if from_unit == 'Celsius' and temperature < -273.15:
        raise ValueError("Temperature below absolute zero.")
    if from_unit == 'Kelvin' and temperature < 0:
        raise ValueError("Temperature below absolute zero.")
    if from_unit == 'Fahrenheit' and temperature < -459.67:
        raise ValueError("Temperature below absolute zero.")

    # Convert the temperature to Celsius first
    if from_unit == 'Celsius':
        temp_celsius = temperature
    elif from_unit == 'Fahrenheit':
        temp_celsius = (temperature - 32) * 5.0/9.0
    elif from_unit == 'Kelvin':
        temp_celsius = temperature - 273.15

    # Now convert from Celsius to the target unit
    if to_unit == 'Celsius':
        return temp_celsius
    elif to_unit == 'Fahrenheit':
        return temp_celsius * 9.0/5.0 + 32
    elif to_unit == 'Kelvin':
        return temp_celsius + 273.15

def count_unique_pairs(arr, target_sum):
    """
    Returns the number of unique pairs of elements in the array that add up to target_sum.
    """
    seen = set()
    pairs = set()

    for num in arr:
        complement = target_sum - num
        if complement in seen:
            pairs.add(tuple(sorted((num, complement))))
        seen.add(num)

    return len(pairs)

def rob(nums, k):
    """
    Returns the maximum amount of money that can be robbed from the houses,
    considering that after robbing one house, you must skip at least k houses.

    :param nums: List[int] - list of integers representing the amount of money at each house
    :param k: int - the number of houses you must skip after robbing one house
    :return: int - the maximum amount of money you can rob
    """
    if not nums:
        return 0

    n = len(nums)
    if k >= n:
        return max(nums)

    dp = [0] * n
    dp[0] = nums[0]

    for i in range(1, n):
        if i <= k:
            dp[i] = max(dp[i-1], nums[i])
        else:
            dp[i] = max(dp[i-1], nums[i] + dp[i-k-1])

    return max(dp)

def is_grid_fully_covered(rows: int, cols: int, objects: list) -> bool:
    # Set to keep track of all required cells
    required_cells = {(r, c) for r in range(rows) for c in range(cols)}

    # Iterate over all objects and remove their covered cells from required_cells
    for obj in objects:
        for cell in obj:
            if cell in required_cells:
                required_cells.remove(cell)

    if required_cells:
        # If there are any cells left in required_cells, print them
        print(f"Cells not covered: {required_cells}")
        return False

    return True

def is_merge(s: str, part1: str, part2: str) -> bool:
    """
    Determines if the string s can be formed by interleaving part1 and part2 in the same order.
    """
    # If the combined length of part1 and part2 is not equal to s, return False
    if len(s) != len(part1) + len(part2):
        return False

    # Dynamic programming approach to solve the merging problem
    dp = [[False] * (len(part2) + 1) for _ in range(len(part1) + 1)]
    dp[0][0] = True

    for i in range(len(part1) + 1):
        for j in range(len(part2) + 1):
            if i > 0 and s[i + j - 1] == part1[i - 1]:
                dp[i][j] = dp[i][j] or dp[i - 1][j]
            if j > 0 and s[i + j - 1] == part2[j - 1]:
                dp[i][j] = dp[i][j] or dp[i][j - 1]

    return dp[len(part1)][len(part2)]

def rearrange_string(s: str) -> str:
    letters = []
    digits = []
    special_chars = []

    for char in s:
        if char.isalpha():
            letters.append(char)
        elif char.isdigit():
            digits.append(char)
        else:
            special_chars.append(char)

    letters.sort(key=lambda x: (x.islower(), x))
    digits.sort()

    return ''.join(letters) + ''.join(digits) + ''.join(special_chars)

def unique_paths_with_obstacles(grid):
    """
    Returns the number of unique paths from the top-left to the bottom-right
    of the grid that avoid obstacles.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1

    # Initialize the first column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]

    # Initialize the first row
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j - 1]

    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]

    return dp[-1][-1]

def decode_string(s: str) -> str:
    stack = []
    current_num = 0
    current_string = ''

    for char in s:
        if char.isdigit():
            current_num = current_num * 10 + int(char)
        elif char == '[':
            stack.append((current_string, current_num))
            current_string = ''
            current_num = 0
        elif char == ']':
            prev_string, num = stack.pop()
            current_string = prev_string + current_string * num
        else:
            current_string += char

    return current_string

def repeat_substring(s: str) -> bool:
    """
    Determine if a given non-empty string can be constructed by repeating a substring multiple times.
    """
    n = len(s)
    for i in range(1, n // 2 + 1):
        if n % i == 0:
            if s[:i] * (n // i) == s:
                return True
    return False

from typing import List, Tuple

def final_position(commands: List[str]) -> Tuple[int, int]:
    """
    Calculates the final position of the robot after executing a series of movement commands.

    Parameters:
    commands (list of str): A list of movement commands ('UP', 'DOWN', 'LEFT', 'RIGHT').

    Returns:
    tuple: Final coordinates (x, y) on the 2D plane.
    """
    x, y = 0, 0  # initial position

    # process each command
    for command in commands:
        if command == "UP":
            y += 1
        elif command == "DOWN":
            y -= 1
        elif command == "LEFT":
            x -= 1
        elif command == "RIGHT":
            x += 1

    return (x, y)

from typing import List

def ternary_search(arr: List[int], left: int, right: int, key: int) -> int:
    while left <= right:
        one_third = left + (right - left) // 3
        two_third = right - (right - left) // 3

        if arr[one_third] == key:
            return one_third
        if arr[two_third] == key:
            return two_third

        if key < arr[one_third]:
            right = one_third - 1
        elif key > arr[two_third]:
            left = two_third + 1
        else:
            left = one_third + 1
            right = two_third - 1

    return -1

def comb_sort(arr):
    """
    Sorts a list of integers in ascending order using the Comb Sort algorithm.
    """
    if not arr:
        return arr

    n = len(arr)
    gap = n
    shrink_factor = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink_factor)
        if gap <= 1:
            gap = 1
            sorted = True

        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False

    return arr

def max_consecutive_ones(binary_array: list) -> int:
    """
    Returns the length of the longest sequence of consecutive 1s in the given binary array.
    """
    max_count = 0
    current_count = 0

    for num in binary_array:
        if num == 1:
            current_count += 1
        else:
            max_count = max(max_count, current_count)
            current_count = 0

    return max(max_count, current_count)  # Handle the case where the array ends with a sequence of 1s.

from collections import deque

def min_steps_to_reach_end(grid):
    """
    Returns the minimum number of steps required to reach the bottom-right corner
    of the grid from the top-left corner. If it is not possible, return -1.
    """
    if not grid or not grid[0]:
        return -1

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right
    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set((0, 0))

    while queue:
        row, col, dist = queue.popleft()

        if row == rows - 1 and col == cols - 1:
            return dist

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            if 0 <= new_row < rows and 0 <= new_col < cols:
                if (new_row, new_col) not in visited and grid[new_row][new_col] <= grid[row][col]:
                    visited.add((new_row, new_col))
                    queue.append((new_row, new_col, dist + 1))

    return -1

def next_permutation(s: str) -> str:
    """
    Returns the next lexicographical permutation of the input string.
    If no such permutation exists, returns the smallest permutation (sorted in ascending order).
    """
    s = list(s)
    n = len(s)

    # Step 1: Find the largest index k such that s[k] < s[k + 1]. If no such index exists, the permutation is the last permutation.
    k = -1
    for i in range(n - 1):
        if s[i] < s[i + 1]:
            k = i

    if k == -1:
        # The string is in descending order
        s.sort()
        return ''.join(s)

    # Step 2: Find the largest index l greater than k such that s[k] < s[l].
    l = -1
    for i in range(n):
        if s[k] < s[i]:
            l = i

    # Step 3: Swap the value of s[k] with that of s[l].
    s[k], s[l] = s[l], s[k]

    # Step 4: Reverse the sequence from s[k + 1] up to and including the final element s[n - 1].
    s = s[:k + 1] + s[k + 1:][::-1]

    return ''.join(s)

def minimum_distance(words, word1, word2):
    """
    Returns the minimum distance between word1 and word2 in the list of words.
    Distance is defined as the number of elements between the two words (inclusive).
    """
    pos1, pos2 = -1, -1
    min_distance = float('inf')

    for i, word in enumerate(words):
        if word == word1:
            pos1 = i
        if word == word2:
            pos2 = i
        if pos1 != -1 and pos2 != -1:
            min_distance = min(min_distance, abs(pos2 - pos1) + 1)

    return min_distance

