def is_subsequence_sum_possible(arr, t):
    """
    Returns true if there exists a sub-sequence of `arr` whose sum is equal to `t`, otherwise false.
    """
    n = len(arr)
    # Using a set to store sums of sub-sequences
    dp = {0}

    for num in arr:
        new_dp = dp.copy()
        for sum_in_dp in dp:
            new_sum = sum_in_dp + num
            if new_sum == t:
                return True
            new_dp.add(new_sum)
        dp = new_dp

    return t in dp

def max_points(colors):
