def construct_lexicographically_smallest_string(s, t):
    """
    Construct the lexicographically smallest string by transforming s using characters from t.

    Args:
        s (str): The original string.
        t (str): The transformation string.

    Returns:
        str: The lexicographically smallest string that can be obtained.
    """
    result = []

    for i in range(len(s)):
        if s[i] < t[i]:
            result.append(s[i])
        else:
            result.append(t[i])

    return ''.join(result)

def find_longest_substring(s: str) -> int:
    """
    Returns the length of the longest substring containing all unique characters.

    Raises a TypeError if the input is not a string.
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    n = len(s)
    if n == 0:
        return 0

    max_len = 0
    start = 0
    char_index_map = {}

    for end in range(n):
        if s[end] in char_index_map and char_index_map[s[end]] >= start:
            start = char_index_map[s[end]] + 1

        char_index_map[s[end]] = end
        max_len = max(max_len, end - start + 1)

    return max_len

def remove_k_characters(s, k):
    """
    Returns the lexicographically smallest string after removing exactly k characters from s.
    """
    stack = []
    for char in s:
        while k > 0 and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)

    # If there are still characters to remove, remove them from the end of the stack
    return ''.join(stack[:len(stack)-k])

def split_path(path: str) -> tuple:
    """
    Splits the given path into directory and file components.

    Parameters:
    path (str): The path to be split.

    Returns:
    tuple: A tuple containing the directory part and the file part.
    """
    if path == '':
        return ('', '')

    # Find the last occurrence of '/'
    index = path.rfind('/')

    if index == -1:
        # No '/' in the path
        return ('', path)
    elif index == len(path) - 1:
        # The path ends with a '/'
        return (path.rstrip('/'), '')
    else:
        return (path[:index], path[index + 1:])

