def top_rated_movies(reviews: List[Tuple[str, int]]) -> List[str]:
    if not reviews:
        return []

    movie_ratings = {}

    for movie, rating in reviews:
        if movie not in movie_ratings:
            movie_ratings[movie] = [0, 0]  # [sum of ratings, number of ratings]
        movie_ratings[movie][0] += rating
        movie_ratings[movie][1] += 1

    max_avg_rating = -1
