def max_product_of_two(arr):
    """
    Returns the maximum product of two distinct elements in the array.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements.")

    max1 = max2 = 0

    # Traverse the array to find the two largest elements
    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

    return max1 * max2

def longest_substring_with_k_distinct_chars(s, k):
    """
    Returns the length of the longest substring with at most k distinct characters.
    """
    if k == 0:
        return 0

    n = len(s)
    left = 0
    right = 0
    max_length = 0
    char_map = {}

    while right < n:
        if s[right] not in char_map:
            char_map[s[right]] = 0
        char_map[s[right]] += 1

        while len(char_map) > k:
            char_map[s[left]] -= 1
            if char_map[s[left]] == 0:
                del char_map[s[left]]
            left += 1

        max_length = max(max_length, right - left + 1)
        right += 1

    return max_length

def min_distance(s, t):
    """
    Returns the minimum number of operations required to convert string s to string t.
    The allowed operations are insert, delete, and replace a character.
    """
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # Need to insert all characters of t
            elif j == 0:
                dp[i][j] = i  # Need to delete all characters of s
            elif s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # Characters are the same, no operation needed
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # Deletion
                                   dp[i][j - 1],    # Insertion
                                   dp[i - 1][j - 1]) # Replacement

    return dp[m][n]

