from typing import List, Tuple

def is_path_exists(vertex_count: int, edges: List[Tuple[int, int]], source: int, target: int) -> bool:
    from collections import defaultdict, deque

    # Create graph as adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Perform BFS to find path from source to target
    visited = [False] * vertex_count
    queue = deque([source])
    visited[source] = True

    while queue:
        current = queue.popleft()
        if current == target:
            return True
        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    return False

def find_insertion_index(arr: list[int], target: int) -> int:
    """
    This function uses binary search to find the index where the target should be inserted
    in order to maintain the array's sorted order.
    """
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

def find_potential_duplicates(users):
