            name_dict[name] = [user_id]

        if email in email_dict:
            for duplicate_id in email_dict[email]:
                duplicates.add((min(user_id, duplicate_id), max(user_id, duplicate_id)))
            email_dict[email].append(user_id)
        else:
            email_dict[email] = [user_id]

    return sorted(list(duplicates))

def convert(s: str, numRows: int) -> str:
    if numRows == 1 or numRows >= len(s):
        return s

    # Initialize a list of strings for each row
    rows = [''] * numRows
    current_row = 0
    going_down = False

    for char in s:
        rows[current_row] += char
        if current_row == 0 or current_row == numRows - 1:
            going_down = not going_down
        current_row += 1 if going_down else -1

    # Concatenate all rows and return
    return ''.join(rows)

def length_of_LIS(arr):
    """
    Returns the length of the longest increasing subsequence in the given list `arr`.
    """
    if not arr:
        return 0

    dp = [1] * len(arr)

    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

from collections import deque

def minSteps(grid):
    n = len(grid)
    if n == 0 or grid[0][0] == 0:
        return -1

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    visited = [[False] * n for _ in range(n)]
    queue = deque([(0, 0, 0)])  # (x, y, steps)
    visited[0][0] = True

    while queue:
        x, y, steps = queue.popleft()

        if x == n-1 and y == n-1:
            return steps

        max_steps = grid[x][y]

        for dx, dy in directions:
            for i in range(1, max_steps + 1):
                nx, ny = x + dx * i, y + dy * i
                if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                    visited[nx][ny] = True
                    queue.append((nx, ny, steps + 1))

    return -1

def partition_labels(s):
    """
    Returns a list of integers representing the lengths of the longest possible substrings,
    such that each letter appears in at most one substring.
    """
    last_occurrences = {char: idx for idx, char in enumerate(s)}
    partitions = []
    start, end = 0, 0

    for idx, char in enumerate(s):
        end = max(end, last_occurrences[char])
        if idx == end:
            partitions.append(end - start + 1)
            start = idx + 1

    return partitions

def compute_binomial_coefficient(n: int, k: int) -> int:
    """
    This function computes the binomial coefficient C(n, k) using a recursive method.
    """
    # Base cases
    if k == 0 or k == n:
        return 1

    # Recursive case
    return compute_binomial_coefficient(n - 1, k - 1) + compute_binomial_coefficient(n - 1, k)

def move_zeros_inplace(array: list) -> None:
    """
    Move all zeros in the list to the end, preserving the order of other elements.
    """
    n = len(array)
    non_zero_index = 0  # Pointer to place the next non-zero element

    for current in range(n):
        if isinstance(array[current], bool) or array[current] != 0:
            array[non_zero_index], array[current] = array[current], array[non_zero_index]
            non_zero_index += 1

def remove_adjacent_duplicates(s):
    """
    Function to remove adjacent duplicates in a string until no more adjacent duplicates exist.
    :param s: input string consisting of lowercase English letters
    :return: final string after all duplicate removal operations
    """
    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

def custom_sort_string(order, string):
    """
    Sorts `string` according to the custom order defined in `order`.
    Characters not in `order` are appended to the end in their original order.
    """
    order_index = {char: i for i, char in enumerate(order)}
    # Sort the string based on custom order
    sorted_string = sorted(string, key=lambda char: order_index.get(char, len(order)))
    return ''.join(sorted_string)

def delete_reoccurring_characters(string: str) -> str:
    """
    Returns a new string with all reoccurring characters removed,
    keeping only the first occurrence of each character.
    """
    seen = set()
    result = []

    for char in string:
        if char not in seen:
            seen.add(char)
            result.append(char)

    return ''.join(result)

from typing import List

def smallest_derangement(n: int) -> List[int]:
    if n == 2:
        return [2, 1]

    derangement = list(range(1, n + 1))

    for i in range(0, n - 1, 2):
        derangement[i], derangement[i + 1] = derangement[i + 1], derangement[i]

    if n % 2 == 1:
        derangement[-1], derangement[-2] = derangement[-2], derangement[-1]

    return derangement

def has_pair_with_sum(arr, target_sum):
    """
    Checks if there are two distinct elements in the array that add up to target_sum.
    """
    seen = set()
    for number in arr:
        if target_sum - number in seen:
            return True
        seen.add(number)
