def count_pairs(nums, target):
    """
    Returns the number of different pairs (i, j) 
    such that nums[i] + nums[j] == target and i < j.
    """
    count = 0
    num_dict = {}
    for num in nums:
        complement = target - num
        if complement in num_dict:
            count += num_dict[complement]
        if num in num_dict:
            num_dict[num] += 1
        else:
            num_dict[num] = 1

    return count

def can_be_equal(target, arr):
