def largest_increasing_subsequence_sum(arr: list) -> int:
    """
    Returns the sum of the largest increasing subsequence in the array.

    Parameters:
    arr (list): the array of integers

    Returns:
    int: the sum of the largest increasing subsequence
    """
    n = len(arr)
    if n == 0:
        return 0

    # Initialize an array to store the maximum sum of increasing subsequence ending at each index
    sums = arr[:]

    # Fill the sums array using Dynamic Programming
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and sums[i] < sums[j] + arr[i]:
                sums[i] = sums[j] + arr[i]

    # The maximum value in sums array is the result
    return max(sums)

def subarray_sum(nums: list[int], k: int) -> int:
    """
    Returns the total number of continuous subarrays whose sum equals k.
    """
    count = 0
    cumulative_sum = 0
    sum_frequencies = {0: 1}

    for num in nums:
        cumulative_sum += num
        if (cumulative_sum - k) in sum_frequencies:
            count += sum_frequencies[cumulative_sum - k]
        if cumulative_sum in sum_frequencies:
            sum_frequencies[cumulative_sum] += 1
        else:
            sum_frequencies[cumulative_sum] = 1

    return count

