def quickest_responder(times: List[Tuple[int, int]]) -> int:
    """
    Finds the employee ID with the fastest average email response time.

    Parameters:
    times (List[Tuple[int, int]]): A list where each element is a tuple containing an employee ID and their email response time in minutes.

    Returns:
    int: The ID of the employee with the fastest average response time.

    Raises:
    ValueError: If the list 'times' is empty.
    """
    if not times:
        raise ValueError("The input list cannot be empty")

    # Create a dictionary to store cumulative response times and count of emails per employee
    response_data = {}

    for emp_id, response_time in times:
        if emp_id in response_data:
            response_data[emp_id]['total_time'] += response_time
            response_data[emp_id]['count'] += 1
        else:
            response_data[emp_id] = {'total_time': response_time, 'count': 1}

    # Compute the average response times
    average_response_times = {emp_id: data['total_time'] / data['count'] for emp_id, data in response_data.items()}

    # Find the employee ID with the smallest average response time
    quickest_employee = min(average_response_times, key=average_response_times.get)

    return quickest_employee

def bit_manipulation(num: int, i: int, action: str, bit: int = None) -> int:
    """
    Perform bit manipulation on the given integer `num`.

    Parameters:
    - num: The integer to be manipulated.
    - i: The index of the bit to be manipulated.
    - action: The type of manipulation. One of 'get', 'set', 'clear', or 'update'.
    - bit: The value to set the bit to, applicable only for 'update'.

    Returns:
    - Result of the bit manipulation or the bit value for 'get' action.
    """

    # Perform the specified action
    if action == 'get':
        return (num >> i) & 1
    elif action == 'set':
        return num | (1 << i)
    elif action == 'clear':
        return num & ~(1 << i)
    elif action == 'update':
        if bit not in [0, 1]:
            raise ValueError("bit must be either 0 or 1 for 'update' action")
        return (num & ~(1 << i)) | (bit << i)
    else:
        raise ValueError("Invalid action. Choose from 'get', 'set', 'clear', 'update'.")

def manage_inventory(transactions):
