    return inventory

def find_pattern(pattern: str, text: str) -> int:
    """
    Uses the Rabin-Karp algorithm to find the first occurrence of the pattern in the text.
    Returns the starting index of the first occurrence if found, otherwise returns -1.
    """
    # Base parameters for the Rabin-Karp algorithm
    base = 256
    prime = 101

    m = len(pattern)
    n = len(text)

    # Early exit if pattern length is greater than text length
    if m > n:
        return -1

    # Compute the hash value for the pattern and the first window of the text
    pattern_hash = 0
    text_hash = 0
    h = 1

    for i in range(m-1):
        h = (h * base) % prime

    for i in range(m):
        pattern_hash = (base * pattern_hash + ord(pattern[i])) % prime
        text_hash = (base * text_hash + ord(text[i])) % prime

    for i in range(n - m + 1):
        if pattern_hash == text_hash:
            # Verify the characters if hash matches
            for j in range(m):
                if text[i + j] != pattern[j]:
                    break
            else:
                return i

        if i < n - m:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + m])) % prime
            if text_hash < 0:
                text_hash += prime

    return -1

def min_edit_distance(word1: str, word2: str) -> int:
    """
    Calculate the minimum edit distance between two words using dynamic programming.
    """
    m, n = len(word1), len(word2)

    # Initialize the DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the base cases
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Compute the edit distances
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # Deletion
                                   dp[i][j - 1],    # Insertion
                                   dp[i - 1][j - 1]) # Substitution

    return dp[m][n]

def longest_common_subsequence(s1, s2):
    import bisect

    # Step 1: Create an index map from characters in s2 to their positions
    index_map = {char: idx for idx, char in enumerate(s2)}
    # Step 2: Filter only those characters from s1 that are in s2 and map to the indices
    filtered_s1_indices = [index_map[char] for char in s1 if char in index_map]

    # Step 3: Use a list to store the longest increasing subsequence (LIS)
    lis = []

    for idx in filtered_s1_indices:
        pos = bisect.bisect_left(lis, idx)
        if pos == len(lis):
            lis.append(idx)
        else:
            lis[pos] = idx

    # The length of lis list is the length of longest common subsequence
    return len(lis)

def longest_common_subsequence(nums1, nums2):
    """
    Returns the length of the longest possible subsequence of nums1 that is also a subsequence in nums2.
    """
    n, m = len(nums1), len(nums2)

    # dp[i][j] will store the length of the longest common subsequence of nums1[0..i-1] and nums2[0..j-1]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if nums1[i - 1] == nums2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][m]

def limit(arr, min_lim=None, max_lim=None):
    """
    Filters the given array so that only elements in the specified range are included.

    Parameters:
    arr (list): List of integers to be filtered.
    min_lim (int, optional): Minimum limit of the range (inclusive). Default is None, which means no minimum limit.
    max_lim (int, optional): Maximum limit of the range (inclusive). Default is None, which means no maximum limit.

    Returns:
    list: A new list containing only elements within the specified range.
    """
    if min_lim is None:
        if arr:
            min_lim = min(arr)
        else:
            min_lim = -float('inf')  # effectively no minimum limit in an empty array case

    if max_lim is None:
        if arr:
            max_lim = max(arr)
        else:
            max_lim = float('inf')  # effectively no maximum limit in an empty array case

    return [x for x in arr if min_lim <= x <= max_lim]

def fib(n: int) -> int:
    """
    Returns the nth Fibonacci number using constant space.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

