    char_to_word = {}
    word_to_char = {}

    for c, word in zip(pattern, words):
        if c in char_to_word:
            if char_to_word[c] != word:
                return False
        else:
            if word in word_to_char:
                return False
            char_to_word[c] = word
            word_to_char[word] = c

    return True

def minAddToMakeValid(s: str) -> int:
    """
    Returns the minimum number of parentheses to add to make the string valid.
    """
    left_balance = 0
    right_balance = 0

    for char in s:
        if char == '(':
            left_balance += 1
        elif char == ')':
            if left_balance > 0:
                left_balance -= 1
            else:
                right_balance += 1

    return left_balance + right_balance

def max_perimeter_triangle(nums):
    """
    Returns the maximum perimeter of a triangle that can be formed with three of these stick lengths.
    If no valid triangle can be formed, returns 0.
    """
    nums.sort(reverse=True)
    for i in range(len(nums) - 2):
        if nums[i] < nums[i + 1] + nums[i + 2]:
            return nums[i] + nums[i + 1] + nums[i + 2]
    return 0

def find_peak_element(nums: list[int]) -> int:
    """
    Finds the index of a peak element in the array.
    A peak element is greater than its neighbors. For corner elements, it is compared to only one neighbor.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        if nums[mid] < nums[mid + 1]:
            left = mid + 1
        else:
            right = mid

    return left

from typing import List, Tuple, Optional

def detect_one_sparse(stream: List[Tuple[int, str]]) -> Optional[int]:
    """
    Determine if the sequence is 1-sparse, and if so, return the unique number.
    If not, return None.
    """
    counter = {}

    for num, sign in stream:
        if sign == '+':
            if num in counter:
                counter[num] += 1
            else:
                counter[num] = 1
        elif sign == '-':
            if num in counter:
                counter[num] -= 1
            else:
                counter[num] = -1

    unique_nums = [num for num, count in counter.items() if count != 0]

    if len(unique_nums) == 1:
        return unique_nums[0]
    else:
        return None

