import math

def is_prime(n: int) -> bool:
    """
    Returns True if n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sort_colors(nums):
    """
    Sorts a list of integers representing colors in-place such that balls of the same color are adjacent and follow the order red (0), white (1), and blue (2).
    """
    low, mid, high = 0, 0, len(nums) - 1

    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[high], nums[mid] = nums[mid], nums[high]
            high -= 1

def max_sum_non_adjacent(arr):
    if not arr:
        return 0
    if len(arr) == 1:
        return max(0, arr[0])

    include = 0
    exclude = 0

    for num in arr:
        new_exclude = max(include, exclude)
        include = exclude + num
        exclude = new_exclude

    return max(include, exclude)

