            result = [
                {'word': word, 'count': count}
                for word, count in most_common_words
            ]
            return result
    except Exception:
        return None

from typing import List

def sparse_matrix_multiply(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    """
    Multiplies two sparse matrices A and B and returns the resultant matrix.
    """
    # Number of rows and columns in the result matrix
    result_rows = len(A)
    result_cols = len(B[0])
    B_rows = len(B)

    # Initialize result matrix with all zeroes
    result = [[0] * result_cols for _ in range(result_rows)]

    # For each row in A
    for i in range(result_rows):
        for k in range(B_rows):
            if A[i][k] != 0:
                for j in range(result_cols):
                    if B[k][j] != 0:
                        result[i][j] += A[i][k] * B[k][j]

    return result

