from typing import List

def pigeonhole_sort(arr: List[int]) -> List[int]:
    if len(arr) == 0:
        return arr

    min_value = min(arr)
    max_value = max(arr)
    size = max_value - min_value + 1

    holes = [0] * size

    for number in arr:
        holes[number - min_value] += 1

    sorted_arr = []
    for i in range(size):
        while holes[i] > 0:
            sorted_arr.append(i + min_value)
            holes[i] -= 1

    return sorted_arr

from typing import List

def enhanced_pigeonhole_sort(arr: List[int]) -> List[int]:
    if not arr:
        return []

    min_value = min(arr)
    max_value = max(arr)
    range_size = max_value - min_value + 1

    if range_size > 1000000:  # Handle very large ranges to avoid memory issues.
        return sorted(arr)

    holes = [0] * range_size

    for number in arr:
        holes[number - min_value] += 1

    sorted_arr = []
    for index, count in enumerate(holes):
        if count > 0:
            sorted_arr.extend([index + min_value] * count)

    return sorted_arr

