def optimized_exchange_sort(arr: List[int]) -> List[int]:
    """
    Sorts the array using an optimized version of exchange sort with early termination check.
    """
    n = len(arr)
    for i in range(n - 1):
        swapped = False
        for j in range(n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

def decode_ways(encoded_message: str) -> int:
    if not encoded_message or encoded_message[0] == '0':
        return 0

    n = len(encoded_message)
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1

    for i in range(2, n + 1):
        one_digit = int(encoded_message[i - 1:i])
        two_digits = int(encoded_message[i - 2:i])

        if 1 <= one_digit <= 9:
            dp[i] += dp[i - 1]

        if 10 <= two_digits <= 26:
            dp[i] += dp[i - 2]

    return dp[n]

