    # Check if the max height is at the center index
    if peak_index != n // 2:
        return False

    # Check the left side (strictly increasing)
    for i in range(peak_index):
        if heights[i] >= heights[i + 1]:
            return False

    # Check the right side (strictly decreasing)
    for i in range(peak_index, n - 1):
        if heights[i] <= heights[i + 1]:
            return False

    return True

