def count_unique_paths(m: int, n: int) -> int:
    if m <= 0 or n <= 0:
        return 0

    # Create a 2D list to store the number of paths to each cell
    dp = [[0] * n for _ in range(m)]

    # Initialize the paths for the first column and row
    for i in range(m):
        dp[i][0] = 1
    for j in range(n):
        dp[0][j] = 1

    # Fill the rest of the dp array
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

