def count_decompositions(n: int) -> int:
    """
    Calculate the number of ways a given positive integer n can be decomposed into the sum of smaller positive integers.
    """
    # Initialize a 2D array to store the number of ways to decompose `i` using integers up to `j`
    arr = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the table
    for i in range(n + 1):
        for j in range(n + 1):
            if i == 0:
                arr[i][j] = 1  # There's one way to decompose 0
            elif j == 0:
                arr[i][j] = 0  # No way to decompose unless we use positive integers
            elif i < j:
                arr[i][j] = arr[i][i]  # If i < j, use the number of ways to decompose i with itself as the limit
            else:
                arr[i][j] = arr[i][j - 1] + arr[i - j][j]  # Use the sum of ways to decompose i with j-1 and i-j with j

    return arr[n][n]

