def longestSubarrayWithSumK(arr: List[int], k: int) -> int:
    sum_map = {}
    current_sum = 0
    max_length = 0

    for i in range(len(arr)):
        # Add the current element to the current_sum
        current_sum += arr[i]

        # If current_sum is equal to k, we found a subarray starting from index 0
        if current_sum == k:
            max_length = i + 1

        # If (current_sum - k) exists in sum_map, update max_length if we get a larger subarray length
        if (current_sum - k) in sum_map:
            max_length = max(max_length, i - sum_map[current_sum - k])

        # Add current_sum to sum_map if it is not already present
        if current_sum not in sum_map:
            sum_map[current_sum] = i

    return max_length

def is_subset_sum(arr, x):
    """
    Determine if there is a subset of arr that sums up to x.

    Parameters:
    arr (list): List of positive integers.
    x (int): Target sum.

    Returns:
    bool: True if there is a subset that sums up to x, False otherwise.
    """

    n = len(arr)
    subset = [[False for j in range(x + 1)] for i in range(n + 1)]

    for i in range(n + 1):
        subset[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, x + 1):
            if j < arr[i-1]:
                subset[i][j] = subset[i-1][j]
            if j >= arr[i-1]:
                subset[i][j] = (subset[i-1][j] or subset[i-1][j-arr[i-1]])

    return subset[n][x]

def next_bigger(num: int) -> int:
    digits = [int(d) for d in str(num)]
    n = len(digits)

    # Step 1: Find the rightmost digit that is smaller than the digit next to it.
    for i in range(n-2, -1, -1):
        if digits[i] < digits[i + 1]:
            break
    else:
        # If no such digit is found, that means we are already at the largest permutation
        return -1

    # Step 2: Find the smallest digit on right side of (i) which is larger than digits[i]
    for j in range(n-1, i, -1):
        if digits[j] > digits[i]:
            break

    # Step 3: Swap digits[i] and digits[j]
    digits[i], digits[j] = digits[j], digits[i]

    # Step 4: Reverse the digits after index i
    digits = digits[:i+1] + digits[i+1:][::-1]

    return int(''.join(map(str, digits)))

