def can_split_into_pairs(arr, m):
    """
    Returns True if the given array can be split into pairs such that the sum of each pair equals m, 
    otherwise returns False.
    """
    from collections import Counter

    if len(arr) % 2 != 0:
        return False

    count = Counter(arr)

    for num in arr:
        if count[num] == 0:
            continue

        complement = m - num
        if count[complement] > 0:
            count[num] -= 1
            count[complement] -= 1
        else:
            return False

    return True

