def snake_matrix(rows: int, columns: int) -> List[List[int]]:
    """
    Generates a snake-like pattern matrix with the given number of rows and columns.
    """
    matrix = [[0] * columns for _ in range(rows)]
    num = 1

    for r in range(rows):
        if r % 2 == 0:
            for c in range(columns):
