def run_length_encode(s: str) -> str:
    """
    Encodes a given string using Run-Length Encoding (RLE).
    """
    if not s:
        return ""

    encoded_string = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            encoded_string.append(f"{current_char}{count}")
            current_char = char
            count = 1

    encoded_string.append(f"{current_char}{count}")

    return ''.join(encoded_string)

