from collections import deque

def is_path_exists(n: int, edges: List[Tuple[int, int]], source: int, target: int) -> bool:
    """
    Determines if there is a path between the given source and target vertex.
    """

    if source == target:
        return True

    adjacency_list = [[] for _ in range(n)]
    for u, v in edges:
        adjacency_list[u].append(v)

    visited = [False] * n
    queue = deque([source])

    while queue:
        node = queue.popleft()
        if node == target:
            return True
        if not visited[node]:
            visited[node] = True
            for neighbor in adjacency_list[node]:
                if not visited[neighbor]:
                    queue.append(neighbor)

    return False

