    Returns the minimum number of parentheses to be added to make the string valid.
    """
    left_balance = 0  # Tracks unbalanced '('
    right_balance = 0 # Tracks unbalanced ')'

    for char in s:
        if char == '(':
            left_balance += 1
        elif char == ')':
            if left_balance > 0:
                left_balance -= 1
            else:
                right_balance += 1

    return left_balance + right_balance

