    return x == 0 and y == 0

def extended_gcd(num1: int, num2: int) -> (int, int, int):
    """
    Returns the coefficients (s, t) and the GCD (g) of num1 and num2 such that:
    num1 * s + num2 * t = g
    """
    if num2 == 0:
        return (1, 0, num1)
    else:
        s, t, g = extended_gcd(num2, num1 % num2)
        return (t, s - (num1 // num2) * t, g)

def three_sum_closest(nums, target):
    """
    Returns the sum of the triplet in nums that is closest to the target.
    """
    nums.sort()
    closest_sum = float('inf')

    for i in range(len(nums) - 2):
        left, right = i + 1, len(nums) - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                return current_sum
            if abs(current_sum - target) < abs(closest_sum - target):
                closest_sum = current_sum
            if current_sum < target:
                left += 1
            else:
                right -= 1

    return closest_sum

def bubble_sort(arr, simulation=False):
    """
