def atbash_cipher(s: str) -> str:
    """
    Applies the Atbash cipher to the input string `s`.
    """
    result = []

    for char in s:
        if char.isalpha():
            if char.islower():
                result.append(chr(219 - ord(char)))  # 'a' + 'z' = 219
            elif char.isupper():
                result.append(chr(155 - ord(char)))  # 'A' + 'Z' = 155
        else:
            result.append(char)

    return ''.join(result)

