def sieve_of_eratosthenes(n: int) -> List[int]:
    """
    Implements the Sieve of Eratosthenes algorithm and returns a list of primes up to and including n.
    """
    if n < 2:
        return []

    primes = [True] * (n + 1)
    p = 2

    while p * p <= n:
        if primes[p]:
            for i in range(p * p, n + 1, p):
                primes[i] = False
        p += 1

    return [p for p in range(2, n + 1) if primes[p]]

