def subarray_sum(arr, k):
    """
    Given an integer array `arr` and an integer `k`, this function returns the total number of subarrays
    whose sum equals to `k`.
    """
    count = 0
    current_sum = 0
    sum_map = {0: 1}

    for num in arr:
        current_sum += num
        if current_sum - k in sum_map:
            count += sum_map[current_sum - k]
        if current_sum in sum_map:
            sum_map[current_sum] += 1
        else:
            sum_map[current_sum] = 1

    return count

