            count += 1
        else:
            compressed_string.append(f"{s[i - 1]}{count}")
            count = 1

    compressed_string.append(f"{s[-1]}{count}")

    compressed_result = ''.join(compressed_string)
    return compressed_result if len(compressed_result) < len(s) else s

