    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Step 2: Reverse each row
    for i in range(n):
        matrix[i].reverse()

def limit_occurrences(lst, n):
    """
    Returns a new list containing each element of lst at most n times without changing the order.

    Parameters:
    lst (list): A list of integers.
    n (int): A non-negative integer specifying the maximum number of occurrences for each element.

    Returns:
    list: A new list with elements restricted to at most n occurrences.
    """
    if n == 0:
        return []

    occurrence_count = {}
    result = []

    for item in lst:
        if item not in occurrence_count:
            occurrence_count[item] = 0

        if occurrence_count[item] < n:
            result.append(item)
            occurrence_count[item] += 1

    return result

def min_operations(word_a: str, word_b: str) -> int:
    """
    Computes the minimum number of operations required to transform word_a into word_b.
    An operation is defined as insertion, deletion, or substitution of a single character.
    """
    n, m = len(word_a), len(word_b)
    # dp[i][j] will hold the minimum distance to convert word_a[0:i] to word_b[0:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize dp for transforming from/to empty string
    for i in range(1, n + 1):
        dp[i][0] = i  # Cost of deletions
    for j in range(1, m + 1):
        dp[0][j] = j  # Cost of insertions

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if word_a[i - 1] == word_b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation needed if characters are the same
            else:
                dp[i][j] = min(dp[i - 1][j] + 1,    # Deletion
                               dp[i][j - 1] + 1,    # Insertion
                               dp[i - 1][j - 1] + 1)  # Substitution

    return dp[n][m]

def longest_valid_parentheses(s):
    """
    Returns the length of the longest valid parentheses substring.
    """
    max_length = 0
    stack = [-1]  # Initialize stack with a base for the next valid substring

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

def is_isomorphic(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False

    map_s_to_t = {}
    map_t_to_s = {}

    for char_s, char_t in zip(s, t):
        if char_s in map_s_to_t:
            if map_s_to_t[char_s] != char_t:
                return False
        else:
            map_s_to_t[char_s] = char_t

        if char_t in map_t_to_s:
            if map_t_to_s[char_t] != char_s:
                return False
        else:
            map_t_to_s[char_t] = char_s

    return True

def max_robbery(values):
    if not values:
        return 0
    if len(values) == 1:
