    An enhanced Gnome Sort function to sort elements in increasing order.
    """
    n = len(arr)
    index = 0

    while index < n:
        if index == 0 or arr[index] >= arr[index - 1]:
            index += 1
        else:
            arr[index], arr[index - 1] = arr[index - 1], arr[index]
            index -= 1

    return arr

def is_match(s: str, p: str) -> bool:
    """
    Returns whether the input string matches the given pattern.
    The pattern supports '.' which matches any single character, 
    and '*' which matches zero or more of the preceding element.
    """
    # Initialize the DP table
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Empty pattern matches empty string
    dp[0][0] = True

    # Handle patterns like a*, a*b*, a*b*c* etc should match empty string
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]

    return dp[m][n]

def group_anagrams(words):
    """
    Groups a list of words into anagrams while maintaining the order of their first occurrence.

    :param words: List of strings where each string is a word.
    :return: List of lists, where each sublist contains words that are anagrams.
    """
    anagrams_dict = {}
    result = []

    for word in words:
        key = ''.join(sorted(word))
        if key not in anagrams_dict:
            anagrams_dict[key] = []
        anagrams_dict[key].append(word)

    for word in words:
        key = ''.join(sorted(word))
        if key in anagrams_dict:
            result.append(anagrams_dict.pop(key))

    return result

def max_sum_strictly_increasing_subarray(nums):
    """
    Returns the maximum sum of any strictly increasing subarray of nums.
    """
    if not nums:
        return 0
    n = len(nums)
    if n == 1:
        return nums[0]

    max_sum = current_sum = nums[0]

    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            current_sum += nums[i]
        else:
            max_sum = max(max_sum, current_sum)
            current_sum = nums[i]

    max_sum = max(max_sum, current_sum)
    return max_sum

def longest_subsequence(nums):
    """
    Returns the length of the longest subsequence such that the difference between
    consecutive elements is either -1, 0, or 1.
    """
    if not nums:
        return 0

    subsequences = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if abs(nums[i] - nums[j]) <= 1:
                subsequences[i] = max(subsequences[i], subsequences[j] + 1)

    return max(subsequences)

