    Takes a string s and returns its run-length encoded form.
    """
    if len(s) == 0:
        return ""

    encoded_str = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            encoded_str.append(f"{current_char}{count}")
            current_char = s[i]
            count = 1

    encoded_str.append(f"{current_char}{count}")  # Append the last counted character

    return ''.join(encoded_str)

def recursive_binary_search(sorted_list: list, target: int, left: int = 0, right: int = None) -> int:
    if right is None:
        right = len(sorted_list) - 1

    if left > right:
        return -1

    middle = (left + right) // 2

    if sorted_list[middle] == target:
        return middle
    elif sorted_list[middle] < target:
        return recursive_binary_search(sorted_list, target, middle + 1, right)
    else:
        return recursive_binary_search(sorted_list, target, left, middle - 1)

def is_sentence_palindrome(s: str) -> bool:
    left, right = 0, len(s) - 1

    while left < right:
        # Move the left pointer to the next alphanumeric character
        while left < right and not s[left].isalnum():
            left += 1

        # Move the right pointer to the previous alphanumeric character
        while left < right and not s[right].isalnum():
            right -= 1

        # Check if the characters are the same (ignore case)
        if s[left].lower() != s[right].lower():
            return False

        left += 1
        right -= 1

    return True

