        if complement in num_to_index:
            return [num_to_index[complement], i]
        num_to_index[num] = i

def search_in_rotated_array(nums, target):
    """
    Searches for target in a rotated sorted array.
    Params:
        nums: List[int] - a list of integers 
        target: int - integer target to be searched
    Returns:
        bool - True if target is found, False otherwise
    """
    if not nums:
        return False

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return True

        # If left part is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # If right part is sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return False

def minOperations(num1, num2):
    operations = 0
    while num1 > 0:
        if num2 == 0:
            return -1
        k = 0
        while (1 << (k+1)) <= num1:
            k += 1
        num1 -= (1 << k)
        num2 -= 1
        operations += 1

    return operations

