def min_bills(bills: List[int], target: int) -> int:
    # Initialize a list to store the minimum number of bills needed for each amount up to target
    dp = [float('inf')] * (target + 1)
    dp[0] = 0  # 0 bills are needed to make up the target amount of 0

    # Process each amount from 1 to target
    for amount in range(1, target + 1):
        for bill in bills:
            if amount - bill >= 0:
                dp[amount] = min(dp[amount], dp[amount - bill] + 1)

    return dp[target] if dp[target] != float('inf') else -1

def length_of_longest_substring_two_distinct(s):
    """
    Returns the length of the longest substring containing at most two distinct characters.
    """
    if len(s) < 3:
        return len(s)

    left = 0
    right = 0
    max_length = 2
    char_map = {}

    while right < len(s):
        char_map[s[right]] = right
        right += 1

        if len(char_map) > 2:
            del_idx = min(char_map.values())
            del char_map[s[del_idx]]
            left = del_idx + 1

        max_length = max(max_length, right - left)

    return max_length

from typing import Dict, List

def find_matching_habitat(animal_habitats: Dict[str, List[str]]) -> Dict[str, List[str]]:
    habitat_animals = {}

    for animal, habitats in animal_habitats.items():
        for habitat in habitats:
            if habitat not in habitat_animals:
                habitat_animals[habitat] = []
            habitat_animals[habitat].append(animal)

    for habitat in habitat_animals:
        habitat_animals[habitat].sort()

    return habitat_animals

from typing import List, Tuple

def can_form_rectangle(points: List[Tuple[int, int]]) -> bool:
    point_set = set(points)

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            (x1, y1), (x2, y2) = points[i], points[j]

            if x1 != x2 and y1 != y2:
                if (x1, y2) in point_set and (x2, y1) in point_set:
                    return True

    return False

def min_operations_to_make_good(nums, k):
    """
    Returns the minimum number of operations needed to make all elements
    of the array nums good numbers (divisible by k).
    """
    operations = 0
    for num in nums:
        if num % k != 0:
            operations += 1
    return operations

import math

def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.

    :param n: int, the number to check if it is a prime
    :return: bool, True if n is prime, False otherwise
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def mars_house_robber(houses):
    if not houses:
        return 0
    elif len(houses) == 1:
        return houses[0]

    n = len(houses)
    dp = [0] * n
    dp[0] = houses[0]
    dp[1] = max(houses[0], houses[1])

    for i in range(2, n):
        dp[i] = max(dp[i - 1], dp[i - 2] + houses[i])

    return dp[-1]

from typing import List, Tuple

def max_profit_days(prices: List[float]) -> Tuple[int, int]:
    if not prices or len(prices) < 2:
        return -1, -1

    min_price_index = 0
    max_profit = 0
    buy_day = -1
    sell_day = -1

    for current_day in range(1, len(prices)):
        if prices[current_day] - prices[min_price_index] > max_profit:
            max_profit = prices[current_day] - prices[min_price_index]
            buy_day = min_price_index
            sell_day = current_day

        if prices[current_day] < prices[min_price_index]:
            min_price_index = current_day

    if buy_day == -1 or sell_day == -1:
        return -1, -1
    else:
        return buy_day, sell_day

def min_insertions_to_make_palindrome(s):
    """
    Returns the minimum number of insertions needed to make the string s a palindrome.
    """
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for gap in range(1, n):
        for left in range(n - gap):
            right = left + gap
            if s[left] == s[right]:
                dp[left][right] = dp[left + 1][right - 1]
            else:
                dp[left][right] = min(dp[left][right - 1], dp[left + 1][right]) + 1

    return dp[0][n - 1]

def search_insert(array, val):
    """
    Returns the index at which val should be inserted to keep the array sorted.
    Assumes array is sorted in ascending order.
    """
    low, high = 0, len(array)

    while low < high:
        mid = (low + high) // 2
        if array[mid] < val:
            low = mid + 1
        else:
            high = mid

    return low

def longest_consecutive_sequence(days):
    if not days:
        return 0

    days_set = set(days)
    longest_streak = 0

    for day in days_set:
        if day - 1 not in days_set:
            current_day = day
            current_streak = 1

            while current_day + 1 in days_set:
                current_day += 1
                current_streak += 1

            longest_streak = max(longest_streak, current_streak)

    return longest_streak

def is_balanced(s):
    """
    Returns True if the string s has balanced parentheses, brackets, and braces, otherwise False.
    """
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()

    return not stack

def findSmallestMissingPositive(nums):
    n = len(nums)

    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

def capitalize_sentences(document: str) -> str:
    """
    Capitalizes the first letter of each sentence in a given document.
    A sentence is considered to end with ., ?, or !
    """
    if not document:
        return document

    # Convert the document string to a list to mutate characters efficiently
    result = list(document)
    capitalize_next = True

    for i in range(len(result)):
        if capitalize_next and result[i].isalpha():
            result[i] = result[i].upper()
            capitalize_next = False
        if result[i] in '.!?':
            capitalize_next = True

    return "".join(result)

def summarize_ranges(numbers: list[int]) -> list[str]:
    if not numbers:
        return []

    summarized = []
    start = numbers[0]
    end = numbers[0]

    for i in range(1, len(numbers)):
        if numbers[i] == end + 1:
            end = numbers[i]
        else:
            if start == end:
                summarized.append(f"{start}")
            else:
                summarized.append(f"{start}-{end}")
            start = numbers[i]
            end = numbers[i]

    if start == end:
        summarized.append(f"{start}")
    else:
        summarized.append(f"{start}-{end}")

    return summarized

def maxProfit(k, prices):
    if not prices or k == 0:
        return 0

    n = len(prices)

    # If k >= n // 2, then we can complete as many transactions as we want.
    if k >= n // 2:
        return sum(max(prices[i + 1] - prices[i], 0) for i in range(n - 1))

    # dp[i][j] represents the maximum profit up to day i with at most j transactions.
    dp = [[0] * (k + 1) for _ in range(n)]

    for j in range(1, k + 1):
        max_diff = -prices[0]
        for i in range(1, n):
            dp[i][j] = max(dp[i - 1][j], prices[i] + max_diff)
            max_diff = max(max_diff, dp[i][j - 1] - prices[i])

    return dp[-1][-1]

def is_match(s, p):
    """
    Returns true if the string `s` matches the pattern `p` where `p` may contain
    wildcard character `*` that can match any sequence of characters including the empty sequence.
    """
    m, n = len(s), len(p)
    # Create a 2D DP array to hold the match status
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True  # Empty pattern matches empty string

    # Initialize for patterns starting with '*'
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]

    # Fill the DP array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j - 1] and s[i - 1] == p[j - 1]

    return dp[m][n]

def add_digits(num):
    """
    Given a non-negative integer num, repeatedly add all its digits until the result has only one digit.
    """
    if num == 0:
        return 0
    else:
        return 1 + (num - 1) % 9

from typing import List

def rotate(mat: List[List[int]]) -> None:
    """
    Rotates the matrix by 90 degrees clockwise in place.
    """
    n = len(mat)

    # Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            mat[i][j], mat[j][i] = mat[j][i], mat[i][j]

    # Reverse each row
    for i in range(n):
        mat[i].reverse()

def sum_and_group_transactions(transactions: list[int]) -> list[int]:
    if not transactions:
        return []

    grouped_transactions = []
    current_sum = transactions[0]

    for i in range(1, len(transactions)):
        if (transactions[i] >= 0 and current_sum >= 0) or (transactions[i] < 0 and current_sum < 0):
            current_sum += transactions[i]
        else:
            grouped_transactions.append(current_sum)
            current_sum = transactions[i]

    grouped_transactions.append(current_sum)
    return grouped_transactions

def three_sum(nums):
    """
    Returns all unique triplets in the list which give the sum of zero.
    The triplets are returned in lexicographical order.
    """
    nums.sort()
    result = []
    n = len(nums)

    for i in range(n-2):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        l, r = i+1, n-1
        while l < r:
            total = nums[i] + nums[l] + nums[r]
            if total == 0:
                result.append([nums[i], nums[l], nums[r]])
                while l < r and nums[l] == nums[l+1]:
                    l += 1
                while l < r and nums[r] == nums[r-1]:
                    r -= 1
                l += 1
                r -= 1
            elif total < 0:
                l += 1
            else:
                r -= 1

    # Sort the result list lexicographically
    result.sort()
    return result

from typing import List

def max_contiguous_subsequence_sum(arr: List[int]) -> int:
    if not arr:
        return 0

    max_sum = float('-inf')
    current_sum = 0

    for num in arr:
        current_sum = max(num, current_sum + num)
        max_sum = max(max_sum, current_sum)

    return max_sum

def smallestCommonElement(mat):
    """
    Finds the smallest common element in all rows of a matrix.
    If no such element exists, returns -1.

    :param mat: List[List[int]]
    :return: int
    """
    count = {}
    for row in mat:
        for num in set(row):  # Convert each row to a set to avoid duplicate counts within the same row
            if num in count:
                count[num] += 1
            else:
                count[num] = 1

    rows = len(mat)
    for num in sorted(count.keys()):  # Check the numbers in sorted order
        if count[num] == rows:
            return num
    return -1

def cycle_sort(arr):
    """
    Sort the array in place using Cycle Sort algorithm.
    """
    writes = 0

    # Loop through the list to find cycles to rotate
    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find where to place the item
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already at the correct position
        if pos == cycle_start:
            continue

        # Otherwise, put the item there or right after any duplicates
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1
    return arr

def is_valid_expression(expression: str) -> bool:
    # Dictionary to hold the mapping of closing and opening brackets
    bracket_map = {')': '(', ']': '[', '}': '{'}
    # Stack to keep track of opening brackets
    stack = []

    for char in expression:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False

    return stack == []

def is_balanced(s):
    """
    Determine if the brackets in the string s are balanced.

    Args:
    s (str): A string containing round and curly brackets.

    Returns:
    bool: True if the string is balanced, otherwise False.
    """
    stack = []
    bracket_map = {')': '(', '}': '{'}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or stack.pop() != bracket_map[char]:
                return False
        else:
            # If any other character, continue (although the prompt does not specify other characters)
            continue

    return not stack

def busyStudent(startTime, endTime, queryTime):
    """
    Returns the number of work intervals during which the worker is busy at queryTime.
    """
    count = 0
    for start, end in zip(startTime, endTime):
        if start <= queryTime <= end:
            count += 1
    return count

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters in the given string s.
    """
    if not s:
        return 0

    char_map = {}
    left = 0
    max_length = 0

    for right in range(len(s)):
        if s[right] in char_map and char_map[s[right]] >= left:
            left = char_map[s[right]] + 1
        char_map[s[right]] = right
        max_length = max(max_length, right - left + 1)

    return max_length

def count_partitions(n):
    """
    Returns the number of ways to partition the integer n.
    """
    # Create a 2D list to store results of subproblems
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # base case: there's one way to partition 0, that is using 0
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(n + 1):
            if j >= i:
                dp[i][j] = dp[i - 1][j] + dp[i][j - i]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][n]

def can_visit_all_rooms(rooms):
    """
    Given a list of rooms where each room contains a list of keys
    to other rooms, returns True if all rooms can be visited.
    """
    visited = [False] * len(rooms)
    visited[0] = True  # Start with room 0, which is unlocked
    stack = [0]  # Start the stack with the first room

    while stack:
        room = stack.pop()
        for key in rooms[room]:
            if not visited[key]:
                visited[key] = True
                stack.append(key)

    return all(visited)

def cap_frequencies(lst: list, N: int) -> list:
    """
    Returns a list where each element appears at most N times.
    """
    if N == 0:
        return []

    element_count = {}
    result = []

    for item in lst:
        if item not in element_count:
            element_count[item] = 0

        if element_count[item] < N:
            result.append(item)
            element_count[item] += 1

    return result

def remove_consecutive_duplicates(s):
    """
    Removes the minimum number of characters from a string to ensure no two consecutive characters are the same.

    Parameters:
    s (str): the input string consisting of lowercase English letters.

    Returns:
    str: the resulting string after removals.
    """
    if not s:
        return s

    result = []

    for char in s:
        if not result or char != result[-1]:
            result.append(char)

    return ''.join(result)

def binary_search_insert_position(nums, target):
    """
    Searches for the target in the sorted list nums.
    Returns the index of the target if found.
    If the target is not found, returns the index where it should be inserted to maintain the sorted order.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return left

def create_histogram(input_list):
    """
    Given an unsorted list of elements, return a histogram as a dictionary where
    the keys are the elements and the values are the frequency counts of those elements.
    """
    histogram = {}
    for element in input_list:
        if element in histogram:
            histogram[element] += 1
        else:
            histogram[element] = 1
    return histogram

def is_perfect_square(x):
    """
    Returns True if x is a perfect square, otherwise False.
    Handles edge cases for zero and negative numbers.
    """
    if x < 0:
        return False
    if x == 0:
        return True

    left, right = 1, x
    while left <= right:
        mid = (left + right) // 2
        if mid * mid == x:
            return True
        elif mid * mid < x:
            left = mid + 1
        else:
            right = mid - 1
    return False

def min_absolute_difference_indices(arr, x, y):
    x_indices = [i for i, val in enumerate(arr) if val == x]
    y_indices = [i for i, val in enumerate(arr) if val == y]

    if not x_indices or not y_indices:
        return -1

    min_diff = float('inf')
    for ix in x_indices:
        for iy in y_indices:
            min_diff = min(min_diff, abs(ix - iy))

    return min_diff

def advanced_reverse(s: str) -> str:
    """
    Returns the reversed version of the input string `s`.
    """
    result = []
    for char in s:
        result.insert(0, char)
    return ''.join(result)

def binary_search(collection: list, target: int) -> int:
    """
    Returns the index of target in the sorted list collection
    or -1 if the target is not found.
    """
    left, right = 0, len(collection) - 1

    while left <= right:
        mid = (left + right) // 2
        if collection[mid] == target:
            return mid
        elif collection[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def longest_substring_with_replacements(s, c, x):
    """
    Returns the length of the longest substring of `s` where at most `x` characters are replaced by `c`.
    """
    max_length = 0
    window_start = 0
    replacements = 0

    for window_end in range(len(s)):
        if s[window_end] != c:
            replacements += 1

        while replacements > x:
            if s[window_start] != c:
                replacements -= 1
            window_start += 1

        max_length = max(max_length, window_end - window_start + 1)

    return max_length

def find_unique_pairs(arr, target):
    """
    Returns a list of unique pairs of elements in the sorted array `arr` 
    such that their sum is equal to `target`.
    """
    pairs = []
    left, right = 0, len(arr) - 1

    while left < right:
        current_sum = arr[left] + arr[right]

        if current_sum == target:
            pairs.append((arr[left], arr[right]))
            left += 1
            right -= 1

            # Skip duplicates
            while left < right and arr[left] == arr[left - 1]:
                left += 1
            while left < right and arr[right] == arr[right + 1]:
                right -= 1

        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return pairs

def factorial_recursive(n: int) -> int:
    """
    Return the factorial of a non-negative integer n using recursion.

    :param n: Non-negative integer
    :return: Factorial of the input integer
    """
    if n == 0:
        return 1
    return n * factorial_recursive(n - 1)

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring with all unique characters.
    """
    char_index_map = {}
    longest = 0
    start = 0

    for index, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = index
        longest = max(longest, index - start + 1)

    return longest

def len_longest_fib_subseq(nums):
    if len(nums) < 3:
        return 0

    index = {x: i for i, x in enumerate(nums)}
    longest = {}
    max_len = 0

    for k in range(len(nums)):
        for j in range(k):
            i = index.get(nums[k] - nums[j], None)
            if i is not None and i < j:
                seq_len = longest.get((i, j), 2) + 1
                longest[j, k] = seq_len
                max_len = max(max_len, seq_len)

    return max_len if max_len >= 3 else 0

def find_duplicates(data):
    """
    Takes a list of integers and returns a set of integers that are duplicated in the list.
    If there are no duplicates, returns an empty set.
    """
    seen = set()
    duplicates = set()
    for num in data:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)
    return duplicates

def move_zeros(array: list) -> list:
    """
    Moves all zeros in the list to the end while preserving the order of non-zero elements.
    """
    result = []
    zeros_count = 0

    for element in array:
        if element == 0 and type(element) is int:
            zeros_count += 1
        else:
            result.append(element)

    result.extend([0] * zeros_count)
    return result

def check_parentheses_validity(expression: str) -> bool:
    """
    Returns True if the parentheses in the input string are valid, otherwise False.
    """
    # Stack to keep track of opening brackets
    stack = []

    # Matching pairs dictionary
    matching_pairs = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in matching_pairs.values():
            # It's an opening bracket, push to stack
            stack.append(char)
        elif char in matching_pairs.keys():
            # It's a closing bracket, check for matching with top of stack
            if stack and stack[-1] == matching_pairs[char]:
                stack.pop()
            else:
                return False
    # Stack should be empty if all brackets matched properly
    return len(stack) == 0

def length_of_longest_substring_two_distinct(s: str) -> int:
    """
    Returns the length of the longest substring that contains at most two distinct characters.
    """
    if len(s) == 0:
        return 0

    if len(s) < 3:
        return len(s)

    # Sliding window approach
    left = 0
    right = 0
    max_length = 2

    char_map = {}

    while right < len(s):
        if len(char_map) < 3:
            char_map[s[right]] = right
            right += 1

        if len(char_map) == 3:
            del_idx = min(char_map.values())
            del char_map[s[del_idx]]
            left = del_idx + 1

        max_length = max(max_length, right - left)

    return max_length

def min_intervals_to_cover_peaks(prices):
    """
    Returns the minimum number of non-overlapping intervals needed to cover all local peaks in the prices list.
    A local peak is prices[i] such that prices[i-1] < prices[i] > prices[i+1].
    """
    if not prices or len(prices) < 3:
        return 0

    peaks = []
    n = len(prices)

    # Identify all the peaks
    for i in range(1, n - 1):
        if prices[i - 1] < prices[i] > prices[i + 1]:
            peaks.append(i)

    if not peaks:
        return 0

    intervals = 1
    current_end = peaks[0] + 1

    # Traverse through the peaks to find non-overlapping intervals
    for peak in peaks[1:]:
        if peak > current_end:
            intervals += 1
            current_end = peak + 1

    return intervals

from typing import List, Dict

def element_frequency(arr: List[int]) -> Dict[int, int]:
    frequency = {}
    for elem in arr:
        if elem in frequency:
            frequency[elem] += 1
        else:
            frequency[elem] = 1
    return frequency

def collatz_sequence_length(n: int) -> int:
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

from typing import List

def cycle_sort(arr: List[int]) -> List[int]:
    """
    Sorts an array using Cycle Sort to minimize the number of write operations.
    """
    n = len(arr)

    # Traverse the array and place each element to its correct position
    for start in range(n - 1):
        item = arr[start]

        # Find the position where we put the element
        pos = start
        for i in range(start + 1, n):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == start:
            continue

        # Otherwise place the item where it needs to be
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]

        # Rotate the rest of the cycle
        while pos != start:
            pos = start
            for i in range(start + 1, n):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]

    return arr

def next_bigger(num):
    digits = list(str(num))
    n = len(digits)

    # Start from the end of the number and find the first digit that is smaller than the digit next to it
    for i in range(n-2, -1, -1):
        if digits[i] < digits[i+1]:
            break
    else:
        # If no such digit is found, the number is the highest permutation
        return -1

    # Find the smallest digit on the right side of the found digit which is larger than the found digit
    for j in range(n-1, i, -1):
        if digits[j] > digits[i]:
            break

    # Swap the found digit and j
    digits[i], digits[j] = digits[j], digits[i]

    # Reverse the digits after the position i
    digits = digits[:i+1] + digits[i+1:][::-1]

    return int("".join(digits))

def is_permutation(str1: str, str2: str) -> bool:
    """
    Determine if two strings are permutations of each other.
    """
    if len(str1) != len(str2):
        return False

    count1 = {}
    count2 = {}

    for ch in str1:
        if ch in count1:
            count1[ch] += 1
        else:
            count1[ch] = 1

    for ch in str2:
        if ch in count2:
            count2[ch] += 1
        else:
            count2[ch] = 1

    return count1 == count2

def evaluate_expression(s):
    """
    Evaluates a mathematical expression with non-negative integers and operators '+' '-' '*'.
    """
    tokens = []
    num = 0
    op = '+'

    for char in s + '+':
        if char.isdigit():
            num = num * 10 + int(char)
        else:
            if op == '+':
                tokens.append(num)
            elif op == '-':
                tokens.append(-num)
            elif op == '*':
                tokens[-1] = tokens[-1] * num

            op = char
            num = 0

    return sum(tokens)

def validate_html_nesting(input_string: str) -> bool:
    import re

    tag_pattern = re.compile(r'<(/?[^>]+)>')
    stack = []

    for match in tag_pattern.finditer(input_string):
        tag = match.group(1)
        if not tag.startswith('/'):
            # Opening tag
            stack.append(tag.lower())
        else:
            # Closing tag
            if not stack:
                return False
            if stack.pop() != tag[1:].lower():
                return False
    return not stack

def edit_distance(word_a: str, word_b: str) -> int:
    m = len(word_a)
    n = len(word_b)

    # Create a table to store results of sub-problems
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp array
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j    # If word_a is empty, insert all chars of word_b
            elif j == 0:
                dp[i][j] = i    # If word_b is empty, remove all chars of word_a
            elif word_a[i-1] == word_b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j],       # Remove
                                   dp[i][j-1],       # Insert
                                   dp[i-1][j-1])     # Replace

    return dp[m][n]

from typing import List

def find_diagonal_order(mat: List[List[int]]) -> List[int]:
    if not mat or not mat[0]:
        return []

    rows, cols = len(mat), len(mat[0])
    result = []
    intermediate = []

    for diag in range(rows + cols - 1):
        row = 0 if diag < cols else diag - cols + 1
        col = diag if diag < cols else cols - 1

        while row < rows and col > -1:
            intermediate.append(mat[row][col])
            row += 1
            col -= 1

        if diag % 2 == 0:
            result.extend(intermediate[::-1])
        else:
            result.extend(intermediate)

        intermediate = []

    return result

def is_sorted(stack: list) -> bool:
    """
    Function to check if the stack is sorted in ascending order from the bottom of the stack to the top.
    """
    if not stack:
        return True  # An empty stack is considered sorted

    for i in range(1, len(stack)):
        if stack[i] < stack[i-1]:
            return False

    return True

def multiply_strings(num1, num2):
    """
    Multiplies two non-negative integers represented as strings and 
    returns the product as a string.
    """
    if num1 == "0" or num2 == "0":
        return "0"

    m, n = len(num1), len(num2)
    result = [0] * (m + n)

    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            product = int(num1[i]) * int(num2[j])
            p1, p2 = i + j, i + j + 1
            sum = product + result[p2]
            result[p2] = sum % 10
            result[p1] += sum // 10

    while result[0] == 0:
        result.pop(0)

    return ''.join(map(str, result))

def longest_arithmetic_subarray(nums):
    """
    Returns the length of the longest arithmetic subarray.
    """
    if len(nums) < 2:
        return len(nums)

    max_length = 0
    current_length = 1
    last_diff = None

    for i in range(1, len(nums)):
        current_diff = nums[i] - nums[i - 1]
        if current_diff == last_diff:
            current_length += 1
        else:
            last_diff = current_diff
            current_length = 2

        max_length = max(max_length, current_length)

    return max_length

def isMatch(s: str, p: str) -> bool:
    """
    Returns True if the input string `s` matches the pattern `p`.
    The pattern `p` can include '.' which matches any single character
    and '*' which matches zero or more of the preceding element.
    """
    # Use dynamic programming to solve the problem
    m, n = len(s), len(p)

    # dp[i][j] means whether s[0:i] matches p[0:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Both s and p are empty
    dp[0][0] = True

    # Handle patterns with *
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2] # Matches zero preceding element (e.g. x*)

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]

    return dp[m][n]

def can_transform(stacks, targetStacks):
    """
    Returns true if it's possible to transform the 'stacks' array into the 'targetStacks' array using the allowed operations.
    """
    return sum(stacks) == sum(targetStacks)

def summarize_ranges(array):
    """
    Processes a sorted list of integers and returns a summary of consecutive ranges.

    Parameters:
        array (List[int]): A list of sorted integers with no duplicates.

    Returns:
        List[str]: A list of strings representing ranges of consecutive integers.
    """
    if not array:
        return []

    result = []
    start = array[0]
    end = array[0]

    for num in array[1:]:
        if num == end + 1:
            end = num
        else:
            if start == end:
                result.append(f"{start}")
            else:
                result.append(f"{start}-{end}")
            start = num
            end = num

    if start == end:
        result.append(f"{start}")
    else:
        result.append(f"{start}-{end}")

    return result

def count_subarrays_with_sum(arr, t):
    """
    Returns the number of subarrays that sum up to t within the given list arr.
    """
    count = 0
    current_sum = 0
    sum_dict = {0: 1}   # Initialize with 0 sum having one count for edge cases.

    for num in arr:
        current_sum += num
        if current_sum - t in sum_dict:
            count += sum_dict[current_sum - t]
        if current_sum in sum_dict:
            sum_dict[current_sum] += 1
        else:
            sum_dict[current_sum] = 1

    return count

def isWellFormed(s: str) -> bool:
    """
    Determines if the input string is well-formed with respect to parentheses.

    Args:
    s (str): Input string containing only '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: True if the string is well-formed, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            return False
    return stack == []

def gnome_sort(arr: list[int]) -> list[int]:
    index = 0
    while index < len(arr):
        if index == 0 or arr[index] >= arr[index - 1]:
            index += 1
        else:
            arr[index], arr[index - 1] = arr[index - 1], arr[index]
            index -= 1
    return arr

import math

def find_perfect_squares(numbers):
    """
    Returns a list of unique perfect squares from the input list.
    """
    perfect_squares = set()
    for num in numbers:
        if num >= 0:  # only non-negative numbers can be perfect squares
            root = int(math.isqrt(num))
            if root * root == num:
                perfect_squares.add(num)
    return sorted(perfect_squares)

def euler_totient(n: int) -> int:
    """
    Computes the value of Euler's Totient Function for a given integer n.
    """
    if n == 1:
        return 1

    result = n
    p = 2
    while p * p <= n:
        # Check if p is a divisor of n
        if n % p == 0:
            # If yes, then it means p is a prime factor of n
            while n % p == 0:
                n = n // p
            result -= result // p
        p += 1

    # If n has a prime factor greater than sqrt(n)
    if n > 1:
        result -= result // n

    return result

def maximal_square(matrix: list[list[int]]) -> int:
    if not matrix or not matrix[0]:
        return 0

    r = len(matrix)
    c = len(matrix[0])
    max_side = 0

    # Create a DP array to store the side length of the largest square ending at (i, j)
    dp = [[0] * c for _ in range(r)]

    for i in range(r):
        for j in range(c):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

                max_side = max(max_side, dp[i][j])

    return max_side

def longest_common_subsequence(s1: str, s2: str) -> int:
    """
    Returns the length of the longest common subsequence between two strings s1 and s2.
    """
    n = len(s1)
    m = len(s2)

    # Create a 2D array to store lengths of longest common subsequence.
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][m]

from collections import deque
from typing import List, Optional

def level_order_traversal(nodes: List[Optional[int]]) -> List[List[int]]:
    if not nodes or nodes[0] is None:
        return []

    result = []
    queue = deque([(0, nodes[0])])

    while queue:
        level_size = len(queue)
        current_level = []

        for _ in range(level_size):
            index, node = queue.popleft()
            if node is None:
                continue
            current_level.append(node)

            left_index = 2 * index + 1
            right_index = 2 * index + 2

            if left_index < len(nodes):
                queue.append((left_index, nodes[left_index]))
            if right_index < len(nodes):
                queue.append((right_index, nodes[right_index]))

        if current_level:
            result.append(current_level)

    return result

def next_greater_element(nums1, nums2):
    """
    Finds the next greater element for each element in nums2 within nums1.
    """
    result = []
    num_dict = {val: idx for idx, val in enumerate(nums1)}

    for num in nums2:
        found = False
        for i in range(num_dict[num] + 1, len(nums1)):
            if nums1[i] > num:
                result.append(nums1[i])
                found = True
                break
        if not found:
            result.append(-1)

    return result

from typing import List, Dict, Union

def calculate_inventory_value(items: List[Dict[str, Union[float, int]]]) -> float:
    total_value = 0.0
    for item in items:
        quantity = item.get('quantity', -1)
        price_per_unit = item.get('price_per_unit', -1.0)

        if isinstance(quantity, int) and quantity >= 0 and isinstance(price_per_unit, (int, float)) and price_per_unit >= 0:
            total_value += quantity * price_per_unit

    return total_value

def delete_reoccurring_characters(s: str) -> str:
    """
    Removes all duplicate characters from the string while preserving the order of their first appearance.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

def text_editor(operations):
    """
    Processes a series of text editor operations and returns the results of "PRINTKth" operations.

    Args:
    operations: List of strings, each string represents an operation ("INSERT c", "DELETE", "PRINTKth k").

    Returns:
    List of results from "PRINTKth" operations.
    """
    document = []
    results = []

    for operation in operations:
        if operation.startswith("INSERT"):
            _, char = operation.split()
            document.append(char)
        elif operation == "DELETE":
            if document:
                document.pop()
        elif operation.startswith("PRINTKth"):
            _, k = operation.split()
            k = int(k)
            if k > len(document):
                results.append("")
            else:
                results.append(document[k-1])

    return results

def remove_adjacent_pairs(s: str) -> str:
    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

def evaluate_expression(expression: str) -> int:
    tokens = expression.split()
    result = int(tokens[0])
    i = 1
    while i < len(tokens):
        operator = tokens[i]
        operand = int(tokens[i+1])

        if operator == '+':
            result += operand
        elif operator == '*':
            result *= operand

        i += 2

    return result

def minStepsToOrigin(x, y):
    """
    Returns the minimum number of steps to reach the origin (0, 0) from the point (x, y).
    """
    # The minimum number of steps required is the sum of the absolute values of the coordinates
    return abs(x) + abs(y)

def run_length_encoding(s: str) -> str:
    """
    Returns the run-length encoded string of input string s.
    """
    if not s:
        return ""

    encoded_str = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            encoded_str.append(current_char + str(count))
            current_char = s[i]
            count = 1

    # Add the last character group
    encoded_str.append(current_char + str(count))

    return ''.join(encoded_str)

def min_removals_to_avoid_adjacent_duplicates(s):
    """
    Returns the minimum number of characters that need to be removed from s 
    so that no two adjacent characters are the same.
    """
    if not s:
        return 0

    count = 0
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
    return count

from typing import List

def generate_pascals_triangle(n: int) -> List[List[int]]:
    if n == 0:
        return []

    triangle = [[1]]

    for row_num in range(1, n):
        row = [1]
        last_row = triangle[row_num - 1]
        for j in range(1, row_num):
            row.append(last_row[j - 1] + last_row[j])
        row.append(1)
        triangle.append(row)

    return triangle

from typing import List

def max_path_value(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])

    # Initialize dp array with same dimensions as grid
    dp = [[0] * cols for _ in range(rows)]

    # Start from the top-left corner
    dp[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, cols):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the first column
    for i in range(1, rows):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp array
    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[rows-1][cols-1]

import math

def find_roots(a: float, b: float, c: float) -> dict[str, float]:
    """
    Given the coefficients of a quadratic polynomial, find its real roots.

    Args:
    a (float): Coefficient of x^2
    b (float): Coefficient of x
    c (float): Constant term

    Returns:
    dict: A dictionary containing the real roots with keys 'root1' and 'root2' if there are two distinct real roots,
          'root' if there is one real root, or an empty dictionary if there are no real roots.

    Raises:
    ValueError: If the coefficient 'a' is zero.
    """
    if a == 0:
        raise ValueError("Coefficient 'a' cannot be zero")

    discriminant = b**2 - 4*a*c

    if discriminant > 0:
        root1 = (-b - math.sqrt(discriminant)) / (2 * a)
        root2 = (-b + math.sqrt(discriminant)) / (2 * a)
        return {'root1': min(root1, root2), 'root2': max(root1, root2)}
    elif discriminant == 0:
        root = -b / (2 * a)
        return {'root': root}
    else:
        return {}

def repeatedSubstringPattern(s: str) -> bool:
    """
    Determines if a given string can be constructed by repeating a substring.
    """
    n = len(s)

    # Check all possible lengths of the repeating substring
    for i in range(1, n // 2 + 1):
        if n % i == 0:
            # If the length is divisible by i, check if s can be constructed
            # by repeating the substring of length i
            if s[:i] * (n // i) == s:
                return True
    return False

def count_distinct_elements(nums, k):
    """
    Returns a list of counts of distinct elements in every subarray of length k.
    If the length of nums is less than k, returns an empty list.
    """
    if len(nums) < k:
        return []

    result = []
    current_window = {}
    distinct_count = 0

    for i in range(len(nums)):
        if nums[i] in current_window:
            current_window[nums[i]] += 1
        else:
            current_window[nums[i]] = 1
            distinct_count += 1

        if i >= k - 1:
            result.append(distinct_count)
            left_elem = nums[i - k + 1]
            if current_window[left_elem] == 1:
                del current_window[left_elem]
                distinct_count -= 1
            else:
                current_window[left_elem] -= 1

    return result

def remove_duplicates(s):
    """
    Removes all duplicate letters from the string s keeping only the last occurrence of each letter.
    The order of the resulting string should preserve the order of their last occurrences in s.

    :param s: str - A string of lowercase English letters.
    :return: str - A new string where all the duplicate letters are removed.
    """

    last_occurrence = {char: idx for idx, char in enumerate(s)}
    result = []
    seen = set()

    for idx, char in enumerate(s):
        if char not in seen and idx == last_occurrence[char]:
            result.append(char)
            seen.add(char)

    return ''.join(result)

def decode_string(encoded: str) -> str:
    stack = []
    curr_num = 0
    curr_str = ''

    for c in encoded:
        if c.isdigit():
            curr_num = curr_num * 10 + int(c)
        elif c == '[':
            stack.append((curr_str, curr_num))
            curr_str = ''
            curr_num = 0
        elif c == ']':
            last_str, num = stack.pop()
            curr_str = last_str + curr_str * num
        else:
            curr_str += c

    return curr_str

def num_ways_to_paint_fence(n: int, k: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k

    same = k
    diff = k * (k - 1)

    for i in range(3, n + 1):
        new_same = diff
        new_diff = (same + diff) * (k - 1)

        same = new_same
        diff = new_diff

    return same + diff

def is_balanced(s: str) -> bool:
    """
    Determines if the bracket sequence is balanced.

    :param s: A string containing only '[' and ']' characters.
    :return: True if the sequence is balanced, otherwise False.
    """
    balance = 0

    for char in s:
        if char == '[':
            balance += 1
        elif char == ']':
            balance -= 1

        if balance < 0:
            return False

    return balance == 0

import os

def rank_files_by_keyword(directory_path: str, keyword: str) -> list[str]:
    keyword = keyword.lower()
    file_keyword_frequency = []

    for filename in os.listdir(directory_path):
        if filename.endswith('.txt'):
            try:
                with open(os.path.join(directory_path, filename), 'r', encoding='utf-8') as file:
                    content = file.read().lower()
                    keyword_count = content.count(keyword)
                    if keyword_count > 0:
                        file_keyword_frequency.append((filename, keyword_count))
            except Exception as e:
                continue

    file_keyword_frequency.sort(key=lambda x: (-x[1], x[0]))

    return [file[0] for file in file_keyword_frequency]

def find_transaction_pairs(transactions, target):
    """
    Finds pairs of transactions whose sums equal the target value.
    """
    seen = {}
    for i, value in enumerate(transactions):
        diff = target - value
        if diff in seen:
            return [(seen[diff], i)]
        seen[value] = i
    return []

def unique_paths_with_obstacles(grid):
    """
    Returns the number of unique paths from top-left to bottom-right in a grid with obstacles.
    :param grid: List[List[int]] The grid with obstacles (0 - empty cell, 1 - obstacle)
    :return: int The number of unique paths
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize the dp array
    dp = [[0] * n for _ in range(m)]

    # Starting point
    dp[0][0] = 1

    # Fill the dp array
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

def search_matrix(matrix, target):
    """
    Searches for the target in a m x n matrix with sorted rows and columns.
    Returns the position [i, j] of the target if found, otherwise returns [-1, -1].
    """
    if not matrix:
        return [-1, -1]

    rows, cols = len(matrix), len(matrix[0])

    # Start from the top-right corner of the matrix
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return [row, col]
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1

