def longest_subarray_with_two_distinct(nums):
    """
    Finds the length of the longest subarray that contains at most two distinct values.
    """
    if not nums:
        return 0

    window_start = 0
    max_length = 0
    freq_map = {}

    for window_end in range(len(nums)):
        right_char = nums[window_end]
        if right_char not in freq_map:
            freq_map[right_char] = 0
        freq_map[right_char] += 1

        while len(freq_map) > 2:
            left_char = nums[window_start]
            freq_map[left_char] -= 1
            if freq_map[left_char] == 0:
                del freq_map[left_char]
            window_start += 1

        max_length = max(max_length, window_end - window_start + 1)

    return max_length

def character_distribution(text):
    """
    Returns a dictionary summarizing the character distribution in the given text.
    """
    distribution = {}
    total_characters = len(text)

    # Compute frequency distribution
    for char in text:
        if char in distribution:
            distribution[char] += 1
        else:
            distribution[char] = 1

    # Find the most frequent character
    most_frequent_char = max(distribution, key=distribution.get)

    # Return the summarized character distribution
    result = {
        'total_characters': total_characters,
        'unique_characters': len(distribution),
        'frequency_distribution': distribution,
        'most_frequent_char': most_frequent_char
    }

    return result

