def are_permutations(str1: str, str2: str) -> bool:
    """
    Determines if str1 is a permutation of str2.

    Args:
    str1 (str): The first string.
    str2 (str): The second string.

    Returns:
    bool: True if str1 is a permutation of str2, False otherwise.
    """

    if len(str1) != len(str2):
        return False

    char_count = {}

    for char in str1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in str2:
        if char in char_count:
            char_count[char] -= 1
        else:
            return False

    for count in char_count.values():
        if count != 0:
            return False

    return True

def lengthOfLongestSubstringKDistinct(s, n):
