    """
    if n == 0:
        return 0

    char_map = {}
    left = 0
    max_len = 0

    for right in range(len(s)):
        char_map[s[right]] = char_map.get(s[right], 0) + 1

        while len(char_map) > n:
            char_map[s[left]] -= 1
            if char_map[s[left]] == 0:
                del char_map[s[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

def is_consecutive(stack):
    """
    Verifies if the stack contains a sequence of consecutive integers starting from the bottom.
    """
    if not stack:
        return True

    # Create a copy of the stack to preserve its integrity
    temp_stack = stack[:]

    # Loop through the copied stack and check for consecutive elements
    for i in range(len(temp_stack) - 1):
        if temp_stack[i] + 1 != temp_stack[i + 1]:
            return False

    return True

def find_magic_index(nums):
    """
    Returns the index of the number in the array nums which is equal to its index.
    If multiple such numbers exist, returns the index of the first occurrence.
    If no such number exists, returns -1.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == mid:
            return mid
        elif nums[mid] < mid:
            left = mid + 1
        else:
            right = mid - 1

    return -1

