        return 0

    # Initialize the minimum time array with infinity
    min_time = [float('inf')] * n
    min_time[0] = 0

    for i in range(n):
        for j in range(1, k + 1):
            if i + j < n and heights[i + j] <= heights[i]:
                min_time[i + j] = min(min_time[i + j], min_time[i] + 1)

    return -1 if min_time[-1] == float('inf') else min_time[-1]

