    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 'O':
                if i == 0 or j == 0:
                    dp[i][j] = 1  # edge cases: first row or first column
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side * max_side

