def findMaxConsecutiveOnes(nums):
    """
    Returns the maximum length of a contiguous subarray that contains only `1`s 
    after flipping at most one `0` to `1`.
    """
    max_len, zero_count, left = 0, 0, 0

    for right in range(len(nums)):
        if nums[right] == 0:
            zero_count += 1

        while zero_count > 1:
            if nums[left] == 0:
                zero_count -= 1
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

def search_in_a_sorted_matrix(matrix, key):
    """
    Search for a key in a 2D matrix where each row and each column is sorted in non-decreasing order.

    :param matrix: List of Lists of integers, where each row and each column is sorted in non-decreasing order
    :param key: Integer, the value to search for within the matrix
    :return: Tuple of (row, column) if the key is found or (-1, -1) if the key is not found
    """
    if not matrix or not matrix[0]:
        return (-1, -1)

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == key:
            return (row, col)
        elif matrix[row][col] > key:
            col -= 1
        else:
            row += 1

    return (-1, -1)

def has_path(n, edges, start, end):
    """
    Determine if there exists a path between two nodes using Depth-First Search (DFS) algorithm.

    :param n: An integer representing the number of nodes.
    :param edges: A list of tuples (u, v), where 'u' is the starting node, and 'v' is the ending node of a directed edge.
    :param start: The starting node from which to search (integer).
    :param end: The ending node that we want to reach (integer).
    :return: A boolean value, True if there is a path from `start` to `end`, False otherwise.
    """

    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)

    stack = [start]
    visited = set()

    while stack:
        node = stack.pop()
        if node == end:
            return True
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    stack.append(neighbor)

    return False

