def min_cost_path(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]

    # Initialize the first cell
    dp[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, cols):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the first column
    for i in range(1, rows):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp table
    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[rows-1][cols-1]

def min_jumps(arr):
    """
    Given an array of integers where each element represents the maximum length of rope you can cut from that position,
    returns the minimum number of jumps required to reach the last index. Returns -1 if it is not possible.
    """
    if len(arr) <= 1:
        return 0
    if arr[0] == 0:
        return -1

    max_reach = arr[0]
    step = arr[0]
    jump = 1

    for i in range(1, len(arr)):
        if i == len(arr) - 1:
            return jump

        max_reach = max(max_reach, i + arr[i])
        step -= 1

        if step == 0:
            jump += 1
            if i >= max_reach:
                return -1
            step = max_reach - i

    return -1

def is_valid_expression(expression: str) -> bool:
    """
    Determines if the input string containing just the characters '(', ')', '{', '}', '[' and ']'
    is valid. A string is considered valid if:
    1. Open brackets are closed by the same type of brackets.
    2. Open brackets are closed in the correct order.

    :param expression: String containing the characters '(', ')', '{', '}', '[' and ']'
    :return: Boolean indicating if the input string is valid
    """
    stack = []
    matching_parentheses = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses:
            if not stack or stack.pop() != matching_parentheses[char]:
                return False
    return not stack

def convert_zigzag(s, num_rows):
    if num_rows == 1 or num_rows >= len(s):
        return s

    rows = [''] * num_rows
    current_row = 0
    going_down = False

    for c in s:
        rows[current_row] += c
        if current_row == 0 or current_row == num_rows - 1:
            going_down = not going_down
        current_row += 1 if going_down else -1

    return ''.join(rows)

