def enhanced_caesar_cipher(s: str, k: int) -> str:
    result = []
    k = k % 26  # Effective shift for alphabet characters
    for char in s:
        if 'a' <= char <= 'z':
            new_char = chr((ord(char) - ord('a') + k) % 26 + ord('a'))
            result.append(new_char)
        elif 'A' <= char <= 'Z':
            new_char = chr((ord(char) - ord('A') + k) % 26 + ord('A'))
            result.append(new_char)
        else:
            result.append(char)
    return ''.join(result)

def multiply(multiplicand: list[list[int]], multiplier: list[list[int]]) -> list[list[int]]:
    # Get the dimensions of the matrices
    m = len(multiplicand)
    n = len(multiplicand[0])
    p = len(multiplier[0])

    # Ensure the matrices can be multiplied
    if len(multiplier) != n:
        raise ValueError("Incompatible matrices for multiplication")

    # Initialize the product matrix with zeros
    product = [[0 for _ in range(p)] for _ in range(m)]

    # Perform matrix multiplication
    for i in range(m):
        for j in range(p):
            for k in range(n):
                product[i][j] += multiplicand[i][k] * multiplier[k][j]

    return product

def substring_frequency(text: str, length: int) -> dict[str, int]:
    """
    Finds all unique substrings of a given length within a string and counts their frequencies.

    Parameters:
    - text (str): The input string to analyze.
    - length (int): The length of substrings to find.

    Returns:
    - dict: A dictionary where keys are substrings and values are their frequencies.
    """
    if length <= 0 or len(text) < length:
        return {}

    freq_dict = {}
    for i in range(len(text) - length + 1):
        substring = text[i:i + length]
        if substring in freq_dict:
            freq_dict[substring] += 1
        else:
            freq_dict[substring] = 1

    return freq_dict

