            count += 1
        else:
            compressed.append(s[i-1] + str(count))
            count = 1

    # Add the last sequence
    compressed.append(s[-1] + str(count))

    return ''.join(compressed)

def can_become_goal(s, goal):
    """
    Returns True if s can become goal after some number of shifts, False otherwise.
    """
    if len(s) != len(goal):
        return False
    return goal in (s + s)

def max_length_subarray_with_one_zero(bins):
    """
    Returns the maximum length of a contiguous subarray that contains at most one zero.
    """
    max_length = 0
    left = 0
    zero_count = 0

    for right in range(len(bins)):
        if bins[right] == 0:
            zero_count += 1

        while zero_count > 1:
            if bins[left] == 0:
                zero_count -= 1
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

def subarray_sum(nums, k):
    """
    Returns the number of contiguous subarrays that sum to k.
    """
    count = 0
    current_sum = 0
    sum_map = {0: 1}

    for num in nums:
        current_sum += num
        if (current_sum - k) in sum_map:
            count += sum_map[current_sum - k]
        if current_sum in sum_map:
            sum_map[current_sum] += 1
        else:
            sum_map[current_sum] = 1

    return count

