def evaluate_expression(s):
    """
    Evaluate a mathematical expression in string format and return the result as an integer.
    """
    tokens = s.split()
    stack = []
    current = 0
    operator = '+'

    for token in tokens + ['+']:
        if token.isdigit():
            num = int(token)
            if operator == '+':
                stack.append(num)
            elif operator == '-':
                stack.append(-num)
            elif operator == '*':
                stack.append(stack.pop() * num)
            elif operator == '/':
                stack.append(int(stack.pop() / num))
        else:
            operator = token

    return sum(stack)

import bisect

def longest_monotonic_increasing_subsequence(prices: list[int]) -> int:
    """
    Returns the length of the longest monotonically increasing subsequence
    in the list of integers.
    """
    if not prices:
        return 0

    sub = []
    for price in prices:
        pos = bisect.bisect_left(sub, price)
        if pos == len(sub):
            sub.append(price)
        else:
            sub[pos] = price

    return len(sub)

def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the string s.
    If there is no non-repeating character, returns an empty string " ".
    """
    frequency = {}

    # Calculate frequency of each character
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    # Find the first non-repeating character
    for char in s:
        if frequency[char] == 1:
            return char

    return " "

def bellman_ford_with_path(graph, source, destination):
    """
    Computes the shortest path travel times from the source city to all cities
    using the Bellman-Ford algorithm and reconstructs the path to the given
    destination city.

    Parameters:
    graph (dict): The graph with cities as nodes and travel times as edges.
    source (str): The starting city.
    destination (str): The destination city.

    Returns:
    tuple: (bool indicating success, list of nodes in the shortest path)
    """
    # Step 1: Initialize distances and predecessors
    dist = {node: float('inf') for node in graph}
    pred = {node: None for node in graph}
    dist[source] = 0

    # Step 2: Relax edges repeatedly |V| - 1 times
    for _ in range(len(graph) - 1):
        for u in graph:
            for v in graph[u]:
                if dist[u] + graph[u][v] < dist[v]:
                    dist[v] = dist[u] + graph[u][v]
                    pred[v] = u

    # Step 3: Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if dist[u] + graph[u][v] < dist[v]:
                return (False, [])

    # Step 4: Reconstruct path from source to destination
    path = []
    current = destination
    while current is not None:
        path.insert(0, current)
        if current == source:
            break
        current = pred[current]

    if dist[destination] == float('inf'):
        return (True, [])

    return (True, path)

def min_words_to_form_target(words, target):
    from collections import deque, defaultdict

    word_set = set(words)
    queue = deque([(target, 0)])
    visited = set()

    while queue:
        current, steps = queue.popleft()

        if current == "":
            return steps

        for word in word_set:
            if current.startswith(word):
                new_target = current[len(word):]
                if new_target not in visited:
                    visited.add(new_target)
                    queue.append((new_target, steps + 1))

    return -1

def spiralOrder(matrix):
    """
    Returns all elements of the matrix in spiral order.
    """
    if not matrix or not matrix[0]:
        return []

    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # Traverse downwards
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        if top <= bottom:
            # Traverse from right to left
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        if left <= right:
            # Traverse upwards
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_index = {}
    max_length = start = 0

    for index, char in enumerate(s):
        if char in char_index and start <= char_index[char]:
            start = char_index[char] + 1
        else:
            max_length = max(max_length, index - start + 1)
        char_index[char] = index

    return max_length

def decode_ways(encoded_message: str) -> int:
    if not encoded_message or encoded_message[0] == '0':
        return 0

    n = len(encoded_message)
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1 if encoded_message[0] != '0' else 0

    for i in range(2, n + 1):
        one_digit = int(encoded_message[i-1:i])
        two_digits = int(encoded_message[i-2:i])

        if 1 <= one_digit <= 9:
            dp[i] += dp[i-1]

        if 10 <= two_digits <= 26:
            dp[i] += dp[i-2]

    return dp[n]

def is_sorted_alternative(stack):
