def next_bigger(num: int) -> int:
    num_str = list(str(num))
    n = len(num_str)

    # Step 1: Identify the rightmost digit which is smaller than its next digit
    for i in range(n-2, -1, -1):
        if num_str[i] < num_str[i+1]:
            break
    else:
        # If no such digit is found, then all digits are in descending order
        return -1

    # Step 2: Find the smallest digit on the right of the above found digit that is larger than the found digit
    for j in range(n-1, i, -1):
        if num_str[j] > num_str[i]:
            break

    # Step 3: Swap the above found two digits
    num_str[i], num_str[j] = num_str[j], num_str[i]

    # Step 4: Sort the digits after the position i
    num_str = num_str[:i+1] + sorted(num_str[i+1:])

    # Convert list back to integer
    return int("".join(num_str))

def maximum_possible_value(nums):
    """
    Returns the maximum possible value of the list by making at most one swap.
    """
    if not nums or len(nums) == 1:
        return nums

    original_nums = nums[:]
    sorted_nums = sorted(nums, reverse=True)

    # Find the first position where nums and sorted_nums differ
    for i in range(len(nums)):
        if nums[i] != sorted_nums[i]:
            break
    else:
        # If nums is already the maximum permutation
        return nums

    # Find the largest value in the list after the first different element
    for j in range(len(nums)-1, -1, -1):
        if nums[j] == sorted_nums[i]:
            nums[i], nums[j] = nums[j], nums[i]
            break

    return nums

def find_kth_missing_positive(arr, k):
    """
    Returns the k-th smallest missing positive integer from the array `arr`.
    """
    missing_count, current = 0, 1
    arr_set = set(arr)

    while missing_count < k:
        if current not in arr_set:
            missing_count += 1
        if missing_count < k:
            current += 1

    return current

def find_first_non_repeating_char(s: str) -> str:
    """
    Identifies the first non-repeating character in a given string.
    If all characters are repeating, returns an underscore ('_').

    Parameters:
    s (str): The string to be processed.

    Returns:
    str: The first non-repeating character or '_' if all characters are repeating.
    """
    char_count = {}

    # First pass: count occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass: find the first character with a count of 1
    for char in s:
        if char_count[char] == 1:
            return char

    return '_'

def max_square_submatrix(matrix):
    """
    Finds the size of the largest square submatrix that contains only `1`s.

    :param matrix: List[List[int]] - a 2D binary matrix
    :return: int - the size (area) of the largest square submatrix consisting entirely of `1`s
    """
    if not matrix or not matrix[0]:
        return 0

    rows = len(matrix)
    cols = len(matrix[0])
    dp = [[0] * cols for _ in range(rows)]
    max_side = 0

    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side * max_side  # Area of the largest square

