def custom_insertion_sort(arr: List[int], threshold: int) -> List[int]:
    if len(arr) > threshold:
        return arr

    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and key < arr[j]:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key

    return arr

def is_one_edit_away(s: str, t: str) -> bool:
    """
    :param s: A string input
    :param t: A string input
    :return: A boolean indicating if s and t are one edit distance apart
    """
    if abs(len(s) - len(t)) > 1:
        return False

    if len(s) > len(t):
        s, t = t, s

    if len(s) == len(t):
        found_difference = False
        for i in range(len(s)):
            if s[i] != t[i]:
                if found_difference:
                    return False
                found_difference = True
        return found_difference
    else:
        i = j = 0
        found_difference = False
        while i < len(s) and j < len(t):
            if s[i] != t[j]:
                if found_difference:
                    return False
                found_difference = True
                j += 1
            else:
                i += 1
                j += 1
        return True

def is_interleave(s1: str, s2: str, s3: str) -> bool:
    """
    Determines if s3 is formed by an interleaving of s1 and s2.
    """
    m, n = len(s1), len(s2)

    if m + n != len(s3):
        return False

    dp = [[False] * (n+1) for _ in range(m+1)]
    dp[0][0] = True

    for i in range(1, m+1):
        dp[i][0] = dp[i-1][0] and s1[i-1] == s3[i-1]

    for j in range(1, n+1):
        dp[0][j] = dp[0][j-1] and s2[j-1] == s3[j-1]

    for i in range(1, m+1):
        for j in range(1, n+1):
            dp[i][j] = (dp[i-1][j] and s1[i-1] == s3[i+j-1]) or (dp[i][j-1] and s2[j-1] == s3[i+j-1])

    return dp[m][n]

def longest_balanced_substring(s):
    """
    Returns the length of the longest balanced substring in s.
    A balanced substring contains an equal number of 'a' and 'b'.
    """
    max_len = 0
    n = len(s)

    # To keep track of count differences
    count_diff = {0: -1}  # Initialize with difference 0 at index -1
    count = 0

    for i in range(n):
        if s[i] == 'a':
            count += 1
        else:
            count -= 1

        if count in count_diff:
            max_len = max(max_len, i - count_diff[count])
        else:
            count_diff[count] = i

    return max_len

from typing import List

def ternary_search(left: int, right: int, key: int, arr: List[int]) -> int:
    """
    Perform ternary search on a sorted array.
    """
    while right >= left:
        third = (right - left) // 3
        mid1 = left + third
        mid2 = right - third

        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2

        if key < arr[mid1]:
            right = mid1 - 1
        elif key > arr[mid2]:
            left = mid2 + 1
        else:
            left = mid1 + 1
            right = mid2 - 1

    return -1

