from typing import List

def cycle_sort(arr: List[int]) -> List[int]:
    """
    Sorts the array in-place using Cycle Sort algorithm and returns the sorted array.
    """

    writes = 0

    # Loop through the array to find cycles to rotate.
    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find where to put the item.
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position, continue.
        if pos == cycle_start:
            continue

        # Otherwise, put the item there or right after any duplicates.
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle.
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1
            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

def shortest_distance(cards):
    """
    Returns the shortest distance between two repeated cards or -1 if no card is repeated.
    """
    card_indices = {}
    min_distance = float('inf')

    for index, card in enumerate(cards):
        if card in card_indices:
            min_distance = min(min_distance, index - card_indices[card])
        card_indices[card] = index

    return -1 if min_distance == float('inf') else min_distance

