def judge_circle(moves):
    """
    Determines if the robot returns to the origin after following the sequence of moves.

    Parameters:
    moves (str): A string representing the sequence of moves ('U', 'D', 'L', 'R').

    Returns:
    bool: True if the robot returns to the origin, False otherwise.
    """
    x, y = 0, 0
