def longest_subsequence(nums, d):
    """
    Returns the length of the longest subsequence such that the difference between
    consecutive elements is exactly `d` in the given integer array `nums`.
    """
    if not nums:
        return 0

    # Dictionary to store the length of subsequence ending with the value of the key
    dp = {}

    max_len = 0

    for num in nums:
        if num - d in dp:
            dp[num] = dp[num - d] + 1
        else:
            dp[num] = 1

        max_len = max(max_len, dp[num])

    return max_len

def product_of_primes(n: int) -> int:
    """
    Calculate the product of all prime numbers up to and including n.
    """
    if n < 2:
        return 1

    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not primes

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for multiple in range(start * start, n + 1, start):
                sieve[multiple] = False

    product = 1
    for num in range(2, n + 1):
        if sieve[num]:
            product *= num

    return product

def calculate_tax(income: float, tax_brackets: list[tuple[float, float]]) -> float:
    total_tax = 0.0
    previous_limit = 0.0

    for i, (limit, rate) in enumerate(tax_brackets):
        if income > limit:
            total_tax += (limit - previous_limit) * rate
            previous_limit = limit
        else:
            total_tax += (income - previous_limit) * rate
            return total_tax

    return total_tax

def dfs_traversal(graph, start):
    stack = [start]
    visited = set()
    traversal_order = []

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            traversal_order.append(node)
            # Add adjacent nodes to stack (in reverse order to maintain correct traversal)
            for neighbor in reversed(graph[node]):
                if neighbor not in visited:
                    stack.append(neighbor)

    return traversal_order

def buddyStrings(s: str, goal: str) -> bool:
    if len(s) != len(goal):
        return False

    if s == goal:
        # Check if there is any character that appears at least twice
        seen = set()
        for char in s:
            if char in seen:
                return True
            seen.add(char)
        return False

    # Find the pairs of characters that are different
    pairs = []
    for a, b in zip(s, goal):
        if a != b:
            pairs.append((a, b))

    # If there are exactly two pairs and they are swappable to make the strings equal
    return len(pairs) == 2 and pairs[0] == pairs[1][::-1]

def is_match(s: str, p: str) -> bool:
    """
    Returns True if input string s matches the pattern p following the rules of
    regular expression matching with '.' and '*'.
    """
    # Create a DP table to store the results
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Base case: empty string matches empty pattern
    dp[0][0] = True

    # Handle patterns like a*, a*b*, a*b*c* etc.
    for j in range(1, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill the DP table
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == s[i - 1] or p[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                # Match empty sequence or match preceding element
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] and (p[j - 2] == s[i - 1] or p[j - 2] == '.'))

    return dp[len(s)][len(p)]

