def decode_string(s: str) -> str:
    stack = []
    current_num = 0
    current_str = ''

    for char in s:
        if char.isdigit():
            current_num = current_num * 10 + int(char)
        elif char == '[':
            stack.append((current_str, current_num))
            current_str = ''
            current_num = 0
        elif char == ']':
            last_str, num = stack.pop()
            current_str = last_str + num * current_str
        else:
            current_str += char

    return current_str

from typing import List

def longest_continuous_sequence(nums: List[int]) -> int:
    if not nums:
        return 0

    num_set = set(nums)
    max_length = 0

    for num in num_set:
        if num - 1 not in num_set:
            current_num = num
            current_length = 1

            while current_num + 1 in num_set:
                current_num += 1
                current_length += 1

            max_length = max(max_length, current_length)

    return max_length

def can_arrange(arr, k):
    """
    Returns True if the array can be divided into pairs such that the sum of each pair is divisible by k, False otherwise.

    Args:
    arr : List[int] - The list of integers.
    k : int - The integer divisor.

    Returns:
    bool - True if it's possible to divide the array into such pairs, False otherwise.
    """
    if len(arr) % 2 != 0:
        return False

    remainder_count = [0] * k

    for num in arr:
        remainder_count[num % k] += 1

    if remainder_count[0] % 2 != 0:
        return False

    for i in range(1, k):
        if remainder_count[i] != remainder_count[k - i]:
            return False

    return True

def two_sum(nums, target):
    """
    Returns the indices of the two numbers in `nums` that add up to `target`.
    The indices should be returned in ascending order. If no such pair exists,
    return an empty array.
    """
    num_to_index = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return sorted([num_to_index[complement], i])
        num_to_index[num] = i

    return []

def longest_subsequence(arr):
