    Returns the length of the longest subsequence such that the difference between 
    consecutive elements is either 1 or -1.
    """
    n = len(arr)
    if n == 0:
        return 0

    # Initialize a list to store the longest subsequence length ending at each element
    longest_end = [1] * n

    for i in range(n):
        for j in range(i):
            if abs(arr[i] - arr[j]) == 1:
                longest_end[i] = max(longest_end[i], longest_end[j] + 1)

    return max(longest_end)

def convert(s, numRows):
    if numRows == 1 or numRows >= len(s):
        return s

    rows = [''] * numRows
    current_row = 0
    going_down = False

    for char in s:
        rows[current_row] += char
        if current_row == 0 or current_row == numRows - 1:
            going_down = not going_down
        current_row += 1 if going_down else -1

    return ''.join(rows)

def length_of_lis(nums):
    """
    Returns the length of the longest strictly increasing subsequence in the list of integers.
    """
    if not nums:
        return 0

    # This list will store the longest increasing subsequence length ending at each index
    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def ohms_law(voltage: float, resistance: float, current: float) -> dict[str, float]:
    """
    Calculate voltage, resistance, or current from two given electrical properties.

    Parameters:
    voltage (float): Voltage in Volts
    resistance (float): Resistance in Ohms
    current (float): Current in Amperes

    Returns:
    dict[str, float]: Dictionary with the name/value pair of the calculated property.

    Raises:
    ValueError: If invalid inputs are provided as per the constraints.
    """

    # Input validation
    if (voltage, resistance, current).count(0) != 1:
        raise ValueError("One and only one argument must be 0")
    if voltage < 0:
        raise ValueError("Voltage cannot be negative")
    if resistance < 0:
        raise ValueError("Resistance cannot be negative")
    if current < 0:
        raise ValueError("Current cannot be negative")

    # Calculate the unknown property
    if voltage == 0:
        return {"voltage": resistance * current}
    elif resistance == 0:
        return {"resistance": voltage / current}
    elif current == 0:
        return {"current": voltage / resistance}
    else:
        raise ValueError("Exactly one argument must be 0")

import heapq

def trap_rain_water(elevation_map):
    if not elevation_map or not elevation_map[0]:
        return 0

    m, n = len(elevation_map), len(elevation_map[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Add all the boundary cells to the heap
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (elevation_map[i][j], i, j))
                visited[i][j] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    water_trapped = 0

    while heap:
        height, x, y = heapq.heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                water_trapped += max(0, height - elevation_map[nx][ny])
                heapq.heappush(heap, (max(height, elevation_map[nx][ny]), nx, ny))

    return water_trapped

def find_triplet(arr, targetSum):
    """
    Returns a list of three distinct elements from the array `arr` whose sum is equal to `targetSum`.
    If no such triplet exists, returns an empty list.
    """
    arr.sort()
    n = len(arr)

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            total = arr[i] + arr[left] + arr[right]
            if total == targetSum:
                return [arr[i], arr[left], arr[right]]
            elif total < targetSum:
                left += 1
            else:
                right -= 1

    return []

