def min_path_sum(matrix):
    """
    Returns the minimum sum of obstacles to reach the bottom-right corner from the top-left corner.
    You can only move right or down from a cell.
    """
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])

    # Initialize the first row and first column
    for i in range(1, m):
        matrix[i][0] += matrix[i-1][0]
    for j in range(1, n):
        matrix[0][j] += matrix[0][j-1]

    # Fill the rest of the matrix
    for i in range(1, m):
        for j in range(1, n):
            matrix[i][j] += min(matrix[i-1][j], matrix[i][j-1])

    return matrix[m-1][n-1]

from typing import List

def ternary_search(left: int, right: int, key: int, arr: List[int]) -> int:
    while right >= left:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2

        if key < arr[mid1]:
            right = mid1 - 1
        elif key > arr[mid2]:
            left = mid2 + 1
        else:
            left = mid1 + 1
            right = mid2 - 1

    return -1

def fewest_coins(coins: list, amount: int) -> int:
    """
    Determines the minimum number of coins needed to make up a given amount using the specified coin denominations.
    Returns -1 if it's not possible to make the amount with the given coins.
    """
    # Array to store the minimum coins needed for each amount up to the target amount
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: 0 coins are needed to make the amount 0

    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] != float('inf'):
                dp[x] = min(dp[x], dp[x - coin] + 1)

    return dp[amount] if dp[amount] != float('inf') else -1

def smallest_substring_with_k_distinct(s, k):
    """
    Returns the length of the smallest substring of 's' that contains at least 'k' distinct characters.
    If no such substring exists, return -1.
    """
    if k > len(set(s)):
        return -1

    n = len(s)
    min_length = n + 1
    left = 0
    char_map = {}

    for right in range(n):
        char_map[s[right]] = char_map.get(s[right], 0) + 1

        while len(char_map) >= k:
            min_length = min(min_length, right - left + 1)
            char_map[s[left]] -= 1
            if char_map[s[left]] == 0:
                del char_map[s[left]]
            left += 1

    return min_length if min_length <= n else -1

