        return 0

    # Start from the second to last row, reduce upwards to the top row.
    for row in range(len(triangle) - 2, -1, -1):
        for col in range(len(triangle[row])):
            # Update the current value to be the minimum path sum of itself and the numbers in the row below
            triangle[row][col] += min(triangle[row+1][col], triangle[row+1][col+1])

    # The top element will have the minimum path sum at the end
    return triangle[0][0]

