def euler_totient(n):
    """
    Computes Euler's Totient function for a given integer n.
    """
    if n == 1:
        return 1

    result = n
    p = 2

    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1

    if n > 1:
        result -= result // n

    return result

def next_permutation(num: int) -> int:
    digits = list(str(num))
    n = len(digits)

    if n == 1:
        return -1

    # Step 1: Find the pivot
    i = n - 2
    while i >= 0 and digits[i] >= digits[i + 1]:
        i -= 1

    if i == -1:
        return -1

    # Step 2: Find the smallest digit larger than digits[i] to the right of i
    j = n - 1
    while digits[j] <= digits[i]:
        j -= 1

    # Step 3: Swap the digits[i] with digits[j]
    digits[i], digits[j] = digits[j], digits[i]

    # Step 4: Reverse the sequence from i + 1 to the end
    digits = digits[:i + 1] + digits[i + 1:][::-1]

    return int("".join(digits))

