def prime_factors_or_prime_check(n: int) -> Union[bool, List[int]]:
    """
    Returns True if n is a prime number, otherwise returns a list of prime factors of n.
    """
    if n <= 1:
        return False

    prime_factors = []
    i = 2

    # Checking for smallest factors i.e starting with 2 and moving upward
    while i * i <= n:
        while (n % i) == 0:
            prime_factors.append(i)
            n //= i
        i += 1

    # If n is a prime number greater than 2, then add it to the list
    if n > 1:
        prime_factors.append(n)

    # If no prime factors were found, n is a prime number.
    if len(prime_factors) == 1 and prime_factors[0] == n:
        return True
    else:
        return prime_factors

