def evaluate_postfix(expression: List[str]) -> int:
    stack = []

    for token in expression:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):  # handling negative numbers
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))  # truncate towards zero
    return stack[0]

def simplify_path(path: str) -> str:
    """
    Simplifies a given Unix-style file path to its canonical form.
    """
    # Split the path by '/'
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    # Create the final simplified path
    simplified_path = '/' + '/'.join(stack)
    return simplified_path

def find_the_longest_substring(s):
    """
    Returns the length of the longest substring where each vowel 
    ('a', 'e', 'i', 'o', 'u') appears an even number of times.
    """
    n = len(s)
    # Vowel to the corresponding bit in the bitmask
    vowel_to_bit = {'a': 1, 'e': 2, 'i': 4, 'o': 8, 'u': 16}
    # A dictionary to store the first occurrence of every bitmask
    prefix_indices = {0: -1}

    current_mask = 0
    max_length = 0

    for i, ch in enumerate(s):
        if ch in vowel_to_bit:
            current_mask ^= vowel_to_bit[ch]

        if current_mask not in prefix_indices:
            prefix_indices[current_mask] = i

        if current_mask in prefix_indices:
            max_length = max(max_length, i - prefix_indices[current_mask])

    return max_length

