def longest_unique_subsequence(arr: List[int]) -> int:
    """
    Determines the length of the longest contiguous subsequence of unique integers in an unsorted array.
    """
    if not arr:
        return 0

    max_length = 0
    current_start = 0
    seen_elements = {}

    for current_end, value in enumerate(arr):
        if value in seen_elements and seen_elements[value] >= current_start:
            current_start = seen_elements[value] + 1
        seen_elements[value] = current_end
        max_length = max(max_length, current_end - current_start + 1)

