def minAddToMakeValid(s):
    """
    Returns the minimum number of parentheses to add to make the string valid.
    """
    open_count = 0
    close_count = 0

    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            if open_count > 0:
                open_count -= 1
            else:
                close_count += 1

    return open_count + close_count

def combination_dp(n: int, r: int) -> int:
    """
    Returns the value of nCr using dynamic programming.
    """
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1

    # Initialize a table to store previously computed values of nCr
    dp = [[0 for _ in range(r+1)] for _ in range(n+1)]

    # Compute the values in a bottom-up manner
    for i in range(n+1):
        for j in range(min(i, r)+1):
            if j == 0 or j == i:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]

    return dp[n][r]

