import time
import logging

def send_scheduled_email(recipient_email: str, subject: str, body: str, send_time: datetime.datetime, server_url: str) -> None:
    current_time = datetime.datetime.now()
    if current_time < send_time:
        time_to_wait = (send_time - current_time).total_seconds()
        time.sleep(max(time_to_wait, 0))

    attempts = 3
    for attempt in range(attempts):
        try:
            response = requests.post(server_url, json={
                'recipient': recipient_email,
                'subject': subject,
                'body': body
            })
            if response.status_code == 200:
                return
        except requests.RequestException:
            pass
        time.sleep(2)  # Delay before retry

    logging.basicConfig(filename='email_failures.log', level=logging.ERROR)
    logging.error(f"Failed to send email to {recipient_email} after {attempts} attempts")

from typing import List

def diagonal_traversal(matrix: List[List[int]]) -> List[int]:
    if not matrix: 
        return []

    m = len(matrix)
    n = len(matrix[0])
    result = []

    for d in range(m + n - 1):
        if d < n:
            i = 0
            j = d
        else:
            i = d - n + 1
            j = n - 1

        temp = []
        while i < m and j >= 0:
            temp.append(matrix[i][j])
            i += 1
            j -= 1

        if d % 2 == 0:
            result.extend(temp[::-1])
        else:
            result.extend(temp)

    return result

