def lexicographically_smallest_subsequence(s, k):
    """
    Returns the lexicographically smallest subsequence of length k from string s.
    """
    stack = []
    n = len(s)

    for i, char in enumerate(s):
        while stack and len(stack) + (n - i) > k and stack[-1] > char:
            stack.pop()
        if len(stack) < k:
            stack.append(char)

    return ''.join(stack)

def min_candies(arr):
    """
    Returns the minimum number of candies required to distribute among students
    with the given ratings, ensuring each student receives at least one candy
    and students with higher ratings get more candies than their neighbors.
    """
    n = len(arr)
    if n == 0:
        return 0

    candies = [1] * n

    # First pass: from left to right, ensure each student has more candies than
    # the left neighbor if the rating is higher
    for i in range(1, n):
        if arr[i] > arr[i-1]:
            candies[i] = candies[i-1] + 1

    # Second pass: from right to left, ensure each student has more candies than
    # the right neighbor if the rating is higher
    for i in range(n-2, -1, -1):
        if arr[i] > arr[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)

    # Return the sum of all candies
    return sum(candies)

def merge_author_contributions(author_dicts: list) -> dict:
    """
    Aggregates the paper counts for authors from multiple dictionaries.

    :param author_dicts: List of dictionaries with authors as keys and paper counts as values
    :return: A dictionary with total paper counts for each author
    """
    merged_contributions = {}

    for author_dict in author_dicts:
        for author, count in author_dict.items():
            if author in merged_contributions:
                merged_contributions[author] += count
            else:
                merged_contributions[author] = count

    return merged_contributions

