    counts = {}
    result = []

    for number in lst:
        if counts.get(number, 0) < N:
            result.append(number)
            counts[number] = counts.get(number, 0) + 1

    return result

def longest_palindromic_subsequence(s):
    """
    Return the length of the longest palindromic subsequence you can obtain by deleting characters from s.
    """
    n = len(s)
    if n == 0:
        return 0

    dp = [[0] * n for _ in range(n)]

    for i in range(n-1, -1, -1):
        dp[i][i] = 1
        for j in range(i+1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    return dp[0][n-1]

def transform_string(s):
    """
    Transform the input string by dividing into minimal substrings with unique characters,
    replacing each substring with the character and count of its occurrence.
    """
    if not s:
        return ""

    result = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(f"{s[i - 1]}{count}")
            count = 1
    result.append(f"{s[-1]}{count}")

    return "".join(result)

import json

def sum_json_array(json_string: str) -> int:
    """
    Returns the sum of integers in the JSON encoded string array.

    :param json_string: A JSON string representing an array of integers.
    :return: Sum of the integers in the JSON array.
    :raises ValueError: If the JSON string is not properly formatted or does not contain integers.
    """
    try:
        data = json.loads(json_string)
    except json.JSONDecodeError:
        raise ValueError("Invalid input, expects a JSON encoded string.")

    if not isinstance(data, list):
