import math

def cholesky_decomposition(A: List[List[float]]) -> Optional[List[List[float]]]:
    """
    Perform Cholesky decomposition of a Hermitian positive-definite matrix A.

    Returns a lower triangular matrix V such that V * V^T = A.
    Returns None if A is not Hermitian positive-definite.
    """
    n = len(A)

    # Check if the matrix is square
    if any(len(row) != n for row in A):
        return None

    # Create an n x n zero matrix for the lower triangular result
    V = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1):
            sum = A[i][j]

            for k in range(j):
                sum -= V[i][k] * V[j][k]

            if i == j:
                if sum <= 0:
                    return None  # Not positive-definite
                V[i][j] = math.sqrt(sum)
            else:
                V[i][j] = sum / V[j][j]

    return V

def search_rotated_array(arr, target):
    """
    Searches for a target value in a rotated sorted array. Returns the index if found; otherwise, returns -1.

    Parameters:
    - arr (list[int]): The rotated sorted array.
    - target (int): The target value to search for.

    Returns:
    int: The index of the target value if found; otherwise, -1.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        # Determine which part is properly sorted
        if arr[left] <= arr[mid]:
            # Left part is sorted
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right part is sorted
            if arr[mid] < target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def normalize_path(path: str) -> str:
    """
    Normalizes a given Unix-style file path by resolving `.` and `..`.

    Parameters:
    path (str): The original file path.

    Returns:
    str: The normalized file path.
    """
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    normalized_path = '/' + '/'.join(stack)
    return normalized_path

def rotate_image(image):
    """
    Rotates the given square matrix (2D list) 90 degrees clockwise.
    """
    n = len(image)
    rotated_image = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            rotated_image[j][n - 1 - i] = image[i][j]

    return rotated_image

from typing import List

def spiral_traversal(matrix: List[List[int]]) -> List[int]:
    if not matrix or not matrix[0]:
        return []

    m, n = len(matrix), len(matrix[0])
    result = []
    top, left = 0, 0
    bottom, right = m - 1, n - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for j in range(left, right + 1):
            result.append(matrix[top][j])
        top += 1

        # Traverse from top to bottom
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])
        right -= 1

        if top <= bottom:
            # Traverse from right to left
            for j in range(right, left - 1, -1):
                result.append(matrix[bottom][j])
            bottom -= 1

        if left <= right:
            # Traverse from bottom to top
            for i in range(bottom, top - 1, -1):
                result.append(matrix[i][left])
            left += 1

    return result

def longest_substring_with_constraints(s: str, k: int) -> int:
    if k == 0:
        return 0
    if len(set(s)) <= k:
        return len(s)

    left = 0
    max_length = 0
    char_count = {}

    for right in range(len(s)):
        char_count[s[right]] = char_count.get(s[right], 0) + 1

        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

def multiply_large_numbers(num1: str, num2: str) -> str:
    # Edge case where any number is zero
    if num1 == "0" or num2 == "0":
        return "0"

    # Initialize result array
    result = [0] * (len(num1) + len(num2))

    # Reverse the strings to simplify the positional multiplication
    num1, num2 = num1[::-1], num2[::-1]

    # Perform multiplication digit by digit
    for i in range(len(num1)):
        for j in range(len(num2)):
            mul = int(num1[i]) * int(num2[j])
            result[i + j] += mul
            result[i + j + 1] += result[i + j] // 10
            result[i + j] %= 10

    # Convert result back to string
    while len(result) > 1 and result[-1] == 0:
        result.pop()
    result = result[::-1]
    return ''.join(map(str, result))

