from collections import deque, defaultdict

def can_route_packet(edges: List[Tuple[int, int, int]], start: int, end: int, packet_size: int) -> bool:
    """
    Determine if there is a path from start to end where all edges on the path
    can handle the packet_size.
    """
    graph = defaultdict(list)
    for u, v, b in edges:
        if b >= packet_size:
            graph[u].append(v)
            graph[v].append(u)

    queue = deque([start])
    visited = set()

    while queue:
        node = queue.popleft()
        if node == end:
            return True
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append(neighbor)

    return False

from typing import List

def single_number3(nums: List[int]) -> List[int]:
    # Step 1: XOR all numbers to get the XOR of the two unique numbers
    xor = 0
    for num in nums:
        xor ^= num

    # Step 2: Find the right-most set bit of xor
    rightmost_set_bit = xor & -xor

    # Step 3: Divide numbers into two groups and XOR each group
    num1, num2 = 0, 0
    for num in nums:
        if num & rightmost_set_bit:
            num1 ^= num
        else:
            num2 ^= num

    return [num1, num2]

def find_added_character(s: str, t: str) -> str:
    """
    Find the additional character added to string t.
    """
    char_count = [0] * 26

    for char in s:
        char_count[ord(char) - ord('a')] -= 1

    for char in t:
        char_count[ord(char) - ord('a')] += 1

    for idx, count in enumerate(char_count):
        if count == 1:
            return chr(ord('a') + idx)

