def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers less than or equal to n using the Sieve of Eratosthenes algorithm.
    """
    if n < 2:
        return []

    prime = [True] * (n + 1)
    prime[0] = prime[1] = False

    p = 2
    while p * p <= n:
        if prime[p]:
            for i in range(p * p, n + 1, p):
                prime[i] = False
        p += 1

    return [p for p in range(n + 1) if prime[p]]

def minimal_write_sort(arr):
    """
    Sort an array using Cycle Sort, minimizing the number of write operations.
    """
    n = len(arr)

    for cycle_start in range(n - 1):
        item = arr[cycle_start]

        pos = cycle_start
        for i in range(cycle_start + 1, n):
            if arr[i] < item:
                pos += 1

        if pos == cycle_start:
            continue

        while item == arr[pos]:
            pos += 1

        arr[pos], item = item, arr[pos]

        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, n):
                if arr[i] < item:
                    pos += 1
            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]

    return arr

def next_bigger(num: int) -> int:
    """
    Returns the next higher number that has the exact same set of digits as the given number.
    If no such number exists, returns -1.
    """
    num_list = list(str(num))
    n = len(num_list)

    # Step 1: Find the first digit that is smaller than the digit next to it.
    for i in range(n-2, -1, -1):
        if num_list[i] < num_list[i + 1]:
            break
    else:
        return -1  # If no such digit is found, then all digits are in descending order.

    # Step 2: Find the smallest digit on the right of the found digit, which is larger than the found digit.
    for j in range(n-1, i, -1):
        if num_list[j] > num_list[i]:
            break

    # Step 3: Swap the found digit with the smallest larger digit.
    num_list[i], num_list[j] = num_list[j], num_list[i]

    # Step 4: Reverse the sequence after the original position of the found digit.
    num_list = num_list[:i+1] + num_list[i+1:][::-1]

    return int(''.join(num_list))

from typing import List

def gnome_sort(arr: List[int]) -> List[int]:
    """
    Sorts the list of integers in non-decreasing order using Gnome Sort algorithm.
    """
    index = 0
    while index < len(arr):
        if index == 0 or arr[index] >= arr[index - 1]:
            index += 1
        else:
            arr[index], arr[index - 1] = arr[index - 1], arr[index]
            index -= 1
    return arr

def unique_paths(grid):
    """
    Function to calculate the number of unique paths in a minefield grid.

    Parameters:
    grid (list of list of int): 2D grid representation of the minefield where 0 is an empty cell and 1 is a mine.

    Returns:
    int: The number of unique paths from the top-left corner to the bottom-right corner.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]

    return dp[m - 1][n - 1]

def caesar_decipher(s: str, k: int) -> str:
    """
    Decrypts a given ciphertext encoded with a Caesar Cipher with a given shift 'k'.
    """
    # Reduce k in modulo 26 to handle large shifts
    k = k % 26
    decrypted_message = []

    for char in s:
        if char.isalpha():
            if char.islower():
                # Shift within lowercase letters
                shifted = ord(char) - k
                if shifted < ord('a'):
                    shifted += 26
                decrypted_message.append(chr(shifted))
            elif char.isupper():
                # Shift within uppercase letters
                shifted = ord(char) - k
                if shifted < ord('A'):
                    shifted += 26
                decrypted_message.append(chr(shifted))
        else:
            # Non-alphabet characters remain unchanged
            decrypted_message.append(char)

    return ''.join(decrypted_message)

def count_paths(m, n):
    """
    Returns the number of unique paths from the top-left to the bottom-right 
    corner of a m x n grid, only moving down or right.
    """
    if m == 1 or n == 1:
        return 1

    # Create a 2D table to store results of subproblems
    dp = [[0] * n for _ in range(m)]

    # Initialize the first row and the first column
    for i in range(m):
        dp[i][0] = 1
    for j in range(n):
        dp[0][j] = 1

    # Fill the dp table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

