def longest_subarray_with_two_distinct(arr):
    """
    Returns the length of the longest contiguous subarray that contains at most two distinct numbers.
    """
    if not arr:
        return 0

    n = len(arr)
    max_len = 0
    left = 0
    num_count = {}

    for right in range(n):
        if arr[right] in num_count:
            num_count[arr[right]] += 1
        else:
            num_count[arr[right]] = 1

        while len(num_count) > 2:
            num_count[arr[left]] -= 1
            if num_count[arr[left]] == 0:
                del num_count[arr[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

