def count_ways_to_decode(message: str) -> int:
    if not message or message[0] == '0':
        return 0

    n = len(message)
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1  # Base cases

    for i in range(2, n + 1):
        one_digit = int(message[i-1:i])
        two_digit = int(message[i-2:i])

        if 1 <= one_digit <= 9:
            dp[i] += dp[i-1]
        if 10 <= two_digit <= 26:
            dp[i] += dp[i-2]

    return dp[n]

from collections import Counter

def min_deletions_to_make_anagrams(word1, word2):
    """
    Returns the minimum number of deletions required to make the two strings anagrams.
    """
    count1 = Counter(word1)
    count2 = Counter(word2)

    # Find the characters that need to be deleted
    deletions = 0
    for char in count1:
        if char in count2:
            deletions += abs(count1[char] - count2[char])
        else:
            deletions += count1[char]

    for char in count2:
        if char not in count1:
            deletions += count2[char]

    return deletions

def firstUniqueChar(s: str) -> int:
    """
    Returns the index of the first non-repeating character in the string `s`.
    If no such character exists, returns -1.
    """
    # Dictionary to store frequency of each character
    char_count = {}

    # First pass: count the frequencies
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass: find the first unique character
    for index, char in enumerate(s):
        if char_count[char] == 1:
            return index

    return -1

