def stooge_sort(arr: List[int], l: int, h: int) -> None:
    if l >= h:
        return

    if arr[l] > arr[h]:
        arr[l], arr[h] = arr[h], arr[l]

    if h - l + 1 > 2:
        third = (h - l + 1) // 3
        stooge_sort(arr, l, h - third)
        stooge_sort(arr, l + third, h)
        stooge_sort(arr, l, h - third)

def max_points(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Create a dp array to keep track of the maximum points at each cell
    dp = [[0] * n for _ in range(m)]

    # Initialize the starting point
    dp[0][0] = grid[0][0]

    # Fill the first row (can only be reached from the left)
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the first column (can only be reached from the top)
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp array
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # The bottom-right corner will contain the maximum points
    return dp[m-1][n-1]

def custom_sort(nums: list[int]) -> list[int]:
    """
    Given a list of integers, return a new list with the integers sorted in ascending order.
    The implementation uses Bubble Sort algorithm from scratch.
    """
    n = len(nums)
    for i in range(n):
        for j in range(0, n-i-1):
            if nums[j] > nums[j+1]:
                nums[j], nums[j+1] = nums[j+1], nums[j]
    return nums

def cycle_sort(arr):
    """
    Sorts the array using Cycle Sort algorithm and returns the sorted array.
    """
    writes = 0

    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find where to put the item
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == cycle_start:
            continue

        # Otherwise, put the item to the right position
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

def calculate_fine(days_overdue, daily_fine, max_fine):
    """
    Calculate the fine for overdue books.

    Parameters:
    days_overdue (int): Number of days the book is overdue.
    daily_fine (float): Fine charged per day the book is overdue.
    max_fine (float): Maximum fine that can be charged for a borrowed book.

    Returns:
    float: The calculated fine rounded to two decimal places.
    """
    if days_overdue < 0:
        raise ValueError("days_overdue cannot be negative")

    if days_overdue == 0:
        return 0.0

    calculated_fine = days_overdue * daily_fine
    if calculated_fine > max_fine:
        return round(max_fine, 2)

    return round(calculated_fine, 2)

def minRemovals(nums, k):
    nums.sort()
    left = 0
    result = len(nums)

    for right in range(len(nums)):
        while nums[right] - nums[left] > k:
            left += 1
        result = min(result, len(nums) - (right - left + 1))

    return result

