def can_make_symmetric(lights):
    """
    Given a binary string `lights`, check whether it is possible to make the string symmetric by toggling at most one light.
    """
    n = len(lights)
    mismatch_count = 0

    for i in range(n // 2):
        if lights[i] != lights[n - i - 1]:
            mismatch_count += 1
            if mismatch_count > 1:
                return False

    return True

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    n = len(s)
    if n == 0:
        return 0

    char_map = {}
    left = 0
    max_len = 0

    for right in range(n):
        if s[right] in char_map:
            left = max(left, char_map[s[right]] + 1)
        char_map[s[right]] = right
        max_len = max(max_len, right - left + 1)

    return max_len

def climb_stairs_variation(steps: int) -> int:
    """
    Returns the number of distinct ways to climb to the top using 1, 2, or 3 steps at a time.
    """
    if steps == 1:
        return 1
    if steps == 2:
        return 2
    if steps == 3:
        return 4

    # Initialize three variables to keep track of ways to climb for the last three positions
    a, b, c = 1, 2, 4

    for i in range(4, steps + 1):
        total_ways = a + b + c
        a, b, c = b, c, total_ways

    return c

def sparse_recovery(array):
    """
    Determines if the stream of sensor readings results in exactly
    one unique non-zero value when all values cancel each other out.

    Parameters:
    array (list of tuples): List where each tuple contains an integer value and a '+' or '-' sign.

    Returns:
    int or None: The unique non-zero value if the stream is 1-sparse, otherwise None.
    """
    counter = {}

    for value, sign in array:
        if sign == '+':
            if value in counter:
                counter[value] += 1
            else:
                counter[value] = 1
        elif sign == '-':
            if value in counter:
                counter[value] -= 1
                if counter[value] == 0:
                    del counter[value]
            else:
                counter[value] = -1

    if len(counter) == 1:
        return next(iter(counter))
    else:
        return None

def max_length_of_substring_with_2_distinct_chars(s):
    """
    Returns the maximum length of a substring that contains no more than 2 distinct characters.
    """
    if not s:
        return 0

    left, right = 0, 0
    max_len = 0
    char_count = {}

    while right < len(s):
        if s[right] in char_count:
            char_count[s[right]] += 1
        else:
            char_count[s[right]] = 1

        while len(char_count) > 2:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_len = max(max_len, right - left + 1)
        right += 1

    return max_len

def edit_distance(str1: str, str2: str) -> int:
    """
    Calculates the edit distance (Levenshtein distance) between two strings str1 and str2.
    """
    m, n = len(str1), len(str2)

    # Initialize the DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # Deletion
                                   dp[i][j - 1],    # Insertion
                                   dp[i - 1][j - 1] # Substitution
                                  )

    return dp[m][n]

def spiral_traversal(matrix):
    """
    Perform a spiral traversal on a given m x n matrix.

    :param matrix: List[List[int]], 2D list of integers representing the matrix.
    :return: List[int], elements of the matrix in spiral order.
    """
    if not matrix or not matrix[0]:
        return []

    result = []
    top, bottom, left, right = 0, len(matrix) - 1, 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for i in range(left, right + 1):
            result.append(matrix[top][i])
        top += 1

        # Traverse downwards
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])
        right -= 1

        if top <= bottom:
            # Traverse from right to left
            for i in range(right, left - 1, -1):
                result.append(matrix[bottom][i])
            bottom -= 1

        if left <= right:
            # Traverse upwards
            for i in range(bottom, top - 1, -1):
                result.append(matrix[i][left])
            left += 1

    return result

def title_case(s: str) -> str:
