def max_subarray_sum(nums):
    """
    Find the contiguous subarray within an array, `nums`, which has the largest sum, and return its sum.
    """
    if not nums:
        return 0

    max_current = max_global = nums[0]
    for num in nums[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

from typing import List

def min_jumps(arr: List[int]) -> int:
    if len(arr) <= 1:
        return 0

    jumps = 0
    current_end = 0
    farthest = 0
    for i in range(len(arr) - 1):
        farthest = max(farthest, i + arr[i])
        if i == current_end:
            jumps += 1
            current_end = farthest
            if current_end >= len(arr) - 1:
                break

    return jumps

def two_sum(array, target):
    """
    Finds two indices of elements in `array` that add up to `target`.

    Args:
    array (List[int]): The list of integers.
    target (int): The target sum.

    Returns:
    Tuple[int, int]: A tuple containing the indices of the two elements that add up to `target`.
    """
    num_to_index = {}

    for index, num in enumerate(array):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], index)
        num_to_index[num] = index

    return None  # This will never be reached due to constraint guarantees.

def longest_increasing_subsequence_with_constraint(arr, k):
    """
    Returns the length of the longest increasing subsequence such that
    the difference between the maximum and minimum element of the subsequence
    is less than or equal to k.
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and (arr[i] - arr[j]) <= k:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def is_prime_number(n: int) -> str:
    """
    Determine if the given number is a prime. Return "Prime" if it is a prime number, 
    otherwise return "Not Prime". Raise ValueError if the number is less than 1.

    Parameters:
    n (int): The number to check.

    Returns:
    str: "Prime" if the number is a prime, "Not Prime" otherwise.
    """
    if n < 1:
        raise ValueError("Number must be greater than 0")

    if n == 1:
        return "Not Prime"

    if n == 2:
        return "Prime"

    if n % 2 == 0:
        return "Not Prime"

    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return "Not Prime"

    return "Prime"

from collections import deque

def walls_and_gates(rooms):
    """
    Fill each empty room with the distance to its nearest gate. 
    If it is impossible to reach a gate, it should remain INF.

    :param rooms: List[List[int]], a 2D grid containing -1, 0, and INF.
    """
    if not rooms or not rooms[0]:
        return

    INF = 2147483647
    rows, cols = len(rooms), len(rooms[0])
    queue = deque()

    # Initialize queue with all gates' positions
    for r in range(rows):
        for c in range(cols):
            if rooms[r][c] == 0:
                queue.append((r, c))

    # Perform BFS from all gates simultaneously
    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]
    while queue:
        x, y = queue.popleft()
        for dr, dc in directions:
            r, c = x + dr, y + dc
            if 0 <= r < rows and 0 <= c < cols and rooms[r][c] == INF:
                rooms[r][c] = rooms[x][y] + 1
                queue.append((r, c))

def smallest_substring_length(s):
    # Set of all unique characters in the input string
    unique_chars = set(s)
    required_char_count = len(unique_chars)

    if required_char_count == 0:
        return 0

    # Dictionary to count the characters in the current window
    window_char_count = {}
    min_length = float('inf')

    left = 0

    # Number of unique characters in the current window that match the requirement
    num_chars_matched = 0

    for right, char in enumerate(s):
        if char in window_char_count:
            window_char_count[char] += 1
        else:
            window_char_count[char] = 1

        if window_char_count[char] == 1:
            num_chars_matched += 1

        while num_chars_matched == required_char_count:
            # Calculate the current window length
            current_length = right - left + 1
            min_length = min(min_length, current_length)

            # Try to shrink the window from the left
            left_char = s[left]
            window_char_count[left_char] -= 1
            if window_char_count[left_char] == 0:
                num_chars_matched -= 1

            left += 1

    return min_length

def count_odd_even(numbers: list[int]) -> tuple[int, int]:
