import os

def get_absolute_path(file: str) -> str:
    """
    Returns the absolute path for the given file path, resolving relative paths
    and paths with '~' referring to the home directory.
    """
    if not file:
        return os.path.abspath('.')

    # Expand the user's home directory if the path starts with ~
    if file.startswith('~'):
        file = os.path.expanduser(file)

    # Convert to absolute path
    return os.path.abspath(file)

from typing import List, Tuple

def optimized_bubble_sort(arr: List[int], simulation: bool = False) -> Tuple[List[int], int]:
    n = len(arr)
    operations = 0
    for i in range(n):
        swapped = False
        if simulation:
            print(f'Iteration {i+1}: {arr}')
        for j in range(0, n - i - 1):
            operations += 1  # count comparison
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
                operations += 1  # count swap
        if not swapped:
            break
    return arr, operations

def maxConsecutiveOnes(nums, k):
    """
    Returns the maximum number of consecutive 1s in the array if you can flip at most k 0s.
    """
    left = 0
    max_ones = 0
    zero_count = 0

    for right in range(len(nums)):
        if nums[right] == 0:
            zero_count += 1

        while zero_count > k:
            if nums[left] == 0:
                zero_count -= 1
            left += 1

        max_ones = max(max_ones, right - left + 1)

    return max_ones

def isMatch(text: str, pattern: str) -> bool:
    # Create a DP table with dimensions (len(text) + 1) x (len(pattern) + 1)
    dp = [[False] * (len(pattern) + 1) for _ in range(len(text) + 1)]
    dp[0][0] = True  # Both text and pattern are empty

    # Handle patterns like a*, a*b*, a*b*c* which can match with an empty text
    for j in range(2, len(pattern) + 1):
        if pattern[j-1] == '*':
            dp[0][j] = dp[0][j-2]

    for i in range(1, len(text) + 1):
        for j in range(1, len(pattern) + 1):
            if pattern[j-1] == text[i-1] or pattern[j-1] == '.':
                dp[i][j] = dp[i-1][j-1]
            elif pattern[j-1] == '*':
                dp[i][j] = dp[i][j-2]  # * means 0 occurrence
                if pattern[j-2] == text[i-1] or pattern[j-2] == '.':
                    dp[i][j] |= dp[i-1][j]  # * means 1 or more occurrence

    return dp[len(text)][len(pattern)]

def remove_adjacent_duplicates(s):
    """
    Recursively eliminate all adjacent duplicate characters from the string
    until no such adjacent duplicates remain.

    :param s: Input string containing only lowercase letters
    :return: String after all adjacent duplicates have been removed
    """
    stack = []

    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)

    return ''.join(stack)

def is_rotated_password(password: str, candidate: str) -> bool:
    """
    Determines if the candidate password is a rotated version of the original password.
    """
    if len(password) != len(candidate):
        return False
    # Check if candidate is a substring of password+password
    return candidate in (password + password)

def calculate_visits(log_file: str) -> dict:
    """
    Reads a log file and calculates the total number of visits per user.

    Args:
    log_file (str): The path to the log file.

    Returns:
    dict: A dictionary where the keys are user identifiers and the values are the total number of visits for each user.
    """
    visits = {}
    try:
        with open(log_file, 'r') as file:
            for line in file:
                try:
                    user_id, _ = line.strip().split()
                    if user_id in visits:
                        visits[user_id] += 1
                    else:
                        visits[user_id] = 1
                except ValueError:
                    # Skipping the line if it does not have exactly two elements
                    continue
    except FileNotFoundError:
        print(f"File not found: {log_file}")
    except Exception as e:
        print(f"An error occurred: {e}")

    return visits

