def min_add_to_make_valid(s):
    """
    Return the minimum number of parentheses needed to be inserted to make the string s valid.
    """
    left_needed = 0
    right_needed = 0
    for char in s:
        if char == '(':
            right_needed += 1
        elif char == ')':
