            else:
                left_needed += 1
    return left_needed + right_needed

from typing import List

def gnome_sort(arr: List[int]) -> List[int]:
    """
    Sorts a list of integers using the Gnome Sort algorithm.
    """
    index = 0
    while index < len(arr):
        if index == 0 or arr[index] >= arr[index - 1]:
            index += 1
        else:
            arr[index], arr[index - 1] = arr[index - 1], arr[index]
            index -= 1
    return arr

def cycle_sort(arr):
    writes = 0

    for cycleStart in range(0, len(arr) - 1):
        item = arr[cycleStart]
        pos = cycleStart

        # Find where to put the item.
        for i in range(cycleStart + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        if pos == cycleStart:
            continue

        while item == arr[pos]:
            pos += 1

        arr[pos], item = item, arr[pos]
        writes += 1

        while pos != cycleStart:
            pos = cycleStart
            for i in range(cycleStart + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

def num_decodings(s: str) -> int:
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    # Base cases
    dp[0] = 1
    dp[1] = 1 if s[0] != '0' else 0

    for i in range(2, n + 1):
        one_digit = int(s[i - 1:i])
        two_digits = int(s[i - 2:i])

        if 1 <= one_digit <= 9:
            dp[i] += dp[i - 1]
        if 10 <= two_digits <= 26:
            dp[i] += dp[i - 2]

    return dp[n]

def transitive_closure(vertices, edges):
    """
    Computes the transitive closure of a directed graph.

    :param vertices: Number of vertices in the graph.
    :param edges: List of pairs (source, target) representing directed edges in the graph.
    :return: A 2D list representing the transitive closure of the graph.
    """
    closure = [[0] * vertices for _ in range(vertices)]

    # Initialize the adjacency matrix representation of the graph
    for i in range(vertices):
        closure[i][i] = 1  # Every vertex is reachable from itself

    for u, v in edges:
        closure[u][v] = 1

    # Use the Floyd-Warshall algorithm to compute the transitive closure
    for k in range(vertices):
        for i in range(vertices):
            for j in range(vertices):
                if closure[i][k] and closure[k][j]:
                    closure[i][j] = 1

    return closure

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_index_map = {}
    longest = 0
    start = 0

    for index, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = index
        longest = max(longest, index - start + 1)

    return longest

