def hailstone_length(n: int) -> int:
    """
    Computes the length of the hailstone sequence starting at n and ending at 1.
    """
    length = 1
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        length += 1
    return length

from typing import List, Tuple

def manage_warehouse(commands: List[str]) -> List[Tuple[str, int]]:
    # Initialize an empty dictionary to store the product inventory
    inventory = {}

    # Process each command in order
    for command in commands:
        parts = command.split()
        action = parts[0]
        product_name = parts[1]

        if action == "ADD":
            quantity = int(parts[2])
            if product_name in inventory:
                inventory[product_name] += quantity
            else:
                inventory[product_name] = quantity

        elif action == "REMOVE":
            if product_name in inventory:
                del inventory[product_name]

        elif action == "UPDATE":
            quantity = int(parts[2])
            if product_name in inventory:
                inventory[product_name] = quantity

    # Convert the inventory dictionary to a sorted list of tuples
    sorted_inventory = sorted(inventory.items())

    return sorted_inventory

def replace_words(s, dictionary):
