    s (str): The input string.
    dictionary ([str]): List of words to be replaced.

    Returns:
    str: The resulting string after replacements.
    """
    words = s.split()
    lower_dictionary = {word.lower() for word in dictionary}

    for i in range(len(words)):
        if words[i].lower() in lower_dictionary:
            words[i] = '*' + words[i] + '*'

    return ' '.join(words)

from collections import deque

def shortest_path(graph, start, target):
    """
    Finds the shortest path in a directed acyclic graph from start node to target node.
    If no path exists, returns an empty list.
    """
    if start == target:
        return [start]

    queue = deque([(start, [start])])
    visited = set([start])

    while queue:
        current_node, path = queue.popleft()

        for neighbor in graph.get(current_node, []):
            if neighbor not in visited:
                if neighbor == target:
                    return path + [neighbor]
                queue.append((neighbor, path + [neighbor]))
                visited.add(neighbor)

    return []

def lexicographically_smallest_string(s):
    """
    Returns the lexicographically smallest string that can be achieved
    by repeatedly reversing any two-character substring in the input string s.
    """
    # Convert string to list for in-place manipulation
    s = list(s)

    # We can use a simple greedy approach by continually sorting the string
    n = len(s)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if s[j] > s[j + 1]:
                # Swap adjacent characters if they are in wrong order
                s[j], s[j + 1] = s[j + 1], s[j]

    # Join the list back into a string
    return ''.join(s)

def compute_balances(transactions):
    """
    Compute the net balance for each account based on the given transactions.

    :param transactions: List of lists where each sublist contains
                         [transaction_id, account_id, transaction_type, amount].
    :return: Dictionary with account_id as keys and net balance as values.
    """
    balances = {}
    for transaction in transactions:
        transaction_id, account_id, transaction_type, amount = transaction

        if account_id not in balances:
            balances[account_id] = 0

        if transaction_type == 'debit':
            balances[account_id] -= amount
        elif transaction_type == 'credit':
            balances[account_id] += amount

    return balances

def iterative_binomial_coefficient(n: int, k: int) -> int:
    """
    Computes the binomial coefficient C(n, k) using an iterative approach.
    """
    if k > n - k:
        k = n - k

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def maximalSquare(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    max_side = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

def optimized_gcd(a: int, b: int) -> int:
    """
    Compute the greatest common divisor (GCD) using the Euclidean algorithm
    optimized with bitwise operations.
    """
    if a == 0:
        return b
    if b == 0:
        return a

    # Use the fact that GCD(a, b) == GCD(b, a % b)
    while b != 0:
        a, b = b, a % b

    return a

def optimized_exchange_sort(arr):
    """
    Sorts a list of integers using an optimized version of the Exchange Sort.

    This function handles various edge cases efficiently and reduces unnecessary swaps.
    """
    n = len(arr)
    if n <= 1:
        # No need to sort if list is empty or has one element.
        return arr

    for i in range(n-1):
        swapped = False
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                # Swap the elements if they are in the wrong order
                arr[i], arr[j] = arr[j], arr[i]
                swapped = True
        if not swapped:
            # If no swaps occurred in the inner loop, array is sorted
            break

    return arr

def nth_fibonacci(n):
    """
    Returns the nth Fibonacci number using an iterative approach.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

from typing import List

def enhanced_gnome_sort(arr: List[int]) -> List[int]:
    n = len(arr)
    index = 0
    last_sorted_position = 0

    while index < n:
        if index == 0 or arr[index] >= arr[index - 1]:
            if index == last_sorted_position:
                last_sorted_position += 1
            index += 1
        else:
            arr[index], arr[index - 1] = arr[index - 1], arr[index]
            index -= 1

            if index < last_sorted_position:
                last_sorted_position = index + 1

    return arr

def find_pair(arr, target):
    """
    Finds two numbers in the sorted array that sum up to the target value.

    Args:
    arr (list[int]): A sorted list of integers.
    target (int): The target sum.

    Returns:
    tuple[int, int] or None: A tuple of two integers that sum up to the target,
    or None if no such pair exists.
    """
    left, right = 0, len(arr) - 1

    while left < right:
        current_sum = arr[left] + arr[right]
        if current_sum == target:
            return (arr[left], arr[right])
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return None

