def four_sum_exists(arr, target):
    """
    Determines if there are four elements in `arr` whose sum is equal to `target`.

    :param arr: list of integers
    :param target: integer target sum
    :return: True if four elements sum to `target`, otherwise False
    """
    arr.sort()
    length = len(arr)

    for i in range(length - 3):
        for j in range(i + 1, length - 2):
            left, right = j + 1, length - 1
            while left < right:
                total = arr[i] + arr[j] + arr[left] + arr[right]
                if total == target:
                    return True
                elif total < target:
                    left += 1
                else:
                    right -= 1
    return False

def max_length_of_special_substring(s):
    """
    Finds the maximum length of a special substring containing equal numbers of 'a' and 'b' in the string s.
    If no such substring exists, returns 0.
    """
    max_length = 0
    for i in range(len(s)):
        count_a = 0
        count_b = 0
        for j in range(i, len(s)):
            if s[j] == 'a':
                count_a += 1
            elif s[j] == 'b':
                count_b += 1

            if count_a == count_b:
                max_length = max(max_length, j - i + 1)

    return max_length

