def smallest_integer_with_sum(n):
    """
    Returns the smallest integer x as a string such that the sum of the digits in x
    equals n, and x is greater than or equal to n.
    """
    if n <= 9:
        return str(n)

    # Start with the number itself
    x = n
    while sum(int(digit) for digit in str(x)) != n:
        x += 1

    return str(x)

import heapq

def minPathCost(grid):
    """
    Returns the minimum cost to reach the bottom-right corner of the grid from the top-left corner.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    heap = [(grid[0][0], 0, 0)]  # (cost, row, col)
    visited = set()

    while heap:
        cost, row, col = heapq.heappop(heap)
        if (row, col) in visited:
            continue
        visited.add((row, col))

        if row == rows - 1 and col == cols - 1:
            return cost

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols and (new_row, new_col) not in visited:
                heapq.heappush(heap, (cost + grid[new_row][new_col], new_row, new_col))

    return -1  # If there's no path (shouldn't reach here for valid input)

def two_sum(arr, target):
    """
    Finds the two indices in the list `arr` such that the numbers at those indices add up to `target`.

    Parameters:
    arr (list of int): List of integers.
    target (int): The target sum.

    Returns:
    list of int: The indices of the two numbers that add up to the target, in increasing order.
    """
    num_to_index = {}
    for index, num in enumerate(arr):
        complement = target - num
        if complement in num_to_index:
            return sorted([num_to_index[complement], index])
        num_to_index[num] = index
    return []

def longest_unique_substring(text):
    """
    Returns the longest substring without repeating characters.
    If there are multiple substrings with the same maximum length, returns the first one.
    """
    if not text:
        return ""

    start = max_length = 0
    used_char = {}
    longest_substr = ''

    for i, char in enumerate(text):
        if char in used_char and start <= used_char[char]:
            start = used_char[char] + 1
        else:
            cur_length = i - start + 1
            if cur_length > max_length:
                max_length = cur_length
                longest_substr = text[start:i+1]

        used_char[char] = i

    return longest_substr

def reduce_string_length(s):
    """
    Returns the length of the shortest string possible by performing any number of deletions 
    of two adjacent characters that are different.

    Parameters:
    s (str): input string containing only 'a', 'b' and 'c'

    Returns:
    int: shortest possible length of the string
    """
    stack = []

    for char in s:
        if stack and stack[-1] != char:
            stack.pop()
        else:
            stack.append(char)

    return len(stack)

def stoogesort(arr: list, l: int, h: int) -> None:
    if l >= h:
        return

    if arr[l] > arr[h]:
        arr[l], arr[h] = arr[h], arr[l]

    if h - l + 1 > 2:
        t = (h - l + 1) // 3
        stoogesort(arr, l, h - t)
        stoogesort(arr, l + t, h)
        stoogesort(arr, l, h - t)

from typing import List

def min_max_normalize(data: List[float], new_min: float, new_max: float) -> List[float]:
    if not data:
        return []

    old_min = min(data)
    old_max = max(data)

    if old_min == old_max:
        return [new_min for _ in data]

    return [(new_max - new_min) * (x - old_min) / (old_max - old_min) + new_min for x in data]

