def one_sparse(stream: List[Tuple[int, str]]) -> Optional[int]:
    count_map = {}

    for value, sign in stream:
        if sign == '+':
            count_map[value] = count_map.get(value, 0) + 1
        elif sign == '-':
            count_map[value] = count_map.get(value, 0) - 1

    non_zero_counts = [key for key, count in count_map.items() if count != 0]

    if len(non_zero_counts) == 1:
