def max_valid_lineup(heights):
    """
    Finds the maximum number of people that can form a valid lineup
    where each person is strictly taller than the person in front.

    Parameters:
    heights (list): List of integers representing the heights of people.

    Returns:
    int: Maximum number of people forming a valid lineup.
    """
    if not heights:
        return 0

    # Lis will store the length of the longest increasing subsequence up to each element.
    lis = [1] * len(heights)

    for i in range(1, len(heights)):
        for j in range(0, i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    return max(lis)

def three_sum(nums, target):
    """
    Determines if there exist three distinct elements in nums such that their sum equals target.

    :param nums: List of integers.
    :param target: Integer target sum.
    :return: True if such a combination exists, otherwise False.
    """
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False

