    Rotates an n x n matrix 90 degrees clockwise in place.
    """
    n = len(mat)
    # Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            mat[i][j], mat[j][i] = mat[j][i], mat[i][j]

    # Reverse each row
    for i in range(n):
        mat[i].reverse()

def longest_substring_k_distinct(s: str) -> int:
    """
    Finds the length of the longest substring containing at most 2 distinct characters.
    """
    if not s:
        return 0

    char_map = {}
    left = 0
    max_length = 0

    for right in range(len(s)):
        char_map[s[right]] = char_map.get(s[right], 0) + 1

        while len(char_map) > 2:
            char_map[s[left]] -= 1
            if char_map[s[left]] == 0:
                del char_map[s[left]]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

from typing import List

def maximalSquare(matrix: List[List[int]]) -> int:
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])
    max_side = 0

    # Create DP table with extra row and column
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if matrix[i - 1][j - 1] == 1:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side * max_side

def evaluate_postfix_expression(expression: str) -> int:
    """
    Evaluates a given postfix expression.

    :param expression: A string containing the postfix expression.
    :return: The integer result of the evaluated expression.
    """
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        else:
            right = stack.pop()
            left = stack.pop()

            if token == '+':
                result = left + right
            elif token == '-':
                result = left - right
            elif token == '*':
                result = left * right
            elif token == '/':
                result = left // right

            stack.append(result)

    return stack[0]

def is_valid_huffman_encoding(encoded_string: str, huffman_tree: dict) -> bool:
    """
    Returns True if the encoded_string can be decoded using the provided huffman_tree,
    otherwise returns False.
    """
    # Create a reverse lookup dictionary for easy matching of encodings to characters
    reverse_huffman_tree = {v: k for k, v in huffman_tree.items()}

    i = 0
    length = len(encoded_string)

    while i < length:
        match_found = False
        for code in reverse_huffman_tree:
            if encoded_string.startswith(code, i):
                i += len(code)
                match_found = True
                break
        if not match_found:
            return False

    return i == length

def sum_of_squares_difference(n: int) -> int:
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")

    if n <= 0:
        raise ValueError("n must be a positive integer")

    sum_of_squares = sum(i**2 for i in range(1, n + 1))
    square_of_sum = sum(range(1, n + 1)) ** 2

    difference = square_of_sum - sum_of_squares

    return difference

def is_multiple_of_11(num):
    """
    Returns True if the large integer represented as a string 'num' is a multiple of 11, otherwise False.
    """
    odd_sum, even_sum = 0, 0
    for i, digit in enumerate(num):
        if i % 2 == 0:
            odd_sum += int(digit)
        else:
            even_sum += int(digit)

    return (odd_sum - even_sum) % 11 == 0

def quick_sort(arr):
    """
    Function that implements the QuickSort algorithm to sort a given list of integers in ascending order.
    """
    if len(arr) <= 1:
        return arr
    else:
        pivot = arr[len(arr) // 2]
        left = [x for x in arr if x < pivot]
        middle = [x for x in arr if x == pivot]
        right = [x for x in arr if x > pivot]
        return quick_sort(left) + middle + quick_sort(right)

def first_unique_char(input_string: str) -> str:
    """
    Finds and returns the first non-repeating character in the input string.
    If all characters are repeating or the string is empty, returns an empty string.
    """
    # Dictionary to keep track of character frequency
    char_count = {}

    # First pass: count the frequency of each character
    for char in input_string:
        char_count[char] = char_count.get(char, 0) + 1

    # Second pass: find the first character with a frequency of 1
    for char in input_string:
        if char_count[char] == 1:
            return char

    return ""

from typing import List, Tuple, Dict

def analyze_logs(logs: List[dict]) -> Tuple[Dict[str, List[str]], List[str]]:
    visitor_activity = {}
    url_visit_count = {}

    for log in logs:
        visitor_id = log['visitor_id']
        url = log['url']

        # Maintain the visitor activity as ordered lists of URLs
        if visitor_id not in visitor_activity:
            visitor_activity[visitor_id] = []
        visitor_activity[visitor_id].append(url)

        # Count visit frequency for URLs
        if url not in url_visit_count:
            url_visit_count[url] = 0
        url_visit_count[url] += 1

    # Sort URLs by visit count in descending order
    sorted_urls = sorted(url_visit_count.keys(), key=lambda x: url_visit_count[x], reverse=True)

    return visitor_activity, sorted_urls

def minimum_trips(packages, capacity):
    trips = 0
    i = 0
    while i < len(packages):
        if packages[i] <= capacity:
            trips += 1
            i += 1
        else:
            trips += 1
            packages[i] -= capacity
    return trips

def length_of_longest_unique_substring(s):
    """
    Returns the length of the longest substring containing unique characters 
    within the given string `s`.
    """
    max_length = 0

    words = s.split()
    for word in words:
        seen = {}
        start = 0
        for end, char in enumerate(word):
            if char in seen:
                start = max(start, seen[char] + 1)
            seen[char] = end
            max_length = max(max_length, end - start + 1)

    return max_length

