def sum_of_multiples(numbers, limit):
    """
    Calculate the sum of all multiples of given numbers up to the specified limit.
    """
    if not numbers:
        return 0

    multiples = set()

    for number in numbers:
        if number <= 0:
            continue
        for multiple in range(number, limit, number):
            multiples.add(multiple)

    return sum(multiples)

def is_valid_parentheses(s):
    """
    Returns True if the input string has balanced parentheses, False otherwise.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def find_length(arr1: list, arr2: list) -> int:
