from typing import List

def count_anagram_pairs(words: List[str]) -> int:
    if not isinstance(words, list) or not all(isinstance(word, str) for word in words):
        raise TypeError("The input must be a list of strings.")

    anagram_map = {}
    for word in words:
        if not word.isalpha() or not word.islower():
            raise ValueError("Each word must consist of lowercase alphabets only.")

        sorted_word = ''.join(sorted(word))
        if sorted_word in anagram_map:
            anagram_map[sorted_word] += 1
        else:
            anagram_map[sorted_word] = 1

    count = 0
    for value in anagram_map.values():
        if value > 1:
            count += value * (value - 1) // 2

    return count

def min_books(ratings):
    n = len(ratings)
    books = [1] * n

    # Left to right
    for i in range(1, n):
        if ratings[i] > ratings[i-1]:
            books[i] = books[i-1] + 1

    # Right to left
    for i in range(n-2, -1, -1):
        if ratings[i] > ratings[i+1]:
            books[i] = max(books[i], books[i+1] + 1)

    return sum(books)

def are_isomorphic(str1: str, str2: str) -> bool:
    """
    Determines if two strings are isomorphic.

    Two strings are isomorphic if there is a one-to-one mapping between every character of str1 
    to every character of str2.

    Parameters:
    - str1 (str): The first input string.
    - str2 (str): The second input string of the same length as str1.

    Returns:
    - bool: True if strings are isomorphic, otherwise False.

    Raises:
    - ValueError: If the input strings are of different lengths.
    """
    if len(str1) != len(str2):
        raise ValueError("Strings are of different lengths, cannot be isomorphic")

    mapping_str1_to_str2 = {}
    mapping_str2_to_str1 = {}

    for char1, char2 in zip(str1, str2):
        if char1 in mapping_str1_to_str2:
            if mapping_str1_to_str2[char1] != char2:
                return False
        else:
            mapping_str1_to_str2[char1] = char2

        if char2 in mapping_str2_to_str1:
            if mapping_str2_to_str1[char2] != char1:
                return False
        else:
            mapping_str2_to_str1[char2] = char1

    return True

def longest_balanced_substring(s):
    """
    Returns the length of the longest balanced substring in the binary string `s`.
    A balanced substring contains an equal number of '0's and '1's.
    """
    longest_length = 0
    balance = 0
    balance_dict = {0:-1}

    for i, char in enumerate(s):
        if char == '0':
            balance -= 1
        else:
            balance += 1

        if balance in balance_dict:
            longest_length = max(longest_length, i - balance_dict[balance])
        else:
            balance_dict[balance] = i

    return longest_length

def contain_string(haystack: str, needle: str) -> int:
    """
    Returns the index of the first occurrence of needle in haystack,
    or -1 if needle is not part of haystack.
    """
    if needle == "":
        return 0
    return haystack.find(needle)

def is_valid(s: str) -> bool:
    """
    Determines if the input string s containing '(', ')', '{', '}', '[' and ']' is valid.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def sort_priorities(tasks):
    """
    Sorts the list `tasks` in-place such that all 0s appear before 1s and all 1s appear before 2s.
    """
    low, mid, high = 0, 0, len(tasks) - 1

    while mid <= high:
        if tasks[mid] == 0:
            tasks[low], tasks[mid] = tasks[mid], tasks[low]
            low += 1
            mid += 1
        elif tasks[mid] == 1:
            mid += 1
        else:
            tasks[mid], tasks[high] = tasks[high], tasks[mid]
            high -= 1

def get_histogram(input_list: list) -> dict:
    """
    This function takes a list of integers and returns a histogram in the form of a dictionary 
    where the keys are the unique integers from the list, and the values are the counts of 
    each integer's occurrences.
    """
    histogram = {}
    for number in input_list:
        if number in histogram:
            histogram[number] += 1
        else:
            histogram[number] = 1
    return histogram

def most_popular_category(orders):
    """
    Identifies the most popular product category based on order data.

    :param orders: List of dictionaries, where each dictionary contains 'order_id', 'product', and 'category'
    :type orders: list
    :return: Most popular category
    :rtype: str
    """
    category_count = {}

    for order in orders:
        category = order['category']
        if category in category_count:
            category_count[category] += 1
        else:
            category_count[category] = 1

    # Find the category with the maximum orders
    max_count = max(category_count.values())
    popular_categories = [category for category, count in category_count.items() if count == max_count]

    # Return the lexicographically smallest category in case of a tie
    return min(popular_categories)

from collections import deque

def ladderLength(beginWord, endWord, wordList):
    """
    Returns the length of the shortest transformation sequence from beginWord to endWord
    """
    if endWord not in wordList or not endWord or not beginWord or not wordList:
        return 0

    L = len(beginWord)
    all_combo_dict = {}

    for word in wordList:
        for i in range(L):
            new_word = word[:i] + "*" + word[i+1:]
            if new_word not in all_combo_dict:
                all_combo_dict[new_word] = [word]
            else:
                all_combo_dict[new_word].append(word)

    queue = deque([(beginWord, 1)])
    visited = {beginWord: True}

    while queue:
        current_word, level = queue.popleft()
        for i in range(L):
            intermediate_word = current_word[:i] + "*" + current_word[i+1:]

            for word in all_combo_dict.get(intermediate_word, []):
                if word == endWord:
                    return level + 1
                if word not in visited:
                    visited[word] = True
                    queue.append((word, level + 1))
            all_combo_dict[intermediate_word] = []

    return 0

def atbash_cipher(text: str) -> str:
    """
    Encodes the input text using the Atbash cipher, where each letter in the alphabet
    is mapped to its reverse (e.g. 'a' becomes 'z', 'b' becomes 'y', etc.). The function
    is case-sensitive and non-alphabet characters remain unchanged.
    """
    result = []
    for char in text:
        if char.isalpha():
            if char.islower():
                result.append(chr(219 - ord(char)))
            else:
                result.append(chr(155 - ord(char)))
        else:
            result.append(char)
    return ''.join(result)

from typing import List

def cycle_sort(arr: List[int]) -> List[int]:
    writes = 0

    # traverse array elements and put it to on
    # the right place
    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find position where we put the element
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the element is already in correct position
        if pos == cycle_start:
            continue

        # Ignore all duplicate elements
        while item == arr[pos]:
            pos += 1
        # Put the item to it's right position
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

def does_robot_return(moves: str) -> bool:
    """
    Determines if a sequence of moves will return the robot to its starting position.

    Parameters:
    moves (str): A string representing the robot's moves, where each character is one of 'U', 'D', 'L', or 'R'.

    Returns:
    bool: True if the robot returns to the origin (0, 0), otherwise False.
    """
    x, y = 0, 0

    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    return x == 0 and y == 0

def minOperations(nums, x):
    """
    Returns the minimum number of operations to reduce x to exactly 0
    by subtracting elements from the edges of the array nums.
    """
    target = sum(nums) - x
    if target == 0:
        return len(nums)

    left = 0
    current_sum = 0
    max_len = -1
    for right in range(len(nums)):
        current_sum += nums[right]

        while current_sum > target and left <= right:
            current_sum -= nums[left]
            left += 1

        if current_sum == target:
            max_len = max(max_len, right - left + 1)

    return -1 if max_len == -1 else len(nums) - max_len

def is_anagram_optimized(s: str, t: str) -> bool:
    """
    Determines if string t is an anagram of string s.
    """
    if len(s) != len(t):
        return False

    count = [0] * 26

    for char in s:
        count[ord(char) - ord('a')] += 1

    for char in t:
        count[ord(char) - ord('a')] -= 1
        if count[ord(char) - ord('a')] < 0:
            return False

    return True

