def final_lent_books(operations):
    lent_books = {}
    result = []

    for operation in operations:
        book_id = abs(operation)
        if operation > 0:
            if book_id not in lent_books:
                lent_books[book_id] = True
                result.append(book_id)
        elif operation < 0:
            if book_id in lent_books:
                lent_books.pop(book_id)
                result.remove(book_id)

    return result

def nth_fibonacci(n: int) -> int:
    """
    Returns the n-th Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def least_prime_factor(n: int) -> int:
    """
    Returns the least prime factor of a positive integer n,
    or 0 if n is less than 2.
    """
    if n < 2:
        return 0

    # Check for smallest prime factor starting from 2
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return i

    # If no factors found, n itself is prime
    return n

def check_distances(s, distance):
    """
    Checks if the string `s` meets all the distance requirements described in the array `distance`.
    """
    character_positions = {}
    for i, char in enumerate(s):
        if char in character_positions:
            required_distance = distance[ord(char) - ord('a')]
            actual_distance = i - character_positions[char] - 1
            if actual_distance != required_distance:
                return False
        character_positions[char] = i
    return True

from typing import List

def find_smallest_letter(letters: List[str], target: str) -> str:
    low, high = 0, len(letters) - 1

    while low <= high:
        mid = (low + high) // 2
        if letters[mid] > target:
            high = mid - 1
        else:
            low = mid + 1

    return letters[low % len(letters)]

def custom_pigeonhole_sort(arr: list[int]) -> list[int]:
    if not arr:
        return []

    min_value = min(arr)
    max_value = max(arr)
    size = max_value - min_value + 1

    holes = [0] * size

    for number in arr:
        holes[number - min_value] += 1

    sorted_arr = []
    for i in range(size):
        while holes[i] > 0:
            sorted_arr.append(i + min_value)
            holes[i] -= 1

    return sorted_arr

def max_sum_of_mins(nums, k):
    # Sort the nums array
    sorted_nums = sorted(nums)
    # We need to pick the first k elements of the sorted array since they are the minimum
    return sum(sorted_nums[:k])

def edit_distance(str1: str, str2: str) -> int:
    # Get the lengths of both strings
    len1, len2 = len(str1), len(str2)

    # Initialize a DP table where dp[i][j] represents the edit distance
    # between str1[0..i-1] and str2[0..j-1]
    dp = [[0 for _ in range(len2 + 1)] for _ in range(len1 + 1)]

    # Fill dp table for the base case: transforming an empty string to another
    for i in range(len1 + 1):
        dp[i][0] = i  # i insertions to transform str1 to empty str2
    for j in range(len2 + 1):
        dp[0][j] = j  # j insertions to transform empty str1 to str2

    # Fill the dp table for all other cases
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(
                    dp[i - 1][j] + 1,    # Deletion
                    dp[i][j - 1] + 1,    # Insertion
                    dp[i - 1][j - 1] + 1 # Substitution
                )

    return dp[len1][len2]

def word_pattern(pattern: str, string: str) -> bool:
    words = string.split()
    if len(pattern) != len(words):
        return False

    char_to_word = {}
    word_to_char = {}

    for char, word in zip(pattern, words):
        if char in char_to_word:
            if char_to_word[char] != word:
                return False
        if word in word_to_char:
            if word_to_char[word] != char:
                return False
        char_to_word[char] = word
        word_to_char[word] = char

    return True

def smallest_integer_with_digit_sum(n):
    """
    Returns the smallest integer k such that the sum of the digits of k is equal to n.
    """
    if n <= 9:
        return n
    else:
        k = ""
        while n > 0:
            if n >= 9:
                k = "9" + k
                n -= 9
            else:
                k = str(n) + k
                n = 0
        return int(k)

from typing import List

def summarize_ranges(array: List[int]) -> List[str]:
    if not array:
        return []

    ranges = []
    start = array[0]
    current = start

    for num in array[1:]:
        if num == current + 1:
            current = num
        else:
            if start == current:
                ranges.append(f"{start}")
            else:
                ranges.append(f"{start}-{current}")
            start = num
            current = start

    if start == current:
        ranges.append(f"{start}")
    else:
        ranges.append(f"{start}-{current}")

    return ranges

def max_unique_elements(nums, k):
    """
    Returns the maximum number of unique elements among all possible contiguous subarrays of length `k` in `nums`.
    """
    if len(nums) < k:
        return 0

    max_unique = 0
    for i in range(len(nums) - k + 1):
        subarray = nums[i:i + k]
        unique_elements = len(set(subarray))
        if unique_elements > max_unique:
            max_unique = unique_elements

    return max_unique

def optimized_edit_distance(s1: str, s2: str) -> int:
    """
    Calculate the edit distance (Levenshtein distance) between two strings.
    """
    m, n = len(s1), len(s2)

    # Create a (m+1) x (n+1) matrix to store the distances
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize dp table
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]  # No operation needed
            else:
                dp[i][j] = min(dp[i-1][j] + 1,    # Deletion
                               dp[i][j-1] + 1,    # Insertion
                               dp[i-1][j-1] + 1)  # Substitution

    return dp[m][n]

