def process_flash_sale(available_items: int, orders: List[int]) -> List[int]:
    result = []

    for order in orders:
        if available_items >= order:
            result.append(order)
            available_items -= order
        else:
            result.append(available_items)
            available_items = 0

    return result

def robot_position(movements: str) -> tuple[int, int]:
    """
    Given a string of movements, returns the final position of the robot in the 2D grid.

    :param movements: A string of movements ('U', 'D', 'L', 'R')
    :return: A tuple containing the final coordinates (x, y) of the robot
    """
    x, y = 0, 0

    for move in movements:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    return (x, y)

def balanced_string_split(s):
    """
    Returns the maximum number of balanced substrings possible.
    A balanced substring has an equal number of 'L' and 'R' characters.
    """
    balance_count = 0
    total_balanced = 0

    for char in s:
        if char == 'L':
            balance_count += 1
        elif char == 'R':
            balance_count -= 1

        if balance_count == 0:
            total_balanced += 1

    return total_balanced

def minAddToMakeValid(s: str) -> int:
    """
    Returns the minimum number of parentheses to be added to make the string s valid.
    """
    balance = 0   # Keeps track of balance of parentheses
    add_needed = 0  # Counts the minimum additions needed

    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        if balance < 0:
            add_needed += 1
            balance = 0

    return add_needed + balance

def bellman_ford(graph, source):
    # Step 1: Initialize distances from source to all other nodes as infinity
    # and distance to source itself as 0.
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Step 2: Relax all edges |V| - 1 times.
    for i in range(len(graph) - 1):
        for node in graph:
            for neighbor in graph[node]:
                if distances[node] + graph[node][neighbor] < distances[neighbor]:
                    distances[neighbor] = distances[node] + graph[node][neighbor]

    # Step 3: Check for negative-weight cycles.
    for node in graph:
        for neighbor in graph[node]:
            if distances[node] + graph[node][neighbor] < distances[neighbor]:
                return {}

    return distances

def min_cost_path(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize the DP table with the same dimensions as the grid
    dp = [[0] * n for _ in range(m)]

    # Start from the top-left corner
    dp[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, n):
        dp[0][j] = dp[0][j - 1] + grid[0][j]

    # Fill the first column
    for i in range(1, m):
        dp[i][0] = dp[i - 1][0] + grid[i][0]

    # Fill the rest of the dp table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = grid[i][j] + min(dp[i - 1][j], dp[i][j - 1])

    # The answer is in the bottom-right corner of the DP table
    return dp[m - 1][n - 1]

def remove_reoccurring_characters(string: str) -> str:
    """
    Returns a string with all reoccurring characters removed, 
    preserving only the first occurrence of each character 
    and maintaining the order of first appearance.
    """
    seen = set()
    result = []

    for char in string:
        if char not in seen:
            seen.add(char)
            result.append(char)

    return ''.join(result)

def transpose_matrix(matrix: list[list[int]]) -> list[list[int]]:
    """
    Returns the transpose of the given matrix.
    """
    if not matrix or not matrix[0]:
        return []
    rows, cols = len(matrix), len(matrix[0])
    transposed = [[0] * rows for _ in range(cols)]
    for i in range(rows):
        for j in range(cols):
            transposed[j][i] = matrix[i][j]
    return transposed

