def is_match(s: str, p: str) -> bool:
    """
    Given an input string (s) and a pattern (p), implement regular expression matching
    with support for '.' and '*'.
    """
    # This uses dynamic programming. We'll create a DP table to store results of subproblems.
    # dp[i][j] will be True if first i characters in string s match the first j characters of pattern p.

    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Base case: empty string matches empty pattern
    dp[0][0] = True

    # Deals with patterns that can match the empty string
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Build the table dp in bottom-up manner
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or dp[i - 1][j] and (p[j - 2] == s[i - 1] or p[j - 2] == '.')

    return dp[m][n]

def calculate_factorial(n: int) -> int:
    """
    Calculates the factorial of a non-negative integer n.
    """
    if n == 0:
        return 1
    factorial = 1
    for i in range(1, n + 1):
        factorial *= i
    return factorial

def multiply(num1: str, num2: str) -> str:
    # Base cases
    if num1 == "0" or num2 == "0":
        return "0"
    if num1 == "1":
        return num2
    if num2 == "1":
        return num1

    # Initialize the result array with zeros
    result = [0] * (len(num1) + len(num2))

    # Reverse the input strings for easier calculation
    num1, num2 = num1[::-1], num2[::-1]

    # Multiply each digit and add the results to the result array
    for i in range(len(num1)):
        for j in range(len(num2)):
            product = int(num1[i]) * int(num2[j])
            result[i + j] += product
            result[i + j + 1] += result[i + j] // 10
            result[i + j] %= 10

    # Remove leading zeros and convert to string
    while result[-1] == 0:
        result.pop()

    return ''.join(map(str, result[::-1]))

def most_frequent_word(s):
    """
    Returns the most frequent word in the string s. In case of a tie,
    returns the lexicographically smallest word.
    """
    words = s.split()
    word_count = {}

    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    # Find the word with the highest frequency
    max_frequency = max(word_count.values())

    # Filter words by max frequency and return the lexicographically smallest one
    candidates = [word for word, count in word_count.items() if count == max_frequency]

    return min(candidates)

def extract_phrases(phrases, k):
    """
    Extract all possible phrases of exactly k contiguous words from the given strings, combine them all into a set,
    and return a list of these phrases sorted in lexicographical order.
    """
    result_set = set()

    for phrase in phrases:
        words = phrase.split()
        for i in range(len(words) - k + 1):
            result_set.add(' '.join(words[i:i+k]))

    return sorted(result_set)

def roman_to_int(s: str) -> int:
    """
    Convert a Roman numeral string to an integer.
    """
    roman_to_integer = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    total = 0
    prev_value = 0

    for char in reversed(s):
        current_value = roman_to_integer[char]
        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value

    return total

def check_balance_with_wildcards(s: str) -> bool:
    low, high = 0, 0

    for char in s:
        if char == '(':
            low += 1
            high += 1
        elif char == ')':
            low = max(low - 1, 0)
            high -= 1
        else: # char == '*'
            low = max(low - 1, 0)
            high += 1

        if high < 0:
            return False

    return low == 0

def count_pairs_with_sum(N, array, target):
    # Create a hashmap to store counts of each element
    count_map = {}
    pair_count = 0

    for num in array:
        complement = target - num
        if complement in count_map:
            pair_count += count_map[complement]

        if num in count_map:
            count_map[num] += 1
        else:
            count_map[num] = 1

    return pair_count

def box_volume_calculator(length, width, height):
    if length <= 0 or width <= 0 or height <= 0:
        raise ValueError("All dimensions must be positive")
    return length * width * height

def decode_string(s: str) -> str:
    """
    Decodes an encoded string with the pattern k[encoded_string].
    """
    stack = []
    curr_num = 0
    curr_str = ''

    for char in s:
        if char.isdigit():
            curr_num = curr_num * 10 + int(char)  # In case there are multi-digit numbers
        elif char == '[':
            stack.append((curr_str, curr_num))
            curr_str = ''
            curr_num = 0
        elif char == ']':
            last_str, num = stack.pop()
            curr_str = last_str + num * curr_str
        else:
            curr_str += char

    return curr_str

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters.    
    """
    n = len(s)
    max_length = 0
    start = 0
    used_chars = {}

    for i in range(n):
        if s[i] in used_chars and start <= used_chars[s[i]]:
            start = used_chars[s[i]] + 1
        else:
            max_length = max(max_length, i - start + 1)

        used_chars[s[i]] = i

    return max_length

def total_sales(records):
