def is_fibonacci_subsequence(arr: list[int]) -> bool:
    if any(x < 0 for x in arr):
        raise ValueError("Elements in the input list must be non-negative")

    if not arr:
        return True

    fib_set = set()
    a, b = 0, 1
    while b <= max(arr):
        fib_set.add(b)
        a, b = b, a + b
    fib_set.add(0)  # explicitly add 0 to handle the start of the sequence

    index = 0
    for num in arr:
        if num in fib_set and (index == 0 or num >= arr[index - 1]):
            index += 1
        else:
