def merge_alternately(word1, word2):
    """
    Merges two strings by alternating characters from each string, starting with word1.
    If one string is longer than the other, append the remaining characters to the result.
    """
    result = []
    length1, length2 = len(word1), len(word2)
    min_length = min(length1, length2)

    for i in range(min_length):
        result.append(word1[i])
        result.append(word2[i])

    if length1 > length2:
        result.append(word1[min_length:])
    elif length2 > length1:
        result.append(word2[min_length:])

    return ''.join(result)

from collections import deque

def shortest_path(graph, start, end):
    """
    Returns the number of edges in the shortest path between start and end user in the given graph.
    If no such path exists, returns -1.
    """
    if start == end:
        return 0

    visited = set()
    queue = deque([(start, 0)])  # (current_node, current_distance)

    while queue:
        current_node, distance = queue.popleft()

        if current_node == end:
            return distance

        if current_node not in visited:
            visited.add(current_node)
            for neighbor in graph.get(current_node, []):
                if neighbor not in visited:
                    queue.append((neighbor, distance + 1))

    return -1

