def longest_unique_substring(s: str) -> str:
    if not s:
        return ""

    # Dictionary to remember the last index of each character
    last_index = {}
    start = 0
    max_length = 0
    max_substring = ""

    for end, char in enumerate(s):
        if char in last_index and last_index[char] >= start:
            start = last_index[char] + 1

        last_index[char] = end
        current_length = end - start + 1

        if current_length > max_length:
            max_length = current_length
            max_substring = s[start:end + 1]

