def reverse_without_punctuation(s: str) -> str:
    """
    Reverses the characters of each word in the input string `s` while keeping
    the punctuation marks in their original positions.
    """
    result = []
    for word in s.split(' '):
        new_word = list(word)
        left, right = 0, len(new_word) - 1
        while left < right:
            if new_word[left].isalpha():
                while not new_word[right].isalpha() and left < right:
                    right -= 1
                new_word[left], new_word[right] = new_word[right], new_word[left]
                right -= 1
            left += 1
        result.append(''.join(new_word))
    return ' '.join(result)

from collections import deque

def walls_and_gates(rooms):
    """
    Fills each empty room with the distance to its nearest gate. 
    If it is impossible to reach a gate, it remains filled with inf.
    """
    if not rooms or not rooms[0]:
        return

    m, n = len(rooms), len(rooms[0])
    queue = deque()

    # Initialize the queue with all the gates' positions
    for i in range(m):
        for j in range(n):
            if rooms[i][j] == 0:
                queue.append((i, j))

    # Perform BFS from the gates
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_x, new_y = x + dx, y + dy
            if 0 <= new_x < m and 0 <= new_y < n and rooms[new_x][new_y] == 2147483647:
                rooms[new_x][new_y] = rooms[x][y] + 1
                queue.append((new_x, new_y))

