def min_difference_in_coins(coins):
    """
    Returns the minimum possible absolute difference between sums of two sets A and B.
    """
    total = sum(coins)
    n = len(coins)
    dp = [[False] * (total // 2 + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, total // 2 + 1):
            dp[i][j] = dp[i - 1][j]
            if coins[i - 1] <= j:
                dp[i][j] = dp[i][j] or dp[i - 1][j - coins[i - 1]]

    for j in range(total // 2, -1, -1):
        if dp[n][j]:
            return total - 2 * j

import heapq

def shortest_path(n, edges, src, dst):
    """
    Returns the shortest path distance from source node `src` to target node `dst` in a directed weighted graph.
    If there is no path, return -1.
    """
    # Create adjacency list
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    # Priority queue to hold (distance, node) tuples
    pq = [(0, src)]
    # Distance array initialized with infinity
    dist = {i: float('inf') for i in range(n)}
    dist[src] = 0

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node == dst:
            return current_dist

        if current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_dist + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return -1 if dist[dst] == float('inf') else dist[dst]

def find_modes(array):
    """
    Returns a list of the most frequently occurring value(s) in the array.
    If multiple values have the same highest frequency, return all such values.
    """
    if not array:
