    # Dictionary to store frequencies of elements
    frequency_dict = {}

    for num in array:
        if num in frequency_dict:
            frequency_dict[num] += 1
        else:
            frequency_dict[num] = 1

    # Find the maximum frequency
    max_frequency = max(frequency_dict.values())

    # Collect all elements with the maximum frequency
    modes = [num for num, freq in frequency_dict.items() if freq == max_frequency]

    return modes

def can_transform(s1, s2):
    """
    Determines if s1 can be transformed into s2 by moving at most one character.
    """
    if s1 == s2:
        return True

    if len(s1) != len(s2):
        return False

    # Scan through characters and collect different positions
    differences = []
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            differences.append((s1[i], s2[i]))

    # If exactly two characters are different, check if a single swap suffices
    if len(differences) == 2:
        if differences[0] == differences[1][::-1]:
            return True

    # If more or less than two characters are different, it's impossible with one move
    return False

