def generate_primes(upper_limit: int) -> list[int]:
    """
    Returns a list of prime numbers less than or equal to upper_limit
    using the Sieve of Eratosthenes algorithm.
    """
    if upper_limit < 2:
        return []

    is_prime = [True] * (upper_limit + 1)
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not primes

    for i in range(2, int(upper_limit**0.5) + 1):
        if is_prime[i]:
            for multiple in range(i*i, upper_limit + 1, i):
                is_prime[multiple] = False

    return [i for i, prime in enumerate(is_prime) if prime]

