def min_word_partitions(s, wordDict):
    word_len = len(wordDict[0])
    word_set = set(wordDict)
    n = len(s)

    # DP array where dp[i] means the minimum number of partitions needed for s[:i]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i - word_len, -1, -1):
            if i - j == word_len and s[j:i] in word_set:
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n] if dp[n] != float('inf') else -1

def compress_string(s: str) -> str:
    if not s:
        return s

    compressed = []
    count = 1
    length = len(s)

    for i in range(1, length):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1] + str(count))
            count = 1

    compressed.append(s[-1] + str(count))
    compressed_string = ''.join(compressed)

    if len(compressed_string) < length:
        return compressed_string
    else:
        return s

