def fibonacci_modulo(n: int, mod: int) -> List[int]:
    if n == 0:
        return [0]
    if n == 1:
        return [0, 1]

    fib = [0, 1]
    for i in range(2, n + 1):
        fib.append((fib[-1] + fib[-2]) % mod)

    return fib

def bellman_ford(graph, source):
    """
    Implements the Bellman-Ford algorithm to detect negative-weight cycles
    in a graph and find the shortest path from a source node.

    Parameters:
    graph (dict): A dictionary representing the directed graph, with edge weights.
    source (str): The starting node.

    Returns:
    bool: True if no negative-weight cycles exist, False otherwise.
    """

    # Initialize distance to all vertices as infinite and distance to source as 0
    distance = {node: float('inf') for node in graph}
    distance[source] = 0

    # Relax edges |V|-1 times
    for _ in range(len(graph) - 1):
        for u in graph:
            for v in graph[u]:
                if distance[u] != float('inf') and distance[u] + graph[u][v] < distance[v]:
                    distance[v] = distance[u] + graph[u][v]

    # Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if distance[u] != float('inf') and distance[u] + graph[u][v] < distance[v]:
                return False  # Negative cycle detected

    return True

def longest_unique_substring(s: str, k: int) -> int:
    if k > len(s):
        return -1

    max_length = -1
    n = len(s)
    for i in range(n - k + 1):
        substring = s[i:i+k]
        if len(set(substring)) == k:
            max_length = k
            break

    return max_length

def remove_duplicate_letters(s):
    """
    Remove duplicate letters from s to ensure every letter appears once and only once,
    and the result is the smallest in lexicographical order among all possible results.
    """
    stack = []
    seen = set()
    last_occurrence = {char: idx for idx, char in enumerate(s)}

    for idx, char in enumerate(s):
        if char not in seen:
            while stack and char < stack[-1] and idx < last_occurrence[stack[-1]]:
                seen.discard(stack.pop())
            seen.add(char)
            stack.append(char)

    return ''.join(stack)

from typing import List

def ternary_search(left: int, right: int, key: int, arr: List[int]) -> int:
    if right >= left:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2

        if key < arr[mid1]:
            return ternary_search(left, mid1 - 1, key, arr)
        elif key > arr[mid2]:
            return ternary_search(mid2 + 1, right, key, arr)
        else:
            return ternary_search(mid1 + 1, mid2 - 1, key, arr)

    return -1

def shortest_subarray_with_sum_at_least_k(nums, k):
    from collections import deque

    n = len(nums)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + nums[i]

    result = n + 1
    dq = deque()

    for i in range(n + 1):
        while dq and prefix_sum[i] - prefix_sum[dq[0]] >= k:
            result = min(result, i - dq.popleft())
        while dq and prefix_sum[i] <= prefix_sum[dq[-1]]:
            dq.pop()
        dq.append(i)

    return result if result <= n else 0

def rabin_karp(word: str, text: str) -> int:
    if not word or not text or len(word) > len(text):
        return -1

    base = 256
    prime = 101
    m = len(word)
    n = len(text)

    hash_word = 0
    hash_text = 0
    h = 1

    for i in range(m - 1):
        h = (h * base) % prime

    for i in range(m):
        hash_word = (base * hash_word + ord(word[i])) % prime
        hash_text = (base * hash_text + ord(text[i])) % prime

    for i in range(n - m + 1):
        if hash_word == hash_text:
            if text[i:i + m] == word:
                return i

        if i < n - m:
            hash_text = (base * (hash_text - ord(text[i]) * h) + ord(text[i + m])) % prime
            if hash_text < 0:
                hash_text = hash_text + prime

    return -1

def is_permutation(str1: str, str2: str) -> bool:
