    return Counter(str1) == Counter(str2)

def rabin_karp_enhanced(pattern: str, text: str) -> int:
    """
    Finds the first occurrence of the pattern in the text using the Rabin-Karp algorithm.
    :param pattern: The substring to be searched.
    :param text: The text within which the pattern is to be searched.
    :return: The starting index of the first occurrence of the pattern in the text, or -1 if the pattern is not found.
    """
    if len(pattern) > len(text):
        return -1

    base = 256  # Number of characters in the input alphabet
    prime = 101  # A prime number to use for hashing

    pattern_length = len(pattern)
    text_length = len(text)

    pattern_hash = 0
    text_hash = 0
    h = 1

    for i in range(pattern_length - 1):
        h = (h * base) % prime

    for i in range(pattern_length):
        pattern_hash = (base * pattern_hash + ord(pattern[i])) % prime
        text_hash = (base * text_hash + ord(text[i])) % prime

    for i in range(text_length - pattern_length + 1):
        if pattern_hash == text_hash:
            if text[i:i + pattern_length] == pattern:
                return i

        if i < text_length - pattern_length:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + pattern_length])) % prime

            if text_hash < 0:
                text_hash += prime

    return -1

def fizzbuzz_adjacent(n: int):
    """
    Generate a modified FizzBuzz sequence and count the occurrences of 'Fizz', 'Buzz', and 'FizzBuzz'.

    Args:
    n (int): The end number (inclusive) in the range starting from 1.

    Returns:
    Tuple[List[Union[int, str]], Dict[str, int]]: A tuple containing the modified list and a dictionary of counts.
    """

    result = []
    counts = {"Fizz": 0, "Buzz": 0, "FizzBuzz": 0}

    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
            counts["FizzBuzz"] += 1
        elif i % 3 == 0:
            result.append("Fizz")
            counts["Fizz"] += 1
        elif i % 5 == 0:
            result.append("Buzz")
            counts["Buzz"] += 1
        else:
            result.append(i)

    return result, counts

def calculate_edit_distance(word_a: str, word_b: str) -> int:
    """
    Calculate the edit distance between two words using dynamic programming.
    The edit distance is the minimum number of operations (insertions, deletions, substitutions)
    required to transform word_a into word_b.
    """
    m, n = len(word_a), len(word_b)

    # Create a table to store the edit distances
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the base cases
    for i in range(m + 1):
        dp[i][0] = i  # Cost of deleting all characters from word_a is i
    for j in range(n + 1):
        dp[0][j] = j  # Cost of inserting all characters of word_b is j

    # Compute the edit distance using bottom-up dynamic programming
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word_a[i - 1] == word_b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation needed
            else:
                dp[i][j] = min(
                    dp[i - 1][j],    # Deletion
                    dp[i][j - 1],    # Insertion
                    dp[i - 1][j - 1] # Substitution
                ) + 1

    return dp[m][n]

def is_permutation(s1: str, s2: str) -> bool:
    """ 
    Check if s1 is a permutation of s2.

    Args:
    s1 (str): The first string.
    s2 (str): The second string.

    Returns:
    bool: True if s1 is a permutation of s2, False otherwise.
    """
    # If the lengths of the strings are different, they cannot be permutations
    if len(s1) != len(s2):
        return False

    # Use dictionary to count occurrences of each character in s1
    char_count = {}
    for ch in s1:
        char_count[ch] = char_count.get(ch, 0) + 1

    # Decrease count based on characters found in s2
    for ch in s2:
        if ch in char_count:
            char_count[ch] -= 1
            if char_count[ch] == 0:
                del char_count[ch]
        else:
            return False

    # If char_count is empty, s1 is a permutation of s2
    return len(char_count) == 0

def has_pair_with_sum(arr, x):
    """
    Returns True if there exists a pair of elements in the array whose sum is equal to x.
    """
    seen = set()
    for num in arr:
        if x - num in seen:
            return True
        seen.add(num)
    return False

