def insertion_sort_unique(arr):
    """
    Returns a new list containing the elements of arr sorted in ascending
    order with duplicates removed.
    """
    if not arr:
        return []

    unique_list = []
    for element in arr:
        if element not in unique_list:
            unique_list.append(element)

    # Insertion sort
    for i in range(1, len(unique_list)):
        key = unique_list[i]
        j = i - 1
        while j >= 0 and key < unique_list[j]:
            unique_list[j + 1] = unique_list[j]
            j -= 1
        unique_list[j + 1] = key

    return unique_list

from collections import deque

def shortest_path(graph, start, end):
    """
    Find the shortest path between start and end nodes in an unweighted graph.
    """
    if start not in graph or end not in graph:
        return []

    queue = deque([start])
    predecessors = {start: None}

    while queue:
        current = queue.popleft()
        if current == end:
            break
        for neighbor in graph[current]:
            if neighbor not in predecessors:
                queue.append(neighbor)
                predecessors[neighbor] = current

    if end not in predecessors:
        return []

    path = []
    curr_node = end
    while curr_node is not None:
        path.append(curr_node)
        curr_node = predecessors[curr_node]
    path.reverse()

    return path

def count_characters(words, chars):
