def count_rectangles(points):
    # Convert the list of points to a set for O(1) lookup times.
    point_set = set(map(tuple, points))
    rectangles = 0

    # Iterate over all pairs of points
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            x1, y1 = points[i]
            x2, y2 = points[j]

            if x1 != x2 and y1 != y2:  # They must form a diagonal
                if (x1, y2) in point_set and (x2, y1) in point_set:
                    rectangles += 1

    return rectangles // 2  # Each rectangle is counted twice, once for each diagonal

from typing import List
from collections import defaultdict

def find_longest_arith_seq(arr: List[int]) -> int:
    # If the array length is 1 or less, return the length of the array.
    if len(arr) <= 1:
        return len(arr)

    # Use a dictionary to store the lengths of the arithmetic sequences.
    dp = [defaultdict(int) for _ in range(len(arr))]
    max_length = 2

    for i in range(1, len(arr)):
        for j in range(i):
            diff = arr[i] - arr[j]

            # Update the dp array with the maximum length of sequence ending at i with difference diff
            if diff in dp[j]:
                dp[i][diff] = max(dp[i][diff], dp[j][diff] + 1)
            else:
                dp[i][diff] = 2

            # Update the maximum length found so far
            max_length = max(max_length, dp[i][diff])

    return max_length

def are_parentheses_balanced(expr: str) -> bool:
    """
    Returns True if the parentheses in the given expression are balanced, False otherwise.
    """
    stack = []
    for char in expr:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:  # If stack is empty, no matching opening parenthesis
                return False
            stack.pop()  # Remove the matching opening parenthesis
    return not stack  # If stack is empty, all parentheses were matched

def largest_prime(n: int) -> int:
    """
    Returns the largest prime number less than or equal to n.
    """
    if n < 2:
        return 0

    # Use the Sieve of Eratosthenes to find all prime numbers up to n
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not primes

    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    # Find the largest prime number less than or equal to n
    for i in range(n, 1, -1):
        if is_prime[i]:
            return i

    return 0

from typing import List

def increment_number(digits: List[int]) -> List[int]:
    n = len(digits)

    # Start from the last digit and proceed backwards
    for i in range(n-1, -1, -1):
        if digits[i] < 9:
            digits[i] += 1
            return digits
        else:
            digits[i] = 0

    # If all digits are 9, we need an extra leading 1
    return [1] + digits

def island_perimeter(grid):
    rows, cols = len(grid), len(grid[0])
    perimeter = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                perimeter += 4  # Start with 4 sides for each land cell

                if r > 0 and grid[r-1][c] == 1:  # Check upper cell
                    perimeter -= 2

                if c > 0 and grid[r][c-1] == 1:  # Check left cell
                    perimeter -= 2

    return perimeter

def is_strictly_increasing(lst):
    """
    Returns True if the list 'lst' is strictly increasing, False otherwise.
    """
    # An empty list or a list with a single element is considered strictly increasing
    if len(lst) <= 1:
        return True

    # Iterate over the list and check if each element is strictly
    # greater than the previous one
    for i in range(1, len(lst)):
        if lst[i] <= lst[i - 1]:
            return False
    return True

def word_pattern(pattern: str, input_string: str) -> bool:
    words = input_string.split()
    if len(pattern) != len(words):
        return False

    char_to_word = {}
    word_to_char = {}

    for p, w in zip(pattern, words):
        if p in char_to_word and char_to_word[p] != w:
            return False
        if w in word_to_char and word_to_char[w] != p:
            return False
        char_to_word[p] = w
        word_to_char[w] = p

    return True

def longest_common_substring(str1: str, str2: str) -> (int, str):
    n, m = len(str1), len(str2)
    longest_length = 0
    longest_substring = ""

    # Initialize a 2D list to keep track of the lengths of longest common suffixes
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > longest_length:
                    longest_length = dp[i][j]
                    longest_substring = str1[i - longest_length:i]
            else:
                dp[i][j] = 0

    return longest_length, longest_substring

def fibonacci_cumulative_sum(n):
    """
    Calculates the cumulative sum of Fibonacci numbers up to the given index n.

    :param n: The non-negative index up to which the cumulative sum of Fibonacci numbers is calculated.
    :return: The cumulative sum of Fibonacci numbers up to index n.
    """
    if n < 0:
        raise ValueError("Index must be a non-negative integer.")
    fib_nums = [0, 1]
    for i in range(2, n + 1):
        fib_nums.append(fib_nums[-1] + fib_nums[-2])
    return sum(fib_nums[:n+1])

def subarray_sum(nums, target):
    """
    Returns the number of subarrays that add up to the target.

    :param nums: List of integers.
    :param target: The target sum.
    :return: Number of subarrays that sum to target.
    """
    count = 0
    current_sum = 0
    prefix_sum = {0: 1}

    for num in nums:
        current_sum += num
        if (current_sum - target) in prefix_sum:
            count += prefix_sum[current_sum - target]
        if current_sum in prefix_sum:
            prefix_sum[current_sum] += 1
        else:
            prefix_sum[current_sum] = 1

    return count

from collections import Counter

def min_anagram_deletions(word1, word2):
    """
    Returns the minimum number of deletions required to make word1 and word2 anagrams of each other.
    """
    counter1 = Counter(word1)
    counter2 = Counter(word2)

    deletions = 0

    # Calculate deletions for characters in word1 that are not in word2 or have different frequencies
    for char in counter1:
        if char in counter2:
            deletions += abs(counter1[char] - counter2[char])
        else:
            deletions += counter1[char]

    # Calculate deletions for characters in word2 that are not in word1
    for char in counter2:
        if char not in counter1:
            deletions += counter2[char] 

    return deletions

def max_distance_with_same_height(nums):
