def unique_number(stream: List[Tuple[int, str]]) -> Optional[int]:
    balance = {}

    for number, sign in stream:
        if sign == '+':
            balance[number] = balance.get(number, 0) + 1
        elif sign == '-':
            balance[number] = balance.get(number, 0) - 1

    remaining_numbers = [number for number, count in balance.items() if count != 0]

    if len(remaining_numbers) == 1:
        return remaining_numbers[0]
    else:
        return None

from typing import List

def warehouse_pigeonhole_sort(identifiers: List[int]) -> List[int]:
    if not identifiers:
        return []

    min_val = min(identifiers)
    max_val = max(identifiers)
    size = max_val - min_val + 1

    pigeonholes = [0] * size

    for identifier in identifiers:
        pigeonholes[identifier - min_val] += 1

    sorted_identifiers = []
    for index in range(size):
        while pigeonholes[index] > 0:
            sorted_identifiers.append(index + min_val)
            pigeonholes[index] -= 1

    return sorted_identifiers

def find_pair_with_sum(arr, x):
    """
    Returns the indices of two distinct elements in the array such that their sum equals x,
    or -1 if no such pair exists.
    """
    # Dictionary to store the value to index mapping
    value_to_index = {}

    for i, num in enumerate(arr):
        # Calculate the complement that would add up to x
        complement = x - num
        if complement in value_to_index:
            # Return the indices in ascending order
            return (value_to_index[complement], i) if value_to_index[complement] < i else (i, value_to_index[complement])
        value_to_index[num] = i

    return -1

