    return True

from typing import List

def robust_interpolation_search(array: List[int], search_key: int) -> int:
    """
    Perform a robust interpolation search to find the index of search_key in a sorted array.
    Returns the smallest index of search_key if present, otherwise returns -1.

    Parameters:
    array (List[int]): A list of sorted integers.
    search_key (int): The integer value to search for in the array.

    Returns:
    int: The index of search_key if present; otherwise, -1.
    """
    n = len(array)
    if n == 0:
        return -1

    low = 0
    high = n - 1

    while low <= high and search_key >= array[low] and search_key <= array[high]:
        if array[high] == array[low]:
            if array[low] == search_key:
                return low
            else:
                break

        pos = low + ((high - low) // (array[high] - array[low]) * (search_key - array[low]))

        if pos < low or pos > high:
            return -1

        if array[pos] == search_key:
            while pos > low and array[pos - 1] == search_key:
                pos -= 1
            return pos

        if array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

def find_indices_with_sum(arr, x):
    """
    Returns True if there exist three distinct indices i, j, k in the array
    such that arr[i] + arr[j] + arr[k] = x. Otherwise, returns False.
    """
    n = len(arr)
    if n < 3:
        return False

    arr.sort()

    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == x:
                return True
            elif current_sum < x:
                left += 1
            else:
                right -= 1

    return False

def array_strings_are_equal(word1, word2):
