def longestEvenSubstring(s):
    """
    Returns the length of the longest substring where every character appears an even number of times.
    """
    n = len(s)
    if n == 0:
        return 0

    # dictionary to store the first occurrence of each state
    first_occurrence = {0: -1}  
    state = 0
    max_length = 0

    for i in range(n):
        # Calculate bitmask: toggle bit for current character
        state ^= (1 << (ord(s[i]) - ord('a')))

        if state in first_occurrence:
            max_length = max(max_length, i - first_occurrence[state])
        else:
            first_occurrence[state] = i

    return max_length

def min_add_to_make_valid(s: str) -> int:
    open_count = 0
    balance = 0

    for char in s:
        if char == '(':
            open_count += 1
        else:  # char == ')'
            if open_count > 0:
                open_count -= 1
            else:
                balance += 1

    return balance + open_count # balance accounts for excess ')', open_count accounts for excess '('

def is_valid(s: str) -> bool:
    """
    Checks if the input string with parentheses, brackets, and braces is valid.
    """
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def can_reach_destination(operations):
    results = []

    for op in operations:
        ai, bi, x, y, d = op
        manhattan_distance = abs(x - ai) + abs(y - bi)

        if manhattan_distance <= d and (d - manhattan_distance) % 2 == 0:
            results.append(True)
        else:
            results.append(False)

    return results

def rotate_180(matrix):
    """
    Rotates the given N x N matrix by 180 degrees.
    """
    n = len(matrix)
    for i in range(n):
        for j in range(n):
            if i * n + j < (n * n) // 2:
                opp_i, opp_j = n - 1 - i, n - 1 - j
                matrix[i][j], matrix[opp_i][opp_j] = matrix[opp_i][opp_j], matrix[i][j]

    return matrix

def search_matrix(matrix, target):
    """
    Returns True if target is found in the matrix, otherwise False.
    """
    if not matrix or not matrix[0]:
        return False

    rows = len(matrix)
    cols = len(matrix[0])
    row = rows - 1
    col = 0

    while row >= 0 and col < cols:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            row -= 1
        else:
            col += 1

    return False

def compare_versions(version1: str, version2: str) -> int:
    v1_segments = list(map(int, version1.split('.')))
    v2_segments = list(map(int, version2.split('.')))

    # Pad the shorter list with zeros (considering missing segments as 0)
    length = max(len(v1_segments), len(v2_segments))
    v1_segments.extend([0] * (length - len(v1_segments)))
    v2_segments.extend([0] * (length - len(v2_segments)))

    for v1, v2 in zip(v1_segments, v2_segments):
        if v1 > v2:
            return 1
        elif v1 < v2:
            return -1
    return 0

