def search_rotated_array(arr, target):
    """
    Searches for the target in a rotated sorted array and returns its index or -1 if not found.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if arr[mid] == target:
            return mid

        if arr[left] <= arr[mid]:  # Left half is sorted
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:  # Right half is sorted
            if arr[mid] < target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def is_match(s: str, p: str) -> bool:
    """
    Returns True if the whole string s matches the pattern p.
    """
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[0][0] = True

    for j in range(1, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]

    return dp[len(s)][len(p)]

from bisect import bisect_left

def longest_increasing_subsequence(A):
    """
    Computes the length of the longest increasing subsequence in an array of integers.
    :param A: List[int] - List of integers
    :return: int - Length of the longest increasing subsequence
    """
    if not A:
        return 0
    lis = []
    for num in A:
        pos = bisect_left(lis, num)
        if pos == len(lis):
            lis.append(num)
        else:
            lis[pos] = num
    return len(lis)

def max_len_even_odd(arr):
    """
    Returns the maximum length of a contiguous subarray that has an equal number of even and odd integers.
    """
    n = len(arr)
    max_len = 0
    diff = 0
    sum_diff = {0: -1}  # Maps diff to first occurrence index

    for i in range(n):
        if arr[i] % 2 == 0:
            diff += 1
        else:
            diff -= 1

        if diff in sum_diff:
            max_len = max(max_len, i - sum_diff[diff])
        else:
            sum_diff[diff] = i

    return max_len

