def find_longest_plateau(nums: List[int]) -> Tuple[int, int]:
    n = len(nums)
    if n == 0:
        return (0, 0)

    longest_start = 0
    longest_end = 0
    max_length = 1

    current_start = 0
    current_length = 1

    for i in range(1, n):
        if nums[i] == nums[i-1]:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                longest_start = current_start
                longest_end = i - 1
            current_start = i
            current_length = 1

    # Final check for the last plateau
    if current_length > max_length:
        longest_start = current_start
        longest_end = n - 1

    return (longest_start, longest_end)

def max_subarray(array):
    """
    Returns the maximum sum of a contiguous subarray.
    """
    max_current = max_global = array[0]

    for i in range(1, len(array)):
        max_current = max(array[i], max_current + array[i])
        if max_current > max_global:
            max_global = max_current

    return max_global

