def most_frequent_char(input_str: str) -> str:
    """
    Identify the most frequent character in a given string.
    If there's a tie, return the earliest occurring character in the string.
    """
    char_frequency = {}
    max_freq = 0
    max_char = input_str[0] if input_str else ''

    for char in input_str:
        if char in char_frequency:
            char_frequency[char] += 1
        else:
            char_frequency[char] = 1

        if char_frequency[char] > max_freq:
            max_freq = char_frequency[char]
            max_char = char
        elif char_frequency[char] == max_freq:
            # retain the max_char as is if char occurs later in the input_str
            if input_str.index(max_char) > input_str.index(char):
                max_char = char

    return max_char

def count_pairs_with_difference_k(nums, k):
    """
    Returns the number of unique pairs in the array where the absolute difference between the pairs is equal to k.
    """
    pairs = set()
    nums_set = set(nums)

    for num in nums:
        if num + k in nums_set:
            pairs.add((min(num, num + k), max(num, num + k)))
        if num - k in nums_set:
            pairs.add((min(num, num - k), max(num, num - k)))

    return len(pairs)

def longest_substr_two_distinct(s: str) -> str:
    if len(s) <= 2:
        return s

    left, right = 0, 0
    max_len = 0
    max_substr = ""
    char_freq = {}

    while right < len(s):
        char = s[right]
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1

        while len(char_freq) > 2:
            left_char = s[left]
            char_freq[left_char] -= 1
            if char_freq[left_char] == 0:
                del char_freq[left_char]
            left += 1

        if (right - left + 1) > max_len:
            max_len = right - left + 1
            max_substr = s[left:right + 1]

        right += 1

    return max_substr

def is_match(s: str, p: str) -> bool:
    """
    Returns True if the string s matches the pattern p, otherwise False.
    """

    # Create a DP table with False default values.
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Empty string matches with empty pattern.
    dp[0][0] = True

    # Empty string match with pattern p.
    for j in range(1, len(p) + 1):
        if p[j-1] == '*':
            dp[0][j] = dp[0][j-2]

    # Fill the table for remaining cases.
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j-1] == s[i-1] or p[j-1] == '.':
                dp[i][j] = dp[i-1][j-1]
            elif p[j-1] == '*':
                dp[i][j] = dp[i][j-2] or (dp[i-1][j] if p[j-2] == s[i-1] or p[j-2] == '.' else False)
            else:
                dp[i][j] = False

    return dp[len(s)][len(p)]

