def max_coins(grid):
    """
    Returns the maximum number of coins collected from the top-left to the bottom-right of the grid.

    :param grid: List[List[int]] - the 2D grid of coin values
    :return: int - maximum number of coins that can be collected
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = grid[0][0]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[m-1][n-1]

def checkSubarraySum(nums, k):
    """
    Return whether the array contains a subarray of at least size 2 that sums up to a multiple of k.
    If k is 0, check if there is at least one subarray sum that equals 0.
    """
    if k == 0:
        # Check for any two consecutive zero elements for the subarray
        for i in range(1, len(nums)):
            if nums[i] == 0 and nums[i - 1] == 0:
                return True
        return False

    # Dictionary to store the modulus of the sum up to current index
    mod_dict = {0: -1}
    cumulative_sum = 0

    for i in range(len(nums)):
        cumulative_sum += nums[i]
        current_mod = cumulative_sum % k

        if current_mod in mod_dict:
            if i - mod_dict[current_mod] > 1:
                return True
        else:
            mod_dict[current_mod] = i

    return False

