def min_path_sum(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])

    for r in range(rows):
        for c in range(cols):
            if r == 0 and c == 0:
                continue  # starting point, no previous cell to add
            elif r == 0:
                grid[r][c] += grid[r][c-1]  # only can come from the left
            elif c == 0:
                grid[r][c] += grid[r-1][c]  # only can come from above
            else:
                grid[r][c] += min(grid[r-1][c], grid[r][c-1])  # can come from left or above

    return grid[rows-1][cols-1]

