import string

def count_words(sentences: list[str]) -> dict[str, int]:
    """
    Count the occurrences of each word in the given list of sentences.

    Parameters:
    sentences (list[str]): A list of strings containing sentences.

    Returns:
    dict[str, int]: A dictionary mapping each unique word to its count.
    """
    word_count = {}
    translator = str.maketrans('', '', string.punctuation)
    for sentence in sentences:
        words = sentence.translate(translator).lower().split()
        for word in words:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1
    return word_count

def count_ways(n: int) -> int:
    """
    Computes the number of distinct ways to reach the nth step.
    This is essentially finding the (n+1)th Fibonacci number.
    """
    if n == 0:
        return 1
    elif n == 1:
        return 1

    a, b = 1, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

from collections import Counter

def count_characters(words, chars):
    """
    Returns the total length of all strings in `words` that can be formed by using the 
    letters in `chars` exactly once.
    """
    chars_count = Counter(chars)
    total_length = 0

    for word in words:
        word_count = Counter(word)
        for char in word_count:
            if word_count[char] > chars_count.get(char, 0):
                break
        else:
            total_length += len(word)

    return total_length

def max_length_subarray_two_colors(arr):
    from collections import defaultdict

    if not arr:
        return 0

    max_length = 0
    start = 0
    color_count = defaultdict(int)

    for end in range(len(arr)):
        color_count[arr[end]] += 1

        while len(color_count) > 2:
            color_count[arr[start]] -= 1
            if color_count[arr[start]] == 0:
                del color_count[arr[start]]
            start += 1

        max_length = max(max_length, end - start + 1)

    return max_length

from collections import deque

def walls_and_gates(rooms):
    """
    Modify the given 2D grid of rooms in-place to fill each empty room with 
    the distance to its nearest gate. If it is impossible to reach a gate, 
    leave the room with INF as its value.

    :param rooms: List[List[int]]
    :return: None
    """
    if not rooms or not rooms[0]:
        return

    INF = 2**31 - 1
    rows, cols = len(rooms), len(rooms[0])
    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if rooms[r][c] == 0:
                queue.append((r, c))

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            rr, cc = r + dr, c + dc
            if 0 <= rr < rows and 0 <= cc < cols and rooms[rr][cc] == INF:
                rooms[rr][cc] = rooms[r][c] + 1
                queue.append((rr, cc))

def find_last_occurrence(nums, target):
    """
    Returns the index of the last occurrence of target in nums.
    If target is not present in nums, return -1.
    """
    for i in range(len(nums) - 1, -1, -1):
        if nums[i] == target:
            return i
    return -1

from typing import List

def longest_consecutive_subsequence(numbers: List[int]) -> int:
    if not numbers:
        return 0

    numbers_set = set(numbers)
    longest_length = 0

    for num in numbers_set:
        # Check if `num` is the start of a sequence
        if num - 1 not in numbers_set:
            current_num = num
            current_length = 1

            while current_num + 1 in numbers_set:
                current_num += 1
                current_length += 1

            longest_length = max(longest_length, current_length)

    return longest_length

def find_duplicates(lst: list) -> dict:
    """
    Returns a dictionary where each key is a duplicate element from the list 
    and the value is a list of indices at which that element occurs.
    """
    element_indices = {}
    duplicates = {}

    for index, element in enumerate(lst):
        if element in element_indices:
            element_indices[element].append(index)
            duplicates[element] = element_indices[element]
        else:
            element_indices[element] = [index]

    return {k: v for k, v in duplicates.items() if len(v) > 1}

from typing import List
from collections import deque

def max_in_subarray(arr: List[int], k: int) -> List[int]:
    """
    Finds the maximum element in every subarray of size k.
    """
    if len(arr) < k:
        return []

    q = deque()
    max_elements = []

    for i in range(k):
        while q and arr[i] >= arr[q[-1]]:
            q.pop()
        q.append(i)

    for i in range(k, len(arr)):
        max_elements.append(arr[q[0]])

        while q and q[0] <= i - k:
            q.popleft()

        while q and arr[i] >= arr[q[-1]]:
            q.pop()
        q.append(i)

    max_elements.append(arr[q[0]])

    return max_elements

def iterative_binomial_coefficient(n, k):
    # Handle base case
    if k > n:
        raise ValueError('Invalid Inputs, ensure that n >= k')

    # Create a 2D table to store values of the binomial coefficients
    C = [[0] * (k+1) for _ in range(n+1)]

    # Calculate value of Binomial Coefficient in bottom-up manner
    for i in range(n+1):
        for j in range(min(i, k)+1):
            # Base cases
            if j == 0 or j == i:
                C[i][j] = 1
            # Calculate value using previously stored values
            else:
                C[i][j] = C[i-1][j-1] + C[i-1][j]

    return C[n][k]

def find_key_in_matrix(matrix, key):
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0

    # Start from the top-right corner
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == key:
            return (row + 1, col + 1)  # 1-indexed
        elif matrix[row][col] > key:
            col -= 1
        else:
            row += 1

    return None

def evaluate_postfix(expression: str) -> float:
    stack = []

    for token in expression.split():
        if token.isdigit() or (token[1:].isdigit() and token[0] == '-'):
            stack.append(float(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)

    return stack.pop()

