def find_first_non_repeating_char(s: str) -> str:
    """
    Function to find the first non-repeating character in a string.
    """
    from collections import OrderedDict

    # Create ordered dictionary to store character counts
    char_count = OrderedDict()

    # Populate the dictionary with character counts
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character with a count of 1
    for char, count in char_count.items():
        if count == 1:
            return char

    # If no non-repeating character is found
    return ""

def smallest_supersequence(str_a: str, str_b: str) -> int:
    """
    Returns the length of the smallest supersequence of two given strings.
    """
    m, n = len(str_a), len(str_b)

    # Create a 2D table to store lengths of longest common subsequence
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the table in bottom-up manner
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif str_a[i-1] == str_b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Length of the smallest supersequence
    lcs_length = dp[m][n]
    return m + n - lcs_length

def word_break(text, wordDict):
    """
    Determine if the text can be segmented into a space-separated sequence
    of one or more dictionary words.
    """
    dp = [False] * (len(text) + 1)
    dp[0] = True  # An empty string can always be segmented

    for i in range(1, len(text) + 1):
        for j in range(i):
            if dp[j] and text[j:i] in wordDict:
                dp[i] = True
                break

    return dp[len(text)]

def next_bigger(n: int) -> int:
    """
    Returns the next higher number which has the exact same set of digits as `n`.
    If no such number exists, returns `-1`.
    """
    digits = list(str(n))
    length = len(digits)

    # Step 1: Find the first digit that can be made larger by swapping with a digit to its right
    for i in range(length - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            break
    else:
        # If no such digit is found, we are at the highest permutation
        return -1

    # Step 2: Find the smallest digit on the right side of `digits[i]` that is larger than `digits[i]`
    for j in range(length - 1, i, -1):
        if digits[j] > digits[i]:
            break

    # Step 3: Swap these two digits
    digits[i], digits[j] = digits[j], digits[i]

    # Step 4: Reverse the sequence after position `i` to get the smallest possible permutation
    digits = digits[:i + 1] + digits[i + 1:][::-1]

    return int("".join(digits))

def is_anagram_of_substring(s1: str, s2: str) -> bool:
    from collections import Counter

    if len(s1) > len(s2):
        return False

    s1_counter = Counter(s1)
    window_counter = Counter(s2[:len(s1)])

    if s1_counter == window_counter:
        return True

    for i in range(len(s1), len(s2)):
        window_counter[s2[i]] += 1
        window_counter[s2[i - len(s1)]] -= 1

        if window_counter[s2[i - len(s1)]] == 0:
            del window_counter[s2[i - len(s1)]]

        if s1_counter == window_counter:
            return True

    return False

def longest_subarray_with_sum_k(arr, k):
    """
    Returns the length of the longest contiguous subarray whose sum is equal to k.
    If there is no such subarray, returns 0.
    """
    sum_map = {}
    sum_map[0] = -1  # to handle case when subarray starts from index 0
    current_sum = 0
    max_length = 0

    for i, num in enumerate(arr):
        current_sum += num

        if (current_sum - k) in sum_map:
            max_length = max(max_length, i - sum_map[current_sum - k])

        if current_sum not in sum_map:
            sum_map[current_sum] = i

    return max_length

def is_valid_calculation(calculation: str) -> bool:
    """
    Checks whether a given string is a valid calculation string.
    """

    if not calculation:
        return False

    operators = {'+', '-', '*', '/'}

    if calculation[0] in operators or calculation[-1] in operators:
        return False

    previous_char = ''
    for char in calculation:
        if char in operators:
            if previous_char in operators:
                return False
        previous_char = char

    return True

def remove_reoccurring_characters(string):
    """
    Takes a single string as input and returns a new string with all recurring characters removed.
    Maintains the order of the first occurrence of each character.
    """
    seen = set()
    result = []
    for char in string:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

import heapq

def trapRainWater(matrix):
    if not matrix or not matrix[0]:
        return 0

    n, m = len(matrix), len(matrix[0])
    visited = [[False] * m for _ in range(n)]
    heap = []

    # Push all the border cells into the heap with their heights
    for i in range(n):
        for j in [0, m-1]:
            heapq.heappush(heap, (matrix[i][j], i, j))
            visited[i][j] = True
    for j in range(1, m-1):
        for i in [0, n-1]:
            heapq.heappush(heap, (matrix[i][j], i, j))
            visited[i][j] = True

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    water_trapped = 0

    while heap:
        height, x, y = heapq.heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                water_trapped += max(0, height - matrix[nx][ny])
                heapq.heappush(heap, (max(matrix[nx][ny], height), nx, ny))
                visited[nx][ny] = True

    return water_trapped

def min_operations(initialState, finalState):
    if sorted(initialState) != sorted(finalState):
        return -1

    n = len(initialState)
    ops = 0
    j = n - 1

    for i in range(n - 1, -1, -1):
        if initialState[i] == finalState[j]:
            j -= 1
        else:
            ops += 1

    return ops

def get_lexicographically_largest_string(text):
