    count = 1

    for char in data[1:]:
        if char == current_char:
            count += 1
            if count == 10:
                result.append(f"{current_char}9")
                count = 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    result.append(f"{current_char}{count}")

    return "".join(result)

