def length_of_longest_substring_k_distinct(s, k):
    """
    Returns the length of the longest contiguous substring with exactly k distinct characters.
    If there is no such substring, returns -1.
    """
    if k == 0:
        return -1

    left = 0
    max_length = -1
    char_map = {}

    for right in range(len(s)):
        char_map[s[right]] = char_map.get(s[right], 0) + 1

        while len(char_map) > k:
            char_map[s[left]] -= 1
            if char_map[s[left]] == 0:
                del char_map[s[left]]
            left += 1

        if len(char_map) == k:
            max_length = max(max_length, right - left + 1)

    return max_length

def longest_good_substring(s):
    """
    Returns the length of the longest good substring in s.
    A good substring has an equal number of 'a's and 'b's.
    """
    max_len = 0
    n = len(s)

    for i in range(n):
        count_a = count_b = 0
        for j in range(i, n):
            if s[j] == 'a':
                count_a += 1
            elif s[j] == 'b':
                count_b += 1
            if count_a == count_b:
                max_len = max(max_len, j - i + 1)

    return max_len

from typing import List

def house_robber(houses: List[int]) -> int:
    if not houses:
        return 0
    elif len(houses) == 1:
        return houses[0]

    previous_two = houses[0]
    previous_one = max(houses[0], houses[1])

    for i in range(2, len(houses)):
        current = max(previous_one, previous_two + houses[i])
        previous_two = previous_one
        previous_one = current

    return previous_one

def find_longest_divisible_subsequence(nums):
    """
    Finds the length of the longest subsequence such that each element in the subsequence is divisible by the previous one.
    :param nums: List of integers
    :return: Length of the longest divisible subsequence
    """
    if not nums:
        return 0

    # Sort the array
    nums.sort()
    n = len(nums)

    # dp array to hold the longest subsequence length ending at each element
    dp = [1] * n

    # Iterate through the array to build up the dp array
    for i in range(1, n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

from typing import List, Tuple, Optional

def find_pair_with_sum(nums: List[int], target: int) -> Optional[Tuple[int, int]]:
    """
    Finds the indices of the two numbers in the array that add up to the target integer.
    """
    num_to_index = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], i)
        num_to_index[num] = i

    return None  # In case no valid pair is found, although the prompt guarantees one solution

def remove_adjacent_pairs(s):
    """
    Removes pairs of adjacent equal characters from the string s until no more pairs can be removed.
    Returns the resulting string.
    """
    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

def next_bigger(num: int) -> int:
    """
    Finds the next bigger number using the same digits, if possible. If not, returns -1.
    """
    digits = list(str(num))
    length = len(digits)

    # Step 1: Find the rightmost digit that is smaller than its next digit
    for i in range(length - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            break
    else:
        return -1

    # Step 2: Find the smallest digit on the right side of (i-th digit) which is larger than digits[i]
    for j in range(length - 1, i, -1):
        if digits[j] > digits[i]:
            break

    # Step 3: Swap the found digits[i] and digits[j]
    digits[i], digits[j] = digits[j], digits[i]

    # Step 4: Reverse the sequence after the (i-th digit) to get the smallest possible number
    digits = digits[:i + 1] + sorted(digits[i + 1:])

    return int(''.join(digits))

from typing import List

def ternary_search_range(arr: List[int], left: int, right: int, key: int) -> int:
    """
    Performs a ternary search to find `key` in `arr` within the range [left, right].
    """
    while right >= left:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2

        if key < arr[mid1]:
            right = mid1 - 1
        elif key > arr[mid2]:
            left = mid2 + 1
        else:
            left = mid1 + 1
            right = mid2 - 1

    return -1

def binary_search(arr, target):
    if not arr:
        return -1

    left, right = 0, len(arr) - 1
    ascending = arr[left] < arr[right]

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        elif ascending:
            if target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if target > arr[mid]:
                right = mid - 1
            else:
                left = mid + 1

    return -1

def longest_subarray_with_sum(nums, target_sum):
    sum_indices = {0: -1}  # Dictionary to store cumulative sums and their earliest index
    max_length = 0
    cumulative_sum = 0

    for i in range(len(nums)):
        cumulative_sum += nums[i]

        if cumulative_sum - target_sum in sum_indices:
            max_length = max(max_length, i - sum_indices[cumulative_sum - target_sum])

        if cumulative_sum not in sum_indices:
            sum_indices[cumulative_sum] = i

    return max_length

def most_frequent(nums):
    """
    Returns the most frequent element in the list of integers.
    If the list is empty, returns None.
    If there are multiple elements with the same highest frequency, returns any one of them.
    """
    if not nums:
        return None

    frequency = {}

    for num in nums:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    most_frequent_element = max(frequency, key=frequency.get)

    return most_frequent_element

def min_slicing_operations(nums):
    """
    Returns the minimum number of slicing operations required to sort nums in non-decreasing order.
    """
    if not nums:
        return 0

    sorted_nums = sorted(nums)
    n = len(nums)

    start, end = None, None

    for i in range(n):
        if nums[i] != sorted_nums[i]:
            if start is None:
                start = i
            end = i

    if start is None:
        return 0  # Already sorted

    if nums[start:end+1] == sorted_nums[start:end+1][::-1]:
        return 1

    return 2

def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)

    # dp[i][j] will be True if the first i characters in s match the first j characters in p
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True  # Both strings are empty

    # Initialize dp for patterns with '*' where they could match an empty string
    for j in range(2, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill up the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] and (p[j - 2] == s[i - 1] or p[j - 2] == '.'))

    return dp[m][n]

def find_min_removals(s: str) -> tuple:
    """
    Given a string of parentheses, determine the minimum number of parentheses
    to remove to make it valid and return the resulting valid string.

    Args:
    s (str): A string containing only '(' and ')'.

    Returns:
    tuple: A tuple containing two elements:
           - An integer count of removed parentheses.
           - The resulting valid string.
    """
    stack = []
    indices_to_remove = set()

    # Determine the indices of invalid parentheses
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                indices_to_remove.add(i)

    while stack:
        indices_to_remove.add(stack.pop())

    # Build the resulting valid string
    result = []
    for i, char in enumerate(s):
        if i not in indices_to_remove:
            result.append(char)

    return (len(indices_to_remove), "".join(result))

def is_match(s: str, p: str) -> bool:
    """
    Returns True if the pattern p matches the entire string s, otherwise returns False.
    The pattern p can contain '.' which matches any single character and 
    '*' which matches zero or more of the preceding element.
    """
    m, n = len(s), len(p)

    # dp[i][j] will be True if s[:i] matches p[:j], else False
    dp = [[False] * (n+1) for _ in range(m+1)]

    # Empty string and empty pattern match
    dp[0][0] = True

    # Handle patterns with '*', since '*' can match zero preceding elements
    for j in range(1, n+1):
        if p[j-1] == '*':
            dp[0][j] = dp[0][j-2]

    for i in range(1, m+1):
        for j in range(1, n+1):
            if p[j-1] == '.' or p[j-1] == s[i-1]:
                dp[i][j] = dp[i-1][j-1]
            elif p[j-1] == '*':
                dp[i][j] = dp[i][j-2] or (dp[i-1][j] if p[j-2] == s[i-1] or p[j-2] == '.' else False)

    return dp[m][n]

def find_repeated_substrings(s):
    """
    Finds all the repeated substrings with the maximum length in the given string.

    Parameters:
    s (str): Input string of lowercase English letters.

    Returns:
    List[str]: List of repeated substrings with maximum length in order of their first appearance.
    """
    n = len(s)
    substr_freq = {}
    max_len = 0

    # Generate all substrings and their frequencies
    for length in range(1, n):
        for i in range(n - length + 1):
            substr = s[i:i + length]
            if substr in substr_freq:
                substr_freq[substr] += 1
            else:
                substr_freq[substr] = 1

    for substr, freq in substr_freq.items():
        if freq > 1 and len(substr) > max_len:
            max_len = len(substr)

    # Collect only the substrings with maximum length and frequency > 1
    result = []
    for substr, freq in substr_freq.items():
        if freq > 1 and len(substr) == max_len:
            result.append(substr)

    return result

def max_cookies(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0]*n for _ in range(m)]

    dp[0][0] = grid[0][0]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[m-1][n-1]

def remove_min_chars_to_unique(s):
    """
    Remove the minimum number of characters from the string s so that all the remaining characters are unique.
    Returns a resulting string with all distinct characters in their original order.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

def does_follow_pattern(pattern: str, string: str) -> bool:
    words = string.split()

    if len(pattern) != len(words):
        return False

    char_to_word = {}
    word_to_char = {}

    for char, word in zip(pattern, words):
        if char in char_to_word:
            if char_to_word[char] != word:
                return False
        else:
            if word in word_to_char:
                return False
            char_to_word[char] = word
            word_to_char[word] = char

    return True

from typing import List

def generate_primes(n: int) -> List[int]:
    """
    Generate a list of prime numbers up to and including the given number n using the Sieve of Eratosthenes algorithm.

    :param n: A non-negative integer
    :return: A list of prime numbers less than or equal to n
    :raises ValueError: If input is not a non-negative integer
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer")

    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not prime numbers

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n + 1, start):
                is_prime[multiple] = False

    return [num for num in range(2, n + 1) if is_prime[num]]

