        return 0
    return text.find(pattern)

def modular_exponentiation(base: int, exponent: int, mod: int) -> int:
    if mod == 1:
        return 0
    result = 1
    base = base % mod
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % mod
        exponent = exponent >> 1
        base = (base * base) % mod
    return result

def min_operations_to_make_equal(s1, s2):
    """
    Returns the minimum number of operations required to make s1 and s2 equal.
    An operation consists of removing one character from either string.
    """
    m, n = len(s1), len(s2)

    # Create a table to store the length of longest common subsequence of substrings
    # lcs_length[i][j] will be the length of lcs of s1[0..i-1] & s2[0..j-1]
    lcs_length = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the lcs_length table from bottom right corner
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                lcs_length[i][j] = lcs_length[i - 1][j - 1] + 1
            else:
                lcs_length[i][j] = max(lcs_length[i - 1][j], lcs_length[i][j - 1])

    # The number of operations needed is the sum of deletions needed
    return (m - lcs_length[m][n]) + (n - lcs_length[m][n])

def next_bigger(num: int) -> int:
    digits = list(str(num))
    n = len(digits)

    # Step 1: Find the rightmost digit which is smaller than its next digit
    for i in range(n - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            break
    else:
        return -1  # If no such digit is found, return -1

    # Step 2: Find the smallest digit on the right side of the above found digit which is greater than the found digit
    for j in range(n - 1, i, -1):
        if digits[j] > digits[i]:
            # Step 3: Swap these two digits
            digits[i], digits[j] = digits[j], digits[i]
            break

    # Step 4: Reverse the digits after the swapped position
    digits = digits[:i + 1] + sorted(digits[i + 1:])

    return int("".join(digits))

def is_bijective_pattern(pattern: str, string: str) -> bool:
    # Split the words in the string
    words = string.split()

    # If lengths of pattern and words do not match, return False
    if len(pattern) != len(words):
        return False

    # Dictionaries to store the mapping of pattern to word and word to pattern    
    pattern_to_word = {}
    word_to_pattern = {}

    # Iterate through each character in pattern and corresponding word
    for char, word in zip(pattern, words):
        # Check if we have a mapping from pattern to word
        if char in pattern_to_word:
            # If there is a mismatch, return False
            if pattern_to_word[char] != word:
                return False
        else:
            # If there is no mapping, create one
            pattern_to_word[char] = word

        # Check if we have a mapping from word to pattern
        if word in word_to_pattern:
            # If there is a mismatch, return False
            if word_to_pattern[word] != char:
                return False
        else:
            # If there is no mapping, create one
            word_to_pattern[word] = char

    return True

