from typing import List

def min_energy_cost(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        raise ValueError("Grid is empty")

    rows, cols = len(grid), len(grid[0])

    for row in grid:
        if any(cell < 0 for cell in row):
            raise ValueError("Energy cost cannot be negative")

    # Create a DP table to store the minimum energy cost at each cell
    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = grid[0][0]

    # Initialize the first row
    for j in range(1, cols):
        dp[0][j] = dp[0][j - 1] + grid[0][j]

    # Initialize the first column
    for i in range(1, rows):
        dp[i][0] = dp[i - 1][0] + grid[i][0]

    # Fill in the rest of the dp table
    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]

    return dp[rows - 1][cols - 1]

def max_overlapping_flights(flights):
    events = []

    for start, end in flights:
        events.append((start, 'start'))
        events.append((end, 'end'))

    # Sort events, by time, with 'end' events coming before 'start'
    events.sort(key=lambda x: (x[0], x[1] == 'start'))

    max_overlap = 0
    current_overlap = 0

    for event in events:
        if event[1] == 'start':
            current_overlap += 1
            max_overlap = max(max_overlap, current_overlap)
        else:
            current_overlap -= 1

    return max_overlap

