def max_coins(matrix):
    """
    Returns the maximum number of coins that can be collected starting from top-left to bottom-right of the matrix.
    Only movements to the right and downward are allowed.
    """
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = matrix[0][0]

    for i in range(1, n):
        dp[0][i] = dp[0][i-1] + matrix[0][i]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + matrix[i][0]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    return dp[m-1][n-1]

def min_path_sum(grid: list) -> int:
    """
    Returns the minimum path sum from the top-left to the bottom-right corner of the given grid.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]

    dp[0][0] = grid[0][0]

    for i in range(1, rows):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    for j in range(1, cols):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[-1][-1]

