def count_rectangles(w: int, h: int) -> int:
    """
    Compute the total number of rectangles of all possible sizes that can 
    be formed within a rectangle of width `w` and height `h`.
    """
    total_rectangles = 0
    for width in range(1, w + 1):
        for height in range(1, h + 1):
