def efficient_cocktail_shaker_sort(arr):
    """
    Sorts an array using an optimized Cocktail Shaker Sort algorithm.
    """
    if not arr:
        return []

    n = len(arr)
    start = 0
    end = n - 1
    while start <= end:
        swapped = False

        # Forward pass
        for i in range(start, end):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True
        if not swapped:
            break
        end -= 1

        swapped = False
        # Backward pass
        for i in range(end, start, -1):
            if arr[i] < arr[i - 1]:
                arr[i], arr[i - 1] = arr[i - 1], arr[i]
                swapped = True
        if not swapped:
            break
        start += 1

    return arr

def common_elements(arr1: list[int], arr2: list[int]) -> list[int]:
