    while i < len(arr1) and j < len(arr2):
        if arr1[i] == arr2[j]:
            common.append(arr1[i])
            i += 1
            j += 1
        elif arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1

    return common

def unique_paths_with_obstacles(grid):
    """
    Returns the number of unique paths from top-left corner to bottom-right corner
    in a grid with given obstacles.

    :param grid: List[List[int]] -- 2D grid of integers where -1 represents a blocked cell.
    :return: int -- number of unique paths avoiding blocked cells.
    """
    if not grid or grid[0][0] == -1 or grid[-1][-1] == -1:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == -1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

