    c = 1
    i = start + 1
    while ( i <= end ) :
        if ( X [ i ] == open ) :
            c += 1
        elif ( X [ i ] == close ) :
            c -= 1
        if ( c == 0 ) :
            return i
        i += 1
    return i
def matchingOpening ( X , start , end , open , close ) :
    c = - 1
    i = end - 1
    while ( i >= start ) :
        if ( X [ i ] == open ) :
            c += 1
        elif ( X [ i ] == close ) :
            c -= 1
        if ( c == 0 ) :
            return i
        i -= 1
    return - 1
