def getBinaryRep ( N , num_of_bits ) :
    r = " " ;
    num_of_bits -= 1
    while ( num_of_bits >= 0 ) :
        if ( N & ( 1 << num_of_bits ) ) :
            r += ( "1" ) ;
        else :
