def factors ( n , k ) :
    v = [ ] ;
    while ( n % 2 == 0 ) :
        v . append ( 2 ) ;
        n //= 2 ;
    if ( len ( v ) >= k ) :
        return True ;
    for i in range ( 3 , int ( n ** ( 1 / 2 ) ) , 2 ) :
        while ( n % i == 0 ) :
            n = n // i ;
            v . append ( i ) ;
        if ( len ( v ) >= k ) :
            return True ;
    if ( n > 2 ) :
        v . append ( n ) ;
    if ( len ( v ) >= k ) :
        return True ;
    return False ;
