def modFact ( n , p ) :
    if ( n >= p ) :
        return 0
    res = 1
    isPrime = [ 1 ] * ( n + 1 )
    i = 2
    while ( i * i <= n ) :
        if ( isPrime [ i ] ) :
            for j in range ( 2 * i , n , i ) :
                isPrime [ j ] = 0
        i += 1
    for i in range ( 2 , n ) :
        if ( isPrime [ i ] ) :
            k = largestPower ( n , i )
