def minimumAND ( arr , n , k ) :
    bit = [ 0 ] * 32 ;
    for i in range ( k ) :
        for j in range ( 32 ) :
            if ( ( arr [ i ] & ( 1 << j ) ) > 0 ) :
                bit [ j ] += 1 ;
    min_and = build_num ( bit , k ) ;
    for i in range ( k , n ) :
        for j in range ( 32 ) :
            if ( ( arr [ i - k ] & ( 1 << j ) ) > 0 ) :
                bit [ j ] -= 1 ;
        for j in range ( 32 ) :
            if ( ( arr [ i ] & ( 1 << j ) ) > 0 ) :
                bit [ j ] += 1 ;
        min_and = min ( build_num ( bit , k ) , min_and ) ;
    return min_and ;
