    return ( N * ( N + 1 ) ) // 2
def printKthCharInConcatSubstring ( string : str , K : int ) -> str :
    n = len ( string )
    suffixArr = buildSuffixArray ( string , n )
    lcp = kasai ( string , suffixArr )
    for i in range ( len ( lcp ) ) :
        charToSkip = ( sumOfFirstN ( n - suffixArr [ i ] ) - sumOfFirstN ( lcp [ i ] ) )
        if ( K <= charToSkip ) :
            for j in range ( lcp [ i ] + 1 , ( n - suffixArr [ i ] ) + 1 ) :
                curSubstringLen = j
                if ( K <= curSubstringLen ) :
                    return string [ ( suffixArr [ i ] + K - 1 ) ]
                else :
                    K -= curSubstringLen
            break
        else :
            K -= charToSkip
