def maxNormalSubstring ( P , Q , K , N ) :
    if ( K == 0 ) :
        return 0
    count = 0
    left , right = 0 , 0
    ans = 0
    while ( right < N ) :
        while ( right < N and count <= K ) :
            pos = ord ( P [ right ] ) - ord ( ' a ' )
            if ( Q [ pos ] == '0' ) :
                if ( count + 1 > K ) :
                    break
                else :
                    count += 1
            right += 1
            if ( count <= K ) :
                ans = max ( ans , right - left )
        while ( left < right ) :
            pos = ord ( P [ left ] ) - ord ( ' a ' )
            left += 1
            if ( Q [ pos ] == '0' ) :
                count -= 1
            if ( count < K ) :
                break
    return ans
