class Graph :
    def __init__ ( self , V ) :
        self . V = V
        self . adj = [ [ ] for i in range ( V ) ]
    def addEdge ( self , s , d ) :
        self . adj [ s ] . append ( d )
        self . adj [ d ] . append ( s )
    def BFS ( self , s , d ) :
        if ( s == d ) :
            return 0
        level = [ - 1 ] * self . V
        queue = [ ]
        level [ s ] = 0
        queue . append ( s )
        while ( len ( queue ) != 0 ) :
            s = queue . pop ( )
            i = 0
            while i < len ( self . adj [ s ] ) :
                if ( level [ self . adj [ s ] [ i ] ] < 0 or level [ self . adj [ s ] [ i ] ] > level [ s ] + 1 ) :
                    level [ self . adj [ s ] [ i ] ] = level [ s ] + 1
                    queue . append ( self . adj [ s ] [ i ] )
                i += 1
        return level [ d ]
