def MinimumPath ( M ) :
    global N
    s , d = None , None
    V = N * N + 2
    g = Graph ( V )
    k = 1
    for i in range ( N ) :
        for j in range ( N ) :
            if ( M [ i ] [ j ] != 0 ) :
                if ( isSafe ( i , j + 1 , M ) ) :
                    g . addEdge ( k , k + 1 )
                if ( isSafe ( i , j - 1 , M ) ) :
                    g . addEdge ( k , k - 1 )
                if ( j < N - 1 and isSafe ( i + 1 , j , M ) ) :
                    g . addEdge ( k , k + N )
                if ( i > 0 and isSafe ( i - 1 , j , M ) ) :
                    g . addEdge ( k , k - N )
            if ( M [ i ] [ j ] == 1 ) :
                s = k
            if ( M [ i ] [ j ] == 2 ) :
                d = k
            k += 1
    return g . BFS ( s , d )
