def KvisibleFromLeft ( N , K ) :
    if ( dp [ N ] [ K ] != - 1 ) :
        return dp [ N ] [ K ]
    if ( N == K ) :
        dp [ N ] [ K ] = 1
        return dp [ N ] [ K ]
    if ( K == 1 ) :
        ans = 1
        for i in range ( 1 , N ) :
            ans *= i
        dp [ N ] [ K ] = ans
        return dp [ N ] [ K ]
    dp [ N ] [ K ] = KvisibleFromLeft ( N - 1 , K - 1 ) + ( N - 1 ) * KvisibleFromLeft ( N - 1 , K )
    return dp [ N ] [ K ]
