def minOperations ( nums , x ) :
    if sum ( nums ) < x :
        return - 1
    ans = math . inf
    l , r = len ( nums ) - 1 , len ( nums )
    x -= sum ( nums )
    while l >= 0 :
        if x <= 0 :
            x += nums [ l ]
            l -= 1
        if x > 0 :
            r -= 1
            x -= nums [ r ]
        if x == 0 :
