                L [ i ] [ j ] = 0 ;
            elif ( X [ i - 1 ] == Y [ j - 1 ] ) :
                L [ i ] [ j ] = L [ i - 1 ] [ j - 1 ] + 1 ;
            else :
                L [ i ] [ j ] = max ( L [ i - 1 ] [ j ] , L [ i ] [ j - 1 ] ) ;
    index = L [ m ] [ n ] ;
    lcs = [ " " ] * ( index + 1 )
    i , j = m , n
    while ( i > 0 and j > 0 ) :
        if ( X [ i - 1 ] == Y [ j - 1 ] ) :
            lcs [ index - 1 ] = X [ i - 1 ]
            i -= 1
            j -= 1
            index -= 1
        elif ( L [ i - 1 ] [ j ] > L [ i ] [ j - 1 ] ) :
            i -= 1
        else :
            j -= 1
    ans = " "
