                    if Matrix [ i ] [ row ] != 0 :
                        self . swap ( Matrix , row , i , rank )
                        reduce = False
                        break
                if reduce :
                    rank -= 1
                    for i in range ( 0 , self . R , 1 ) :
                        Matrix [ i ] [ row ] = Matrix [ i ] [ rank ]
                row -= 1
