    for i in range ( n - 1 , - 1 , - 1 ) :
        output [ count [ ( arr [ i ] // exp ) % n ] - 1 ] = arr [ i ]
        count [ ( arr [ i ] // exp ) % n ] -= 1
    for i in range ( n ) :
