        ans += " Empty   String "
        return ans
    single_digits = [ " zero " , " one " , " two " , " three " , " four " , " five " , " six " , " seven " , " eight " , " nine " ]
    two_digits = [ " " , " ten " , " eleven " , " twelve " , " thirteen " , " fourteen " , " fifteen " , " sixteen " , " seventeen " , " eighteen " , " nineteen " ]
    tens_multiple = [ " " , " " , " twenty " , " thirty " , " forty " , " fifty " , " sixty " , " seventy " , " eighty " , " ninety " ]
    tens_power = [ " hundred " , " thousand " ]
    if ( length == 1 ) :
        ans += single_digits [ ord ( num [ 0 ] ) - ord ( '0' ) ]
        return ans
    x = 0
    while ( x < len ( num ) ) :
        if ( length >= 3 ) :
            if ( num [ x ] - '0' != 0 ) :
                ans += single_digits [ ord ( num [ x ] ) - ord ( '0' ) ]
                ans += "   "
                ans += tens_power [ len - 3 ]
                ans += "   "
            length -= 1
        else :
            if ( ord ( num [ x ] ) - ord ( '0' ) == 1 ) :
                sum = ( ord ( num [ x ] ) - ord ( '0' ) + ord ( num [ x ] ) - ord ( '0' ) )
                ans += two_digits [ sum ]
                return ans
            elif ( ord ( num [ x ] ) - ord ( '0' ) == 2 and ord ( num [ x + 1 ] ) - ord ( '0' ) == 0 ) :
                ans += " twenty "
                return ans
            else :
                i = ( ord ( num [ x ] ) - ord ( '0' ) )
                if ( i > 0 ) :
                    ans += tens_multiple [ i ]
                    ans += "   "
                else :
                ans += " "
                x += 1
                if ( ord ( num [ x ] ) - ord ( '0' ) != 0 ) :
                    ans += single_digits [ ord ( num [ x ] ) - ord ( '0' ) ]
        x += 1
    return " "
