    countOpen , countClosed = 0 , 0
    countSymbol = 0
    for i in range ( len ( sequence ) ) :
        if ( sequence [ i ] == ' ) ' ) :
            countClosed += 1
            if ( len ( stack_ ) == 0 ) :
                return False
            else :
                del stack_ [ - 1 ]
        else :
            if ( sequence [ i ] == ' $ ' ) :
                countSymbol += 1
            else :
                countOpen += 1
            stack_ . append ( sequence [ i ] )
    for i in range ( len ( sequence ) - 1 , - 1 , - 1 ) :
        if ( sequence [ i ] == ' ( ' ) :
            if ( len ( stack2_ ) == 0 ) :
                return False
            else :
                del stack2_ [ - 1 ]
        else :
            stack2_ . append ( sequence [ i ] )
    extra = abs ( countClosed - countOpen )
    if ( countSymbol < extra ) :
        return False
    else :
        countSymbol -= extra
        if ( countSymbol % 2 == 0 ) :
            return True
    return False
