def findMinCost ( strr , pos ) :
    n = len ( strr )
    if ( pos >= n / 2 ) :
        strr = strr [ : : - 1 ]
        pos = n - pos - 1
    left , right = pos , pos
    for i in range ( pos , - 1 , - 1 ) :
        if ( strr [ i ] != strr [ n - i - 1 ] ) :
            left = i
    for i in range ( pos , n // 2 ) :
        if ( strr [ i ] != strr [ n - i - 1 ] ) :
            right = i
    ans = 0
    for i in range ( left , right + 1 ) :
        if ( strr [ i ] != strr [ n - i - 1 ] ) :
            ans += 1
    dis = ( min ( ( 2 * ( pos - left ) + ( right - pos ) ) , ( 2 * ( right - pos ) + ( pos - left ) ) ) )
    ans = ans + dis
    return ans
