def pushBoxes ( S ) :
    N = len ( S )
    force = [ 0 ] * N
    f = 0
    for i in range ( 0 , N ) :
        if S [ i ] == ' R ' :
            f = N
        elif S [ i ] == ' L ' :
            f = 0
        else :
            f = max ( f - 1 , 0 )
        force [ i ] += f
    f = 0
    for i in range ( N - 1 , - 1 , - 1 ) :
        if S [ i ] == ' L ' :
            f = N
        elif S [ i ] == ' R ' :
            f = 0
        else :
            f = max ( f - 1 , 0 )
        force [ i ] -= f
    return " " . join ( ' . ' if f == 0 else ' R ' if f > 0 else ' L ' for f in force )
