def phi ( n ) :
    result = n
    for p in range ( 2 , n ) :
        if p * p > n :
            break
        if ( n % p == 0 ) :
            while ( n % p == 0 ) :
                n //= p
            result -= result // p
    if ( n > 1 ) :
        result -= result // n
    return result
