class Node :
    def __init__ ( self ) :
        self . data = 0
        self . next = None
def removeLeadingZeros ( a ) :
    if ( a != None and a . data == 0 ) :
        return removeLeadingZeros ( a . next ) ;
    else :
        return a ;
def getSize ( a ) :
    sz = 0 ;
    while ( a != None ) :
        a = a . next ;
        sz += 1
    return sz ;
def push ( head_ref , new_data ) :
    new_node = Node ( )
    new_node . data = new_data ;
    new_node . next = ( head_ref ) ;
    ( head_ref ) = new_node ;
    return head_ref
def compare ( a , b ) :
    a = removeLeadingZeros ( a ) ;
    b = removeLeadingZeros ( b ) ;
    lenA = getSize ( a ) ;
    lenB = getSize ( b ) ;
    if ( lenA > lenB ) :
        return 1 ;
    elif ( lenB > lenA ) :
        return - 1 ;
    while ( a != None and b != None ) :
        if ( a . data > b . data ) :
            return 1 ;
        elif ( a . data < b . data ) :
            return - 1 ;
        a = a . next ;
        b = b . next ;
    return 0 ;
