def findWays ( nums , S ) :
    sum = 0
    for i in range ( len ( nums ) ) :
        sum += nums [ i ]
    memo = [ [ - sys . maxsize - 1 for i in range ( 2 * sum + 1 ) ] for j in range ( len ( nums ) + 1 ) ]
