def dfs ( memo , nums , S , curr_sum , index , sum ) :
    if ( index == len ( nums ) ) :
        if ( S == curr_sum ) :
            return 1
        else :
            return 0
    if ( memo [ index ] [ curr_sum + sum ] != - sys . maxsize - 1 ) :
        return memo [ index ] [ curr_sum + sum ]
    ans = ( dfs ( memo , nums , index + 1 , curr_sum + nums [ index ] , S , sum ) + dfs ( memo , nums , index + 1 , curr_sum - nums [ index ] , S , sum ) )
    memo [ index ] [ curr_sum + sum ] = ans
    return ans
