            while ( i >= 0 and k < n ) :
                if A [ i ] + A [ k ] == 2 * A [ j ] :
                    llap [ j ] = max ( llap [ k ] + 1 , llap [ j ] )
                    ans = max ( ans , llap [ j ] )
                    i -= 1
                    k += 1
                elif A [ i ] + A [ k ] < 2 * A [ j ] :
                    k += 1
                else :
                    i -= 1
