    if ( n <= 0 ) :
        return 0
    fibo = [ 0 ] * ( n + 1 )
    fibo [ 0 ] = 0
    fibo [ 1 ] = 1
    sum = pow ( fibo [ 0 ] , 2 ) + pow ( fibo [ 1 ] , 2 )
