    dp = [ 0 for _ in range ( len ( s ) ) ]
    dp [ 0 ] = 1
    pre = 0
    for i in range ( 1 , len ( s ) ) :
        if ( i >= L ) :
            pre += dp [ i - L ]
        if ( i > R ) :
            pre -= dp [ i - R - 1 ]
        dp [ i ] = ( pre > 0 ) and ( s [ i ] == '0' )
    return dp [ len ( s ) - 1 ]
